ull potence( ull base, ull exp ){
    if (exp == 0) return 1;
    if (exp == 1) return base;
    ull half = potence(base, exp/2);
    return half*half*potence(base, exp%2);    
}

int main() {   
    ios_base::sync_with_stdio(0);
    int a, c;
    cin >> a >> c;
    ull exp = 0;
    ull result = 0;
    static ull base = 3;
    while ( !(a == 0 && c == 0) ){
          int b = (( c%base - a%base )+ base)%base;
          result += b*potence(base,exp++);
          a /= base;
          c /= base;
    }    
    cout << result;
}

