int go(int t, int v){
	//~ if(v > 100*d) return -INF;
	if(t == 1) 	return v==vi?v:-INF;  

	int &ref = pd[t][v];
	if(ref != -1) return ref;
	ref = v+go(t-1,v);
	for(int i = 1 ; i <= d ; ++i){
		if(v-i>=0) ref = max(ref,v+go(t-1,v-i));
		ref = max(ref,v+go(t-1,v+i));
	}
	return ref;
}

