#include <bits/stdc++.h>
using namespace std;
long long n,k,m;
long long dp[1005][10][100][2];
long long dfs(int L,int be,int mod,bool flag,int mul)
{
    long long ans=0;
    if(L==n)return flag&&be!=0;
    if(dp[L][be][mod][flag]!=-1)return dp[L][be][mod][flag];
    for(int i=0;i<=9;i++)
    {
        int next=(mul*i+mod)%k;
        ans=(ans+dfs(L+1,i,next,flag||(next==0&&i>0),mul*10%k))%m;
    }
    return dp[L][be][mod][flag]=ans;
}
int main()
{
    memset(dp,-1,sizeof(dp));
    cin>>n>>k>>m;
    cout<<dfs(0,0,0,0,1)<<endl;
    return 0;
}

