typedef long long ll;
ll INF=1000000000010;
char oper[10];
ll func2(ll a,ll b) {
	if(oper[2]=='+') return a+b;
	return a*b;
}  
ll func3(ll a,ll b,ll c) {
	ll ans=INF;
	if(oper[1]=='+') {
		ans=min(ans,func2(a+b,c));
		ans=min(ans,func2(b+c,a));
		ans=min(ans,func2(a+c,b));
	}
	else {
		ans=min(ans,func2(a*b,c));
		ans=min(ans,func2(b*c,a));
		ans=min(ans,func2(a*c,b));
	}
	return ans;
}
ll func4(ll a,ll b,ll c,ll d) {
	ll ans=INF;
	if(oper[0]=='+') {
		ans=min(ans,func3(a+b,c,d));
		ans=min(ans,func3(b+c,a,d));
		ans=min(ans,func3(a+c,b,d));
		ans=min(ans,func3(a+d,c,b));
		ans=min(ans,func3(b+d,a,c));
		ans=min(ans,func3(c+d,a,b));
	}
	else {
		ans=min(ans,func3(a*b,c,d));
		ans=min(ans,func3(b*c,a,d));
		ans=min(ans,func3(a*c,b,d));
		ans=min(ans,func3(a*d,b,c));
		ans=min(ans,func3(b*d,a,c));
		ans=min(ans,func3(c*d,a,b));
	}
	return ans;
}
