typedef long long ll;
using namespace std;
int main() {
    ll n, L;
    cin >> n >> L;
    vector<ll> cost(34, 4e18);
    for(int i = 0; i < n; i++)
        cin >> cost[i];
    for(int i = 1; i < 34; i++) {
        cost[i] = min(cost[i], cost[i-1]*2);
    }
    auto compute = [&] (ll x) {
        ll idx = 0, res = 0;
        while(x > 0) {
            if (x % 2 == 1)
                res += cost[idx];
            x /= 2;
            idx += 1;
        }
        return res;
    };
    ll L2 = L;
    ll ans = compute(L2);
    while(L2 <= max(L*2, 1LL<<(n+1))) {
        L2 += L2 & (-L2);
        // cout << "res " << compute(L2)
        ans = min(ans, compute(L2));

    }
    cout << ans << endl;
    return 0;
}

