#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int mod=1000000007;

ll fp(ll num,int pow){
    if (!pow)
        return 1;
    if (pow&1)
        return (fp((num*num)%mod,pow/2)*num)%mod;
    return fp((num*num)%mod,pow/2);
}

int main()
{
    string s;
    cin>>s;
    ll ans=0,tmp;
    for (int i=0;i<s.size();i++){
        if (s[i]=='1'){
            tmp=fp(2,s.size()-i-1);
            ans+=(((fp(2,i)*tmp)%mod)*tmp)%mod;
            ans%=mod;
        }
    }
    cout<<ans;

    return 0;
}

