void task() {
    int hy, ay, dy, hm, am, dm, h, d, a;
    scanf("%d %d %d", &hy, &ay, &dy);
    scanf("%d %d %d", &hm, &am, &dm);
    scanf("%d %d %d", &h, &a, &d);
    int ans = (int)1e6;
    for (int ia = ay; ia <= hm + dm; ++ia) {
        for (int id = dy; id <= am; ++id) {
            if (ia <= dm) {
                continue;
            }
            int cnt = hm / (ia - dm) + (hm % (ia - dm) != 0);
            int need = (id >= am ? 0 : max(0, (am - id)*cnt - hy + 1));
            int t_ans = need*h + (ia - ay)*a + (id - dy)*d;
            ans = min(ans, t_ans);
            //cout << ia << ' ' << id << ' ' << cnt << ' ' << need << ' ' << t_ans << endl;
        }
    }
    if (ans == (int)1e6){
        if (ay > hm + dm){
            if (am - dy >= hy) {
                ans = (am - dy - hy + 1)*min(h, d);
            } else
                ans = 0;
        } else {//dy > am
            if (ay - dm <= 0)
                ans = (dm - ay + 1)*a;
            else
                ans = 0;
        }
    }
    printf("%d", ans);
}

