using namespace std;

const int MAXN = 5001;
const long long MODULE = 1000 * 1000 * 1000 + 7;
const int N	= 7;
const int M = 1 << N;
long long f1[M][M], fc[M][M], nfc[M][M];
long long f[M], f2[M];
const int LG = 17;
int msk;

void merg(long long a[M][M], long long b[M][M])
{
	for (int i = 0; i < msk; i++)
	{
		for (int j = 0; j < msk; j++)
		{
			fc[i][j] = 0;
			for (int l = 0; l < msk; l++)
			{
				fc[i][j] = (fc[i][j] + a[i][l] * b[l][j]) % MODULE;
			}
		}
	}
}


void copyf()
{
	for (int j = 0; j < msk; j++)
	{
		for (int l = 0; l < msk; l++)
		{
			nfc[j][l] = fc[j][l];
		}
	}
}

int main()
{
	for (int i = 0; i < M; i++) f[i] = 0;
	f[0] = 1;
	msk = 1;
	for (int i = 1; i <= N; i++)
	{
		int w;
		cin >> w;
		for (int j = 0; j < msk; j++)
		{
			f[j + msk] = f[j];
			f[j] = 0;
		}
		msk *= 2;
		for (int j = 0; j < msk; j++)
		{
			for (int l = 0; l < msk; l++)
			{
				long long n0 = 0, n1 = 1;
				for (int k = 0; k < i; k++)
				{
					long long v0 = n0 + n1, v1 = n0;
					if (((j & (1 << k)) == 0) || ((l & (1 << k)) == 0)) v1 += n1;
					n0 = v0, n1 = v1;
				}
				f1[j][l] = n1;
			}
		}
		for (int j = 0; j < msk; j++)
		{
			for (int l = 0; l < msk; l++)
			{
				fc[j][l] = 0;
			}
			fc[j][j] = 1;
		}
		for (int pp = LG; pp >= 0; pp--)
		{
			copyf();
			merg(nfc, nfc);
			if ((1 << pp) & w)
			{
				copyf();
				merg(nfc, f1);
			}
		}
		for (int j = 0; j < msk; j++)
		{
			f2[j] = 0;
			for (int l = 0; l < msk; l++)
			{
				f2[j] = (f2[j] + f[l] * fc[l][j]) % MODULE;
			}
		}
		for (int j = 0; j < msk; j++) f[j] = f2[j];
	}
	cout << f[(1 << N) - 1] << endl;
	return 0;
}

