void go(vector <int> &a, int v, int vl, int vr, int pos) {
    if (vl == vr) {
        a.pb(v);
        return;
    }

    a.pb(v);
    int vm = (vl + vr) / 2;
    if (pos <= vm)
        go(a, v + v, vl, vm, pos);
    else
        go(a, v + v + 1, vm + 1, vr, pos);

}

