ll recur(ll index,ll moves,ll cnt,string &s,string &t,vector<vector<vector<ll>>>&dp){
    if(index==s.length())
        return 0;
    if(dp[index][moves][cnt]!=-1)
        return dp[index][moves][cnt];
    if(!moves){
        if(s[index]==t[0])
            return dp[index][moves][cnt]=recur(index+1,moves,cnt+1,s,t,dp);
        if(s[index]==t[1])
            return dp[index][moves][cnt]=cnt+recur(index+1,moves,cnt,s,t,dp);
        return dp[index][moves][cnt]=recur(index+1,moves,cnt,s,t,dp);
    }
    if(s[index]==t[0])
        return dp[index][moves][cnt]=max(recur(index+1,moves,cnt+1,s,t,dp),cnt+recur(index+1,moves-1,cnt,s,t,dp));
    if(s[index]==t[1])
        return dp[index][moves][cnt]=max(recur(index+1,moves-1,cnt+1,s,t,dp),cnt+recur(index+1,moves,cnt,s,t,dp));
    return dp[index][moves][cnt]=max({recur(index+1,moves-1,cnt+1,s,t,dp),cnt+recur(index+1,moves-1,cnt,s,t,dp),recur(index+1,moves,cnt,s,t,dp)});
}
