// probabilidade de equal iguais a need e o resto menor
double solve(int mask, int need, int equal, int ind) {
  if (equal < 0) return 0.0;

  if (mask == 0) {
    if (equal == 0) return 1.0;
    else return 0.0;
  }

  double &ans = pd[mask][need][equal][ind];
  if (vis[mask][need][equal][ind]) return ans;
  vis[mask][need][equal][ind] = true;

  if (mask & (1 << ind)) {
    if (r[ind] < need) {
      return ans = solve(mask ^ (1 << ind), need, equal, ind); 
    } else {
      double pe = 1.0/double(r[ind] - l[ind] + 1);
      double pl = double(need - l[ind])/double(r[ind] - l[ind] + 1);
      return ans = pe*solve(mask ^ (1 << ind), need, equal - 1, ind+1) + pl*solve(mask ^ (1 << ind), need, equal, ind+1); 
    }
  } else {
    return ans = solve(mask, need, equal, ind+1);
  }
}



