const ll mod = 1e9 + 7;
ll dp[MAXN][MAXN], dp2[MAXN][MAXN];
int z[MAXN];
int n;
string s;

ll solve(int pos) {
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    for (int i = 1; i <= 2 * n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (pos <= i && pos + s.length() - 1 >= i) {
                if (s[i - pos] == '(') {
                    dp[i][j] = (dp[i][j] + (j ? dp[i - 1][j - 1] : 0)) % mod;
                }
                else {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % mod;
                }
                if (pos + s.length() - 1 > i && z[s.length() - (i - pos) - 1] == i - pos + 1) {
                    dp[i][j] = (dp[i][j] - dp2[i][j] + mod) % mod;
                }
                if (pos + s.length() - 1 == i) {
                    dp2[i][j] = dp[i][j];
                }
            }
            else {
                dp[i][j] = (dp[i][j] + (j ? dp[i - 1][j - 1] : 0)) % mod;
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % mod;
                if (pos + s.length() - 1 > i) {
                    dp[i][j] = (dp[i][j] - dp2[i][j] + mod) % mod;
                }
            }
        }
    }
    return dp[2 * n][0];
}

