        while (s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    ll ans = 0;
    for (int pos = 1; pos <= 2 * n - s.length() + 1; ++pos) {
        ans = (ans + solve(pos)) % mod;
    }
