    }

    Matrix operator^(int n) const
    {
        Matrix ret;
        ret.I();
        Matrix A(*this);
        while(n)
        {
            if(n&1)
                ret = ret*A;
            A = A*A;
            n >>= 1;
        }
        return ret;
    }

    int sum() const 
    {
        int ret = 0;
        FOR(i,0,N)
            FOR(j,0,N)
                ret = (ret+a[i][j]) % mod;
        return ret;
    }

    int& operator()(int i,int j)
    {
        return a[i][j];
    }

    const int& operator()(int i,int j) const
    {
        return a[i][j];
    }

};


Matrix calcGeom(const Matrix& A,int n)
{
    Matrix ret;
    if(n == 0)
        return ret.I();
    if(n%2 == 0)
        ret = A^n, n--;

    int mid = (n+1)/2;
    return ret +  (Matrix().I() + (A^mid))*calcGeom(A,mid-1);

}

int g(const Matrix& A,int L,int R)
{


    int ret = 0;
    if(L<1)
        throw 0;
    if(L<2)
        ++L, ret = 4;
    if(L > R)
        return ret;
    L-=2, R-=2;


    Matrix X = (A^L)*calcGeom(A,R-L);
    return (ret + X.sum())%Matrix::mod;
}

i64 fastPow(i64 a,i64 n,i64 mod)
{
    i64 ret = 1;
    while(n>0)
    {
        if(n&1)
            ret*=a, ret%=mod;
        a*=a, a%=mod;
        n>>=1;
    }
    return ret%mod;
}

int f(const Matrix& A,int L,int R)
{
    if(L == 1 && R == 1)
        return 4;

    int ans = 0;
    if(L == 1)
        ++L, ans = 4;

    int all = g(A,L,R);
    if(L%2 == 0) ++L;
    if(R%2 == 0) --R;
    int pals = L<=R ? g(A,(L+1)/2,(R+1)/2):0;
    ans += ((i64)all+pals)%Matrix::mod * fastPow(2,Matrix::mod-2,Matrix::mod) % Matrix::mod;
    ans += Matrix::mod;
    ans %= Matrix::mod;
    return ans;
}


