const int N = 5;

bool v[N][N][50];
ll val[N][N], best[N][N], dp[N][N][50];

ll solve(int l, int r, int n) {
    if (v[l][r][n]) return dp[l][r][n];

    v[l][r][n] = 1;
    ll& ans = dp[l][r][n];
    int x = 6 - l - r;

    if (n == 1) return ans = best[l][r];
    ans = solve(l, x, n-1) + solve(x, r, n-1) + val[l][r];
    ll k = solve(l, r, n-1) * 2 + solve(r, l, n-1) + val[l][x]+ val[x][r];
    ans = min(ans, k);
    return ans;
}

