ll mod = 998244353;

ll binpow(ll a, ll p) {
    return p ? binpow(a * a % mod, p >> 1)* (p & 1 ? a : 1) % mod : 1;
}
ll bininv(ll a) { return binpow(a, mod - 2); }
set<int> solved;
map<ll, vector<ll> > mp;
vector<vector<ll> > C;
int k, kk;
ll m, invm;
ll fact[35000];
