struct FFT {
    int n;
    vector<ll> w;
    vector<ll> inv;

    void set(int _n = (1 << 14)) {
        n = _n;
        inv.resize(n);
        inv[0] = 0;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = (n >> 1);
            while (bit & j) {
                j ^= bit;
                bit >>= 1;
            }
            j ^= bit;
            inv[i] = j;
        }

        w.resize(n);
        ll step = binpow(3, (mod - 1) / n);
        w[0] = 1;
        for (int i = 1; i < n; i++) {
            w[i] = w[i - 1] * step % mod;
        }
    }

    void fft(vector<ll>& a) {
        for (int i = 0; i < n; i++) {
            if (i < inv[i]) {
                swap(a[i], a[inv[i]]);
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            for (int i = 0; i < n; i += len) {
                int i1 = i, i2 = i + (len >> 1);
                int wind = 0, wstep = (n / len);
                for (; i2 < i + len; i1++, i2++, wind += wstep) {
                    ll x = a[i1], y = a[i2] * w[wind] % mod;
                    a[i1] = (x + y) % mod;
                    a[i2] = (x - y + mod) % mod;
                }
            }
        }
    }

    void ifft(vector<ll>& a) {
        fft(a);
        reverse(a.begin() + 1, a.end());
        ll invn = binpow(n, mod - 2);
        for (int i = 0; i < n; i++) {
            a[i] = (a[i] * invn) % mod;
        }
    }

    void do_calculation(vector<ll> a, vector<ll> b, vector<ll>& to) {
        fft(a);
        fft(b);
        for (int i = 0; i < n; i++) {
            to[i] = a[i] * b[i] % mod;
        }
        ifft(to);
        for (int i = k + 1; i < n; i++) {
            to[i] = 0;
        }
    }
}fft;

void prec() {
    fact[0] = ifact[0] = 1;
    for (int i = 1; i < 35000; i++) {
        fact[i] = fact[i - 1] * i % mod;
        ifact[i] = binpow(fact[i], mod - 2);
    }
}

void calc(ll n) {

    // (a+b)^k = SUM_0^k C_k^i a^i b^{k-i}
    if (solved.count(n))
        return;
    if (n == 1) {
        vector<ll> tmp(k + 1, invm);
        tmp[0] = 1;
        for (int i = 0; i < k + 1; i++) {
            tmp[i] = tmp[i] * ifact[i] % mod;
        }
        while (tmp.size() < kk) {
            tmp.push_back(0);
        }
        mp[1] = tmp;
    }
    else if (n & 1) {
        calc(n - 1);
        mp[n] = vector<ll>(kk, 0);
        fft.do_calculation(mp[1], mp[n - 1], mp[n]);
        mp[n][0] = 1;
        //for (int ii = 1; ii <= k; ++ii) {
