        //        (mp[n][ii] += C[ii][i] * mp[n - 1][i] % mod * mp[1][ii - i] % mod) %= mod;
        //    }
        //}
    }
    else {
        calc(n / 2);
        mp[n] = vector<ll>(kk, 0);
        fft.do_calculation(mp[n / 2], mp[n / 2], mp[n]);
        mp[n][0] = 1;
        //for (int ii = 1; ii <= k; ++ii) {
