void go(ll ost)
{
    int last = 0;
    for (int i = 0; i < n; i++)
    {
        for (int j = last + 1; j <= n; j++)
        {
            if (ost > pow(n - j - 1))
                ost -= pow(n - j - 1);
            else
            {
                last = j;
                used[j] = true;
                p[i] = j;
                break;
            }
        }
    }
    bool flag = false;
