int C(long long x){
    for (j = 0; ;j++){
        long long y = P[j];
        if ((y*y) > x) return 1;
        if (!(x%y)) return 0;
    }
}

inline int F(int i, long long a){
    if (a == 1) return 1;
    long long y = P[i];
    if ((y + 1) > a) return 0;
    if (((y*y) + 1) > a) return C(--a);

    int res = F(i + 1, a);
    for (; ;){
        if (++y > a) break;
        if (!(a%y)) res += F(i + 1, a/y);
        y--;
        y *= P[i];
    }
    return res;
}

