const int N=21;
ll k,t,dep;
ll c[N][N],f[N][N];
int a[23],num[N];
ll dp(int x){
    for(int i=0;i<=16;i++)
        f[0][i]=1;
    for(int i=1;i<=x;i++)
        for(int j=1;j<=16;j++){
            f[i][j]=0;
            for(int k=0;k<=min(i,a[j]);k++)
                f[i][j]+=f[i-k][j-1]*c[i][k];
        }
    return f[x][16];
}
void prt(int x){
    if(x<10)putchar(x+'0');
    else putchar(x-10+'a');
}
void dfs(int k,int x)
{
    if(x==0)return;
    for(int i=(x==dep)?2:1;i<=16;i++){
        if(a[i]==0)continue;
        a[i]--;
        ll size=dp(x-1);
        if(size>=k){
            prt(i-1);
            dfs(k,x-1);
            break;
        }
        k=k-size;
        a[i]++;
    }
}
