            c[i][j]=c[i-1][j-1]+c[i-1][j];
    }
    dep=1;
    while(1){
        a[2]--;
        ll size=dp(dep-1)*15;
        a[2]++;
        if(size>=k)break;
        dep++,k-=size;
    }
    dfs(k,dep);
    return 0;
}

