std::vector<ll> Brute(std::vector<ll> v, ll n){
   std::vector<ll> tv;
   for(ll i = 0; i < (ll)(1LL << n); i++){
       ll tval = 0;
       for(ll j = 0; j < n; j++){
           if((1LL << j) & i){
              tval += v[j];
           }
       }
       tv.push_back(tval);
   }
   sort(all(tv));
   return tv;
}

bool checkInOwn(std::vector<ll> vtot, ll m){
   map <ll, bool> mp;
   for(auto i : vtot){
      if(mp.find(i - m) != mp.end()) return true;
      mp[i] = true;
    }  
    return false;
}

bool solve(){
