using namespace std;
typedef long long ll;
typedef long double ld;
const int MOD = 998244353;
const ld PI = acos(ld(-1));
int fix(ll i) { return (i % MOD + MOD) % MOD; }

const int N = 502;

ll h[N][N];
ll he[N][N];
ll sumh[N][N];

void solve(int n, int k)
{
  for (int i = 0; i <= 1; ++i) {
    for (int j = 1; j <= n; ++j) {
      h[i][j] = 1;
      he[i][j] = h[i][j] - h[i][j - 1];
      sumh[i + 1][j] = sumh[i][j] + h[i][j];
    }
  }
  for (int i = 2; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      h[i][j] = fix(sumh[i][j] - sumh[max(0, i - j)][j]);
      he[i][j] = fix(h[i][j] - h[i][j - 1]);
      sumh[i + 1][j] = fix(sumh[i][j] + h[i][j]);
    }
  }
  int ans = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
      if (i * j < k) {
        ans = fix(ans + he[n][i] * he[n][j]);
      }
    }
  }
  cout << fix(ans * 2) << endl;
}

