	Forx(i,2,n){
		dp[i] = fact[i-1] * (sum[i-1]-(i-k<=0?0:sum[i-k-1])+MOD) % MOD;
		sum[i] = ( sum[i-1] + dp[i]*invfact[i] ) % MOD;
	}
	// Print(dp,1,n);

	ll ans = 0;
	For(i,n){
		ll tans = dp[i-1] * C(n-1,i-1) % MOD * fact[n-i] % MOD;
