		// for all sums
		forr(i,0,R){
			// for all k (k has meaning in topmost comments section)
			// - i.e. ways to form sum 'i' using  exactly 'now' elements
			forr(now,0,n+1){
				// use only dp vals from previous
				// distince 'wei' for this iter
				ways[i][now][sp&1] = ways[i][now][(sp-1)&1];
				// iterating over all relevant j given i,now
				// so that doesn't go out of bounds
				forr (j, 1, min(i/wei, min(mul, now))+1) {
					// lhs: current dp arr, rhs: prev dp arr
					// where prev is dp arr for (4,4) if cur is dp arr for
					// (4,4,5,5) and arr = 4,4,5,5
					ways[i][now][sp&1] += ways[i-j*wei][now-j][(sp-1)&1];
					ways[i][now][sp&1] = min(ways[i][now][sp&1],2);
				}
			}
		}
	}
	if (sz(cnt) == 2) {
		cout<<n<<endl;
		return 0;
	}
	int best = 0;
	for (auto p : cnt) {
		int wei = p.first;
		int mul = p.second;
		forr (i, 0, mul+1) {
			// if only 1 way to form that sum,
			// composed of all same elements
			// then that is a possible candidate
			// answer, since you can identify that
			// sum with that many weights, all
			// weights are of a particular kind
			if(ways[wei*i][i][(sp)&1] == 1){
				best = max(best, i);
			}
		}
	}
	cout<<best<<endl;
	return 0;
}

