void F(int n)
{
    for(int i=0;i<=n;i++)
    {
        c[i][i]=1;
        c[0][i]=1;
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<i;j++)
        {
            c[j][i]=c[j-1][i-1]+c[j][i-1];
            c[j][i]%=mod;
        }
    }
}

main()
{
    int n;
    cin>>n;
    s[0]=1;
    s[1]=1;
    F(n);
    for(int i=2;i<=n;i++)
    {
        s[i]=s[i-1];
        for(int j=1;j<=i-1;j++)
        {
            s[i]+=c[j][i-1]*s[i-j-1];
            s[i]%=mod;
        }
    }
    dp[0]=1;
    dp[1]=1;
    for(int i=2;i<=n;i++)
    {
        dp[i]=2*dp[i-1]+s[i-1];
