void c20()
{
    size_t n, m;
    cin >> n >> m;

    typedef tuple< size_t, int64 > edge_type;

    // const auto make_edge = tuple< size_t , int64 >;

    vector < vector < edge_type > > adj( n );
    for ( size_t j = 0; j < m; ++ j )
    {
        size_t u, v;
        int64 w;
        cin >> u >> v >> w;
        -- u; -- v;

        adj[ u ].push_back( edge_type( v, w ));
        adj[ v ].push_back( edge_type( u, w ));
    }

    const int64 INF = numeric_limits< int64 >::max();
    vector < int64 > dist( n, INF );

    typedef tuple< int64, size_t > value_type;
    Heap < value_type, greater< value_type > > heap;

    dist[ 0 ] = 0;
    heap.push( make_tuple< int64, size_t >( 0, 0 ) );

    while ( ! heap.empty() )
    {
        const size_t u = get< 1 >( heap.front() );
        const int64 d = get< 0 >( heap.front() );
        heap.pop();

        if ( dist[ u ] == d )
            for ( const auto & e : adj[ u ] )
                if ( d + get< 1 >( e ) < dist[ get< 0 >( e ) ] )
                {
                    dist[ get< 0 >( e ) ] = d + get< 1 >( e );
                    heap.push( make_tuple( dist[ get< 0 >( e ) ], get< 0 >( e ) ));
                }
    }

    if ( dist[ n - 1 ] != INF )
    {
        vector < size_t > path;
        size_t u = n - 1;

        const auto pred = [&dist, &u](const edge_type & e){ return dist[get<0>(e)] + get<1>(e) == dist[u]; };

        do
        {
            path.push_back( u );
            const auto iter = find_if(begin(adj[u]), end(adj[u]), pred);
            u = get<0>(*iter);
        } while ( u != 0 );

        path.push_back( 0 );

        transform( path.rbegin(), path.rend(),
                ostream_iterator< size_t >( cout, " " ),
                bind( plus< size_t >(), placeholders::_1, 1 ));
    }
    else
        cout << -1;

}

