int power(int base, int index)
{
	if (index == 0)
		return 1;
	ll temp = power(base, index / 2);
	temp *= temp;
	if (index & 1)
		return temp * base;
	return temp;
}
int f(int x, int y)
{
	return n / (1 << x) / (y == 0 ? 1 : 3);
}

int mul(int a, int b)
{
	return (ll)a * b % mod;
}

void add_self(int &a, int b)
{
	a += b;
	if (a >= mod)
		a -= mod;
}

void solve()
{
	cin >> n;
	int x1 = log2l(n);
	db(log2l(n));
	dp[1][x1][0] = 1;
	if ((1 << (x1 - 1)) * 3 <= n)
		dp[1][x1 - 1][1] = 1;
	for (int i = 1; i < n; ++i)
	{
		for (int x = 0; x <= x1; ++x)
			for (int y = 0; y <= 1; ++y)
			{
				add_self(dp[i + 1][x][y], mul(dp[i][x][y], f(x, y) - i));
				if (x > 0)
					add_self(dp[i + 1][x - 1][y], mul(dp[i][x][y], f(x - 1, y) - f(x, y)));
				if (y > 0)
					add_self(dp[i + 1][x][y - 1], mul(dp[i][x][y], f(x, y - 1) - f(x, y)));
			}
	}
	cout << dp[n][0][0] << '\n';
}

