		}
		if(!ok) continue;
		dp[j ^ 1 << i] = min(dp[j ^ 1 << i], dp[j] + 1);
		rep(k, i) if(j & 1 << k) dp[j ^ 1 << i ^ 1 << k] = min(dp[j ^ 1 << i ^ 1 << k], dp[j]);
	}
	int ans = inf;
	rep(i, 1 << n) if(i & 1 << (n - 1)) ans = min(ans, dp[i]);
