	while((f < '0' || f > '9')&&f != '-')f = nc();
	if(f == '-')
	{
		sig = -1;
		f = nc();
	}
	while(f >='0' && f <= '9'){
		sum = sum * 10 + f - '0';
		f = nc(); 
	}
	sum *= sig;
	return sum;
}

