long long getp(long long time, int k)
{
	time %= 2 * k;
	if (time <= k)
		return time;
	time -= k;
	return k - time;
}

int main()
{
	ull t;
	cin >> t;

	for (; t > 0; --t)
	{
		int n, k, l;
		cin >> n >> k >> l;

		vector<int> d(n);
		for (int i = 0; i < n; ++i)
			cin >> d[i];

		vector<pair<long long, long long>> v;
		v.emplace_back(0, 2 * k - 1);

		for (int i = 0; i < n && !v.empty(); ++i)
		{
			vector<pair<long long, long long>> v2;

			for (auto [b, e] : v)
			{
				++b;
				++e;

				for (long long j = b; j <= e;)
				{					
					if (d[i] + getp(j, k) > l)
					{
						auto level = d[i] + getp(j, k);
						auto time = j % (2 * k);
						if (time < k)
						{
							level += k - time;
							time = k;
						}

						j += level - l;
						if (j > e)
							break;
					}

					auto curb = j;
					auto level = d[i] + getp(j, k);
					auto time = j % (2 * k);
					if (time < k)
					{
						if (level + (k - time) > l)
						{
							j = curb + l + 1 - level;
							v2.emplace_back(curb, j - 1);
							continue;
						}
					}

					while (d[i] + getp(j, k) <= l && (j - curb) < 2 * k)
						++j;

					v2.emplace_back(curb, j - 1);
				}
			}

			swap(v, v2);
		}

		cout << (v.empty() ? "No" : "Yes") << endl;
	}
}

