typedef long long ll;

bool Check(ll need1, ll need2, ll x, ll y, ll have){
    if (x == y){
        ll good = have - have / x;
        return good >= ll(need1 + need2);
    }

    ll bad1 = have / x - have / (x * y);
    ll bad2 = have / y - have / (x * y);
    ll bad12 = have / x + have / y - have / (x * y);
    ll good12 = have - have / x - have / y + have / (x * y);

    ll add1, add2;

    add1 = min(need1, bad2);
    need1 -= add1;

    add2 = min(need2, bad1);
    need2 -= add2;

    add1 = min(need1, good12);
    good12 -= add1;
    need1 -= add1;

    add2 = min(need2, good12);
    need2 -= add2;
    return need1 == 0 && need2 == 0;
}

int main(){
