    cin >> need1 >> need2 >> x >> y;

    ll lb = 0, rb = 1000000000000000;
    while (true){
        ll diff = rb - lb;
        if (diff <= 1ll)
            break;
        ll cur = (lb + rb) / 2ll;
        if (Check(need1, need2, x, y, cur))
            rb = cur;
        else
            lb = cur;
    }

    cout << rb;
    return 0;
}

