#define MOD 1000000007

int dp[20], c[10];
long long DP[20];

long long getc(long long val, int c) {
	if(val < c)
		return 0;
	if(c == 0)
		return 1LL;
	return (val * getc(val - 1, c - 1)) % MOD;
}

long long get() {
	long long ans = 1;
	for(int i = 0; i < 10; i ++) {
		ans *= getc(DP[i], c[i]);
		ans %= MOD;
	}
	return ans;
}

void work(string m) {
	int len = m.length();
	for(int i = 0; i < len; i ++) {
		int already = 0;
		for(int j = 0; j < i; j ++)
			if(m[j] == '4' || m[j] == '7')
				already ++;
		for(int k = 0; k < (1 << (len - i)); k ++) {
			int count = 0;
			int numposs = 0;
			if(k & 1) {
				if(m[i] > '7') {
					numposs = 2;
				}
				else if(m[i] > '4') {
					numposs = 1;
				}
				count ++;
			}
			else {
				if(m[i] > '7') {
					numposs = m[i] - '0' - 2;
				}
				else if(m[i] > '4') {
					numposs = m[i] - '0' - 1;
				}
				else
					numposs = m[i] - '0';
			}
			for(int j = 1; j < (len - i); j ++) {
				if(k & (1 << j)) {
					numposs *= 2;
					count ++;
				}
				else
					numposs *= 8;
			}
			dp[count + already] += numposs;
		}
	}
	int p = 0;
	for(int i = 0; i < len; i ++) {
		if(m[i] == '4' || m[i] == '7')
			p ++;
	}
	dp[p] ++;
	dp[0] --;
	for(int i = 0; i < 15; i ++)
		DP[i] = (long long) dp[i];
}

int main() {
	string m;
	cin >> m;
	work(m);
	/*for(int i = 0; i < 10; i ++)
		printf("%lld\n", DP[i]);*/
	long long ans = 0;
	for(int i = 1; i < 10; i ++) {
		for(int p1 = 0; p1 < i; p1 ++) {
			for(int p2 = 0; p1 + p2 < i; p2 ++) {
				for(int p3 = 0; p1 + p2 + p3 < i; p3 ++) {
					for(int p4 = 0; p1 + p2 + p3 + p4 < i; p4 ++) {
						for(int p5 = 0; p1 + p2 + p3 + p4 + p5 < i; p5 ++) {
							for(int p6 = 0; p1 + p2 + p3 + p4 + p5 + p6 < i; p6 ++) {
								memset(c, 0, sizeof(c));
								c[p1] ++;
								c[p2] ++;
								c[p3] ++;
								c[p4] ++;
								c[p5] ++;
								c[p6] ++;
								c[i] ++;
								ans += get();
								ans %= MOD;
							}
						}
					}
				}
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

