template< const ll &mod >
struct _m_int 
{
    ll val;

    _m_int(ll v = 0) 
    {
        if (v < 0) v = v % mod + mod;
        if (v >= mod) v %= mod;
        val = v;
    }

    static ll inv_mod(ll a, ll m = mod) // Extended Euclidean algorithm
    {
        ll g = m, r = a, x = 0, y = 1;

        while (r != 0) 
        {
            ll q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }

        return x < 0 ? x + m : x;
    }

    _m_int& operator+=(const _m_int &other) 
    {
        val -= mod - other.val;
        if (val < 0) val += mod;
        return *this;
    }

    _m_int& operator-=(const _m_int &other) 
    {
        val -= other.val;
        if (val < 0) val += mod;
        return *this;
    }

    static unsigned fast_mod(ull x, unsigned m = mod) 
    {
        #if !defined(_WIN32) || defined(_WIN64)
                return unsigned(x % m);
        #endif
                // Optimized mod for Codeforces 32-bit machines.
                // x must be less than 2^32 * m for this to work, so that x / m fits in a 32-bit unsigned int.
                unsigned x_high = unsigned(x >> 32), x_low = unsigned(x);
                unsigned quot, rem;
                asm("divl %4\n"
                    : "=a" (quot), "=d" (rem)
                    : "d" (x_high), "a" (x_low), "r" (m));
                return rem;
    }

    _m_int& operator*=(const _m_int &other) 
    {
        val = fast_mod(ull(val) * other.val);
        return *this;
    }

    _m_int& operator/=(const _m_int &other) 
    {
        return *this *= other.inv();
    }

    friend _m_int operator+(const _m_int &a, const _m_int &b) { return _m_int(a) += b; }
    friend _m_int operator-(const _m_int &a, const _m_int &b) { return _m_int(a) -= b; }
    friend _m_int operator*(const _m_int &a, const _m_int &b) { return _m_int(a) *= b; }
    friend _m_int operator/(const _m_int &a, const _m_int &b) { return _m_int(a) /= b; }

    _m_int& operator++() 
    {
        val = val == mod - 1 ? 0 : val + 1;
        return *this;
    }

    _m_int& operator--() 
    {
        val = val == 0 ? mod - 1 : val - 1;
        return *this;
    }

    _m_int operator++(int) { _m_int before = *this; ++*this; return before; }
    _m_int operator--(int) { _m_int before = *this; --*this; return before; }

    _m_int operator-() const 
    {
        return val == 0 ? 0 : mod - val;
    }

    bool operator==(const _m_int &other) const { return val == other.val; }
    bool operator!=(const _m_int &other) const { return val != other.val; }

    _m_int inv() const 
    {
        return inv_mod(val);
    }

    _m_int pow(ll p) const 
    {
        if (p < 0)
            return inv().pow(-p);

        _m_int a = *this, result = 1;

        while (p > 0) 
        {
            if (p & 1)
                result *= a;

            p >>= 1;

            if (p > 0)
                a *= a;
        }

        return result;
    }

    explicit operator ll() const { return val; }

    friend ostream& operator<<(ostream &os, const _m_int &m) 
    {
        return os << m.val;
    }

    inline friend void __print(_m_int x) {cerr << x;}
};

using mint = _m_int<MOD>;

vector<mint> inverse, factorial, inv_factorial;
ll prepared_maximum = -1;

void prepare_factorials(ll maximum) 
{
    static ll prepare_calls = 0;

    if (prepare_calls++ == 0) 
    {
        // Make sure MOD is prime, which is necessary for the inverse algorithm below.
        for (ll p = 2; p * p <= MOD; p += p % 2 + 1)
            assert(MOD % p != 0);

        inverse = {0, 1};
        factorial = inv_factorial = {1, 1};
        prepared_maximum = 1;
    }

    if (maximum > prepared_maximum) 
    {
        inverse.resize(maximum + 1);
        factorial.resize(maximum + 1);
        inv_factorial.resize(maximum + 1);

        for (ll i = prepared_maximum + 1; i <= maximum; i++) 
        {
            inverse[i] = inverse[MOD % i] * (MOD - MOD / i);
            factorial[i] = i * factorial[i - 1];
            inv_factorial[i] = inverse[i] * inv_factorial[i - 1];
        }

        prepared_maximum = ll(maximum);
    }
}

mint fact(ll n) 
{
    prepare_factorials(n);
    return factorial[n];
}

mint ifact(ll n) 
{
    prepare_factorials(n);
    return inv_factorial[n];
}

mint ncr(ll n, ll r) 
{
    if (r < 0 || r > n || n < 0) return 0;
    prepare_factorials(n);
    return factorial[n] * inv_factorial[r] * inv_factorial[n - r];
}

mint incr(ll n, ll r) 
{
    assert(0 <= r && r <= n);
    prepare_factorials(n);
    return inv_factorial[n] * factorial[r] * factorial[n - r];
}

mint npr(ll n, ll r) 
{
    if (r < 0 || r > n || n < 0) return 0;
    prepare_factorials(n);
    return factorial[n] * inv_factorial[n - r];
}

mint inpr(ll n, ll r) 
{
    assert(0 <= r && r <= n);
    prepare_factorials(n);
    return inv_factorial[n] * factorial[n - r];
}

