pT qpow ( const pT &a, int b )
{
	pT base = a, ans;
	ans[0] = 1;
	while ( b ){
		if ( b & 1 ) ans *= base;
		base *= base;
		b >>= 1;
	}
	return ans;
}



int add ( int x, int y )
{
	return ( ( x += y ) < MOD ) ? x : ( x - MOD );
}

void addv ( int &x, int y )
{
	( ( x += y ) < MOD ) ? x : ( x -= MOD );
}

int sub ( int x, int y )
{
	return ( ( x -= y ) >= 0 ) ? x : ( x + MOD );
}

void subv ( int &x, int y )
{
	( ( x -= y ) >= 0 ) ? x : ( x += MOD );
}

int qpow ( int a, int b )
{
	LL base = a, ans = 1;
	while ( b ){
		if ( b & 1 ) ( ans *= base ) %= MOD;
		( base *= base ) %= MOD;
		b >>= 1;
	}
	return SC ( int, ans );
}



