    rep(i, 1, n) rep(j, i, n) c[i][j] = c[i - 1][j - 1] + c[i][j - 1];
    queue<State> q;
    d[cnt50][cnt100][0] = 1;
    cnt[cnt50][cnt100][0] = 1;
    q.push(State(cnt50, cnt100, 0));
    while (!q.empty())
    {
