using namespace std;

const int MAXN = 60;
const int MAXM = 10;

int n;
long long dp[MAXN][MAXM];
char phone[MAXN];

long long calcDP(int idx, int digit) {
    if (dp[idx][digit] != -1) {
        return dp[idx][digit];
    }
    if ((digit + phone[idx + 1] - '0') & 1) {
        dp[idx][digit] = calcDP(idx + 1, (digit + phone[idx + 1] - '0') >> 1) + calcDP(idx + 1, ((digit + phone[idx + 1] - '0') >> 1) + 1);
    } else {
        dp[idx][digit] = calcDP(idx + 1, (digit + phone[idx + 1] - '0') >> 1);
    }
    return dp[idx][digit];
}

bool isValid() {
    for (int i = 0; i < n - 1; i++) {
        int digit1 = phone[i] - '0', digit2 = phone[i + 1] - '0';
        if ((digit1 + digit2) & 1) {
            if (digit2 != ((digit1 + digit2) >> 1) && digit2 != ((digit1 + digit2) >> 1) + 1) {
                return false;
            }
        } else {
            if (digit2 != ((digit1 + digit2) >> 1)) {
                return false;
            }
        }
    }
    return true;
}

int main() {
    scanf("%s", phone);
    n = (int)strlen(phone);
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < 10; j++) {
            dp[i][j] = -1;
        }
    }
    for (int j = 0; j < 10; j++) {
        dp[n - 1][j] = 1;
    }
    long long res = 0;
    for (int digit = 0; digit < 10; digit++) {
        res += calcDP(0, digit);
    }
    printf("%lld\n", res - isValid());
    return 0;
}

