// region 自动取模类
template<int MOD, int RT>
struct mint {
    static constexpr mint rt() { return RT; } // primitive root for FFT
    int v;

    explicit operator int() const { return v; } // explicit -> don't silently convert to int
    mint() : v(0) {}

    mint(ll _v) {
        v = int((-MOD < _v && _v < MOD) ? _v : _v % MOD);
        if (v < 0) v += MOD;
    }

    bool operator==(const mint &o) const {
        return v == o.v;
    }

    friend bool operator!=(const mint &a, const mint &b) {
        return !(a == b);
    }

    friend bool operator<(const mint &a, const mint &b) {
        return a.v < b.v;
    }

    mint &operator+=(const mint &o) {
        if ((v += o.v) >= MOD) v -= MOD;
        return *this;
    }

    mint &operator-=(const mint &o) {
        if ((v -= o.v) < 0) v += MOD;
        return *this;
    }

    mint &operator*=(const mint &o) {
        v = int((ll) v * o.v % MOD);
        return *this;
    }

    mint &operator/=(const mint &o) { return (*this) *= inv(o); }

    friend mint qpow(mint a, ll p) {
        mint ans = 1;
        assert(p >= 0);
        for (; p; p /= 2, a *= a) if (p & 1) ans *= a;
        return ans;
    }

    friend mint inv(const mint &a) {
        assert(a.v != 0);
        return qpow(a, MOD - 2);
    }

    mint operator-() const { return mint(-v); }

    mint &operator++() { return *this += 1; }

    mint &operator--() { return *this -= 1; }

    mint operator++(int) {
        mint tmp = *this;
        *this += 1;
        return tmp;
    }

    mint operator--(int) {
        mint tmp = *this;
        *this -= 1;
        return tmp;
    }

    friend mint operator+(mint a, const mint &b) { return a += b; }

    friend mint operator-(mint a, const mint &b) { return a -= b; }

    friend mint operator*(mint a, const mint &b) { return a *= b; }

    friend mint operator/(mint a, const mint &b) { return a /= b; }

    friend istream &operator>>(istream &is, mint &a) {
        ll tv;
        is >> tv;
        a = mint(tv);
        return is;
    }

    friend ostream &operator<<(ostream &os, const mint &a) {
        return os << a.v;
    }
};
// endregion

// region 矩阵(Z)
template<int SZ, class Z>
struct Mat {
    int r, c;
    Z a[SZ + 1][SZ + 1];

    Mat() {}

    void init(int _r, int _c) {
        r = _r, c = _c;
    }

    inline void operator=(Z x) {
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                a[i][j] = i == j ? x : 0;
            }
        }
    }

    // _a: 0 base, a: 1 base
    inline void operator=(const vector<vector<Z>> &_a) {
        assert(r == _a.size() && c == _a[0].size());

        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                a[i][j] = _a[i - 1][j - 1];
            }
        }
    }

    inline Mat operator+(const Mat &T) const {
        assert(r == T.r && c == T.c);

        Mat res;
        res.init(r, c);
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                res.a[i][j] = a[i][j] + T.a[i][j];
            }
        }
        return res;
    }

    inline Mat operator-(const Mat &T) const {
        assert(r == T.r && c == T.c);

        Mat res;
        res.init(r, c);
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                res.a[i][j] = a[i][j] - T.a[i][j];
            }
        }
        return res;
    }

    inline Mat operator*(const Mat &T) const {
        assert(c == T.r);

        Mat res;
        res.init(r, T.c);
        for (int i = 1; i <= res.r; i++) {
            for (int j = 1; j <= res.c; j++) {
                res.a[i][j] = 0;
                for (int k = 1; k <= c; k++) {
                    res.a[i][j] = res.a[i][j] + a[i][k] * T.a[k][j];
                }
            }
        }
        return res;
    }

    inline Mat operator*(Z x) const {
        Mat res;
        res.init(r, c);
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                res.a[i][j] = a[i][j] * x;
            }
        }
        return res;
    }

    inline Mat operator^(ll x) const {
        assert(r == c);

        Mat res, bas;
        res.init(r, c), bas.init(r, c);
        res = 1, bas = *this;

        while (x) {
            if (x & 1) res = res * bas;
            bas = bas * bas;
            x >>= 1;
        }
        return res;
    }

    inline bool operator==(const Mat &T) const {
        if (r != T.r || c != T.c) return false;
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                if (a[i][j] != T.a[i][j]) return false;
            }
        }
        return true;
    }

    inline void print() const {
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                cout << a[i][j] << " \n"[j == c];
            }
        }
    }
};
// endregion

// region trie
// 字符总长 SZ, 字符集大小 C
// 默认小写字母
template<int SZ, int C = 26>
struct Trie {
    int rt;
    int ne[SZ + 10][C], mem;
    int cnt[SZ + 10];

    Trie() {}

    void init() {
        mem = 0;
        rt = new_node();
        fill(&ne[0][0], &ne[0][C], 0);
        cnt[0] = 0;
    }

    int new_node() {
        int id = ++mem;
        fill(&ne[id][0], &ne[id][C], 0);
        cnt[id] = 0;
        return id;
    }

    void ins(const string &s) {
        int u = rt;
        for (char ch : s) {
            int &v = ne[u][ch - 'a'];
            if (!v) v = new_node();
            u = v;
        }

        cnt[u]++;
    }

    int qr(const string &s) {
        int u = rt, res = 0;
        for (char ch : s) {
            int v = ne[u][ch - 'a'];
            if (!v) break;

            u = v;
            res += cnt[u];
        }

        return res;
    }
};
// endregion

const int dir[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
const int MOD = 998244353;
const int N = 11;
const int B = 44;

using Z = mint<MOD, 5>;

int n, m;
string a[N];
Trie<B> tr;
int ids[B][B], tt;
pii rid[B * B];
int vis[B * B];
Mat<170, Z> coef, A;

inline int get(int u, int v) {
    if (u > v) swap(u, v);
    if (!ids[u][v]) {
        ids[u][v] = ++tt;
        rid[tt] = {u, v};
    }
    return ids[u][v];
}

void solve() {
    tr.init();
    for (int i = 1; i <= n; i++) tr.ins(a[i]);

    coef.init(170, 170);

    queue<int> que;
    vis[get(1, 1)] = 1;
    que.push(get(1, 1));
    while (!que.empty()) {
        auto u = que.front(); que.pop();
        auto [x, y] = rid[u];

        for (char ch = 'a'; ch <= 'z'; ch++) {
            int nx = tr.ne[x][ch - 'a'], ny = tr.ne[y][ch - 'a'];
            if (nx == 0 || ny == 0) continue;

            coef.a[u][get(nx, ny)]++;
            que.push(get(nx, ny));
            if (tr.cnt[nx]) {
                coef.a[u][get(1, ny)]++;
                if (!vis[get(1, ny)]) {
                    vis[get(1, ny)] = 1;
                    que.push(get(1, ny));
                }
            }
            if (tr.cnt[ny]) {
                coef.a[u][get(nx, 1)]++;
                if (!vis[get(nx, 1)]) {
                    vis[get(nx, 1)] = 1;
                    que.push(get(nx, 1));
                }
            }
            if (tr.cnt[nx] && tr.cnt[ny]) {
                coef.a[u][get(1, 1)]++;
                if (!vis[get(1, 1)]) {
                    vis[get(1, 1)] = 1;
                    que.push(get(1, 1));
                }
            }
        }
    }
    coef.r = coef.c = tt;

    A.init(tt, 1);
    A.a[1][1] = 1;

    A = (coef ^ m) * A;

    cout << A.a[1][1] << "\n";
}

