		for (int w = 0; w < 8; w++){
			cin>>board[q][w];
			if (board[q][w] == 'W'){ i++; rowW[i] = q; colW[i] = w; }
			else if (board[q][w] == 'B'){ j++; rowB[j] = q; colB[j] = w; }
