int clockWise(char source, char distination)
{
	if (source == distination)
		return 0;
	if(source < distination)
		return distination - source;
	return 'z' - source + distination - 'a'+1;
}

int antiClockWise(char source, char distination)
{
	if(source == distination)
		return 0;
	if(source < distination)
		return source - 'a' + 'z' - distination + 1;
	return source - distination;
}

