	long long k(3), b, c;
	while (k < p) {
		b = 3*a[i].first+2;
		c = 3*(a[j].first/2)+a[j].first%2;
		k = min(b,c);
		if (a[i].second != 0 && a[j].second != 0) {
			if (a.back().second == 0) a.back().first = k;
			else a.push_back(pair<long long,int>(k,0));
		}
