			if (a.back().second == 1) a.back().first = k;
			else a.push_back(pair<long long,int>(k,1));
		}
		else {
			if (a.back().second == 2) a.back().first = k;
			else a.push_back(pair<long long,int>(k,2));
		}
		if (b <= c) ++i;
		if (c <= b) ++j;
	}

	long long nimble[4] = {0};
	for (int i = a.size()-1; i > 0; --i)
		nimble[a[i].second] += (a[i].first-a[i-1].first)*(2*p-a[i].first-a[i-1].first-1)/2;
	nimble[a.back().second] -= (a.back().first-p)*(p-a.back().first-1)/2;
	nimble[0] += 2*p-3;
	for (int i = 0; i < 4; ++i)
		nimble[i] %= mod;

	long long tmp[4], ans[4] = {1, 0, 0, 0};
	for (int i = n; i > 0; i /= 2) {
