			for (int j = 0; j < 4; ++j)
				tmp[j] = ans[j];
			for (int j = 0; j < 4; ++j) {
				ans[j] = 0;
				for (int k = 0; k < 4; ++k)
					ans[j] += tmp[k]*nimble[j^k];
				ans[j] %= mod;
			}
		}
		for (int j = 0; j < 4; ++j)
			tmp[j] = nimble[j];
		for (int j = 0; j < 4; ++j) {
			nimble[j] = 0;
	   		for (int k = 0; k < 4; ++k)
				nimble[j] += tmp[k]*tmp[j^k];
			nimble[j] %= mod;
		}
	}
	cout << (ans[1]+ans[2]+ans[3]) % mod << endl;
	return 0;
}

