                while(l == i || l == j)
                    l++;
                if(l >= 2*n)
                    break;
                first = l;
                l++;
                while(l == i || l == j)
                    l++;
                if(l >= 2*n)
                    break;
                second = l;
                l++;
                temp += arr[second] - arr[first];
            }

            ans = min(ans,temp);
        }
    }

    cout << ans << endl;
    return 0;
}

