int mod=1e9+7;
ll mem[50][50][10005],n,k,ans=1,inv[51];

ll bpw(ll b,ll p){
	ll ans=1;
	while(p){
		if(p&1)ans=ans*b%mod;
		b=b*b%mod;
		p/=2;
	}
	return ans;
}

int main(){__
	for(int i=1;i<=50;i++)
		inv[i]=bpw(i,mod-2);
	for(int i=0;i<50;i++)
		mem[i][i][0]=1;
	for(int k=1;k<=10000;k++)
		for (int to=0;to<50;to++){
			ll s=0;
			for(int from=0;from<50;from++){
				s=s*(from)%mod;
				s+=mem[from][to][k-1];
				s=s*inv[from+1]%mod;
				mem[from][to][k]=s;
			}
		}
	cin>>n>>k;
	for(ll i=2;i*i<=n;i++)
		if(n%i==0){
			ll pw=0,x=0;
			while(n%i==0)
				n/=i,pw++;
			for(ll j=0,l=1;j<=pw;j++,l=l*i%mod)
				x+=mem[pw][j][k]*l%mod;
			x%=mod;
			ans=ans*x%mod;
		}
