using namespace std;

long long int count(long long int x){
	long long int ans = 0;
	while (x != 0){
		ans += (x % 10);
		x /= 10;
	}
	return ans;
}

long long int solve(long long int x){
	long long int ans = x;
	long long int i = 10;
	while (x > 0){
		x = x - x % i - 1;
		if (count(x) > count(ans))
			ans = x;
		i *= 10;
	}
	return ans;
}

int main()
{
	long long int x;
	cin >> x;
	cout << solve(x);
	return 0;
}

