ll mul(ll a, ll b, ll mod) {
	a %= mod;
	ll res = 0, p = a;
	while(b) {
		if(b%2) res += p, res %= mod;
		p += p; p %= mod; b>>=1;
	}
	return res;
}
ll a_b(ll a, ll b, ll mod) {
	a %= mod;
	ll res = 1, p = a;
	while(b) {
		if(b%2) res = mul(res, p, mod);
		p = mul(p, p, mod); b>>=1;
	}
	return res;
}


