//	printf("%lld %lld\n", A, B);
	if(A == 1) return B;
	if(B == 0) return 0;
	if(isPrime(A)) {
		ll v = B % A; B -= v;
		v += B / A;
		return v;
	}
	if(B % A == 0) return B / A;

	ll g = gcd(A, B);
	ll cnt = 1, na = A/g;
	ll b = B/g - 1;

	if(isPrime(na)) {
		cnt += b % na;
		b -= b % na;
	}else{
		while(gcd(b, na) == 1 && b > 0) b--, cnt++;
	}
	ll ans = cnt + myF(na, b);
	return ans;
}
