		pw[i]=pw[i-1]*p%mod;
		pw2[i]=pw2[i-1]*(1-p)%mod;
	}
	for(int i=0;i<=n;g[i++][0]=1)
		for(int j=1;j<=i;j++){
			g[i][j]=(g[i-1][j]*pw2[j]+g[i-1][j-1]*pw[i-j])%mod;
		}
	for(int i=1;i<=n;i++){
		h[i]=1;
		for(int j=1;j<i;j++)h[i]=(h[i]-h[j]*g[i][j])%mod;
	}
	for(int i=1;i<=n;i++){
		ll tot=0;
		for(int j=1;j<=i;j++)tot=(tot+g[i][j]*h[j]%mod*((C2(j)+j*(i-j)+f[i-j]+f[j])%mod))%mod;
