ll dp[N][N], ans, fact[N], pwd[N][N], c[N][N];
ll power(int x, int n){
	if(x < N && n < N && pwd[x][n] != -1) {
		return pwd[x][n];
	}
	if(n == 0)
		return 1ll;
	ll y = power(x, n/2);
	y = (y*y) % mod;
	if(n % 2)
		return (1ll * x * y) %mod;
	return y;
}
ll ncr(int n, int r){
	if(r > n)
		return 0ll;
	return c[n][r];
}
