    for(int i=1; i < N; i++) {
    	fact[i] = (1ll * i * fact[i-1]) % mod;
    }
    for(int i = 0; i < N; i++) {
    	for(int j = 0; j < N; j++) {
    		pwd[i][j] = -1;
    		pwd[i][j] = power(i, j);
    	}
    }

	c[0][0] = 1;
	for (int i = 1; i < N; ++i) {
   		c[i][0] = c[i][i] = 1;
    	for (int j = 1; j < i; ++j) {
        	c[i][j] = (c[i - 1][j - 1] + c[i - 1][j])%mod;
    	}
	}
