    			dp[i][k] = power(k, i) - power(k-1, i);
    			if(dp[i][k] < 0ll)
    				dp[i][k] += mod;
    		} else {
    			for(int j = i; j > 1; j--) {
    				dp[i][k] = (dp[i][k] + ( (ncr(i, i-j) * power(i-1, (i-j)) ) % mod * dp[j][k - (i-1)]) % mod) % mod;
    			}
    		}
    		if(i == n) {
    			ans = (ans + dp[i][k]) % mod;
    		}
    	}
