long long solve(int x) {
	if(x == 1) return 0;
	long long rekt = (long long) 1e18;
	for(int i = 1; 1LL * i * i <= x; ++i) {
		if(x % i == 0) {
		if(i != 1) {
			rekt = min(rekt , ((x / i) * get(i)) + solve(x / i) );
		}
		if((x / i) != 1 and (x / i) != i) {
			rekt = min(rekt , (i * get(x / i) ) + solve(i) );
		}
	}
	}
	return rekt;
}
