vector<vector<ll>> mul(vector<vector<ll>> a, vector<vector<ll>> b) {
    int n = a.size();
    int k = b.size();
    int m = b[0].size();
    vector<vector<ll>> c(n, vector<ll>(m, 1e10));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int z = 0; z < k; z++) {
                c[i][j] = min(c[i][j], a[i][z] + b[z][j]);
            }
        }
    }
    return c;
}

vector<vector<ll>> fast_pow(vector<vector<ll>> v, int p) {
    vector<vector<ll>> res = v;
    p--;
    while (p) {
        if (p & 1) {
            res = mul(res, v);
            p--;
        } else {
            v = mul(v, v);
            p /= 2;
        }
    }
    return res;
}

