  ll n, k;
  cin >> n >> k;
  string str;
  cin >> str;
  vector <vector <int> > lst(n, vector <int> (26, -1));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < 26; j++) {
      if (i) lst[i][j] = lst[i - 1][j];
    }
    lst[i][str[i] - 'a'] = i;
  }
  vector <vector <ll> > dp(n + 1, vector <ll> (n + 1));
  for (int i = 0; i < n; i++) {
    dp[i][1] = 1;
  }
  for (int len = 2; len <= n; len++) {
    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < 26; j++) {
        if (lst[i - 1][j] != -1) {
          dp[i][len] = min((ll)1e12, dp[i][len] + dp[lst[i - 1][j]][len - 1]);
        }
      }
    }
  }

  ll ans = 0;
  for (int i = n; i >= 0 && k; i--) {
    ll cnt = 0;
    for (int j = 0; j < 26; j++) {
      if (lst[n - 1][j] != -1) {
        cnt += dp[lst[n - 1][j]][i];
      }
    }
    if (i == 0) cnt = 1;
    if (k >= cnt) {
      ans += cnt * 1ll * (n - i);
      k -= cnt;
    }
    else {
      ans += k * 1ll * (n - i);
      k = 0;
      break;
    }
  }
  cout << (k == 0 ? ans : -1) << endl;

  return 0;
}

