bool cut[MAXN];
int op[MAXN], cl[MAXN];
vector<int> G[MAXN];
int getf(int x)
{
	if (x==f[x]) return x;
	return f[x]=getf(f[x]);
}
void merge(int u, int v)
{
	int x=getf(u), y=getf(v);
	if (x!=y)
	{
		f[x]=f[y]=++num;
		G[num].push_back(x);
		G[num].push_back(y);
	}
}
void DFS(int u)
{
	op[u]=++dfc;
	for (int v: G[u]) DFS(v);
	cl[u]=dfc;
}
namespace SGT
{
	struct Node
	{
		int l, r;
		pair<int, int> val;
	} tr[4*MAXN];
#define lc (o<<1)
#define rc (o<<1|1)
	void pushup(int o)
	{
		tr[o].val=max(tr[lc].val, tr[rc].val);
	}
	void build(int o, int l, int r, int* a)
	{
		tr[o].l=l, tr[o].r=r;
		if (l==r) return tr[o].val=make_pair(a[l], l), void();
		int mid=(l+r)>>1;
		build(lc, l, mid, a);
		build(rc, mid+1, r, a);
		pushup(o);
	}
	pair<int, int> query(int o, int l, int r)
	{
		if (tr[o].l>r||tr[o].r<l) return make_pair(0, 0);
		if (l<=tr[o].l&&tr[o].r<=r) return tr[o].val;
		return max(query(lc, l, r), query(rc, l, r));
	}
	void modify(int o, int p)
	{
		if (tr[o].l==tr[o].r) return tr[o].val.first=0, void();
		int mid=(tr[o].l+tr[o].r)>>1;
		if (p<=mid) modify(lc, p);
		else modify(rc, p);
		pushup(o);
	}
#undef lc
#undef rc
}
