	}
	num=n;
	for (int i=1; i<=m; i++)
		if (!cut[i]) merge(u[i], v[i]);
	for (int i=q; i>=1; i--)
		if (opt[i]==1) p[i]=getf(ob[i]);
		else merge(u[ob[i]], v[ob[i]]);
	for (int i=1; i<=num; i++)
		if (getf(i)==i) DFS(i);
