ll fastpow(ll x, ll k)
{
	ll base = x;
	ll ret = 1;
	while (k) {
		if (k & 1) {
			ret *= base;
			ret %= mod;
		}
		base *= base;
		base %= mod;
		k >>= 1;
	}
	return ret;
}

