void init() {
	for(int i = 2; i <M; ++i) {
		if(!is[i]) {
			pr[ct++]=i;
			fa[i]=i;
		}
		for(int j = 0; j < ct&&i*pr[j]<M;++j){
			is[i*pr[j]]=1;
			fa[i*pr[j]]=pr[j];
			if(i%pr[j]==0)break;
		}
	}
