	ll ans = 1;
	for(int i = n-1; i >=0; --i) {
		if(!cnt[p[i]]) {
			cnt[p[i]]=1;
			num[p[i]]=1;
			ans = (ans * p[i])%mod;
			//printf("i = %d ans = %lld\n",i,ans);
		}
		else {
			int v = --p[i];
			while(v>1) {
				int u = fa[v];
				//printf("i = %d v = %d u = %d\n",i,v,u);
				int nu = 0;
				while(v%u==0)v/=u,nu++;
