  struct DPE{
    number_t matched;
    number_t unmatched;
    number_t unused;
  };
  DPE solve(int u,int p){
    DPE r={1,0,1};
    vector<number_t>matchable;
    vector<number_t>matched;
    for(int v:adj[u]){
      if(v!=p){
        auto r2=solve(v,u);
        auto r2matchable=r2.unmatched+r2.unused;
        matchable.push_back(r2matchable);
        matched.push_back(r2.matched);
        r.matched*=r2matchable;
        r.unused*=r2.unused;
     }
    }
    int sz=matchable.size();
    if(sz){
      vector<number_t>matchableLeft(sz,0);
      vector<number_t>matchableRight(sz,0);
      matchableLeft[0]=1;
      for(int i=1;i<sz;i++)matchableLeft[i]=matchableLeft[i-1]*matchable[i-1];
      matchableRight[sz-1]=1;
      for(int i=sz-2;i>=0;i--)matchableRight[i]=matchableRight[i+1]*matchable[i+1];
      for(int i=0;i<sz;i++){
        r.unmatched+=matchableLeft[i]*matched[i]*matchableRight[i];
      }
    }
    r.unused+=r.unmatched;
    return r;
  }
