void find_node(vector<int>& a, vector<int>& b, int s, int e, int curr)
{
	int pos = s;
	if (s == e)
	{
		b[s] = curr + 1;
		return;
	}
	if (e < s)
	{
		return;
	}
	for (int i = s; i <= e; i++)
	{
		if (a[pos] < a[i])
		{
			pos = i;
		}
	}
	b[pos] = curr + 1;
	curr++;
	find_node(a, b, s, pos - 1, curr);
	find_node(a, b, pos + 1, e, curr);
}

