	int digits = 0;
	long long a = x;
	while (a > 0) {
		a /= 10;
		digits++;
	}
	if (digits == n) {
		return;
	}
	long long y = x;
	while (y > 0) {
		int temp = y % 10;
		if (temp > 1) {
			search(x * temp, n, count + 1, ans);
		}
		y /= 10;
	}
}

