#define N 255
#define Mod 998244353
#define For(i,x,y)for(i=x;i<=(y);i++)
int f[N][N][N],pre[N][N][N],g[N][N],inv[N];
int ksm(int x,int y)
{
	return(!y?1:1LL*ksm(1LL*x*x%Mod,y>>1)*(y&1?x:1)%Mod);
}
int main()
{
	int n,k,i,j,p,num,tmp,res=0;
	cin>>n>>k;
	For(j,1,k)f[1][j][1]=1;
	For(i,1,n-1)inv[i]=ksm(i,Mod-2);
	For(i,1,k)
	{
		g[i][0]=1;
		For(j,1,n)g[i][j]=1LL*g[i][j-1]*i%Mod;
	}
	For(i,2,n-1)
	{
		For(j,1,k)
		For(num,1,i-1)pre[i-1][j][num]=(pre[i-1][j-1][num]+f[i-1][j][num])%Mod;
		For(j,1,k)
		For(num,1,i-1)
		{
			p=j;
			tmp=(p==j?num+1:1);
			f[i][j][tmp]=(f[i][j][tmp]+1LL*f[i-1][p][num]*inv[tmp]%Mod*g[k-j+1][i-1])%Mod;
			tmp=1;
			f[i][j][tmp]=(f[i][j][tmp]+1LL*pre[i-1][j-1][num]*inv[tmp]%Mod*g[k-j+1][i-1])%Mod;
		}
	}
	For(j,1,k)
	For(num,1,n-1)res=(res+f[n-1][j][num])%Mod;
	For(i,1,n-1)res=1LL*res*i%Mod;
	cout<<res;
	return 0;
}

