template <class T> void read(T & t) { for (auto & x : t) in >> x; }

int bit_count(int i) {
    i = i - ((i >> 1) & 0x55555555);
    i = (i & 0x33333333) + ((i >> 2) & 0x33333333);
    i = (i + (i >> 4)) & 0x0f0f0f0f;
    i = i + (i >> 8);
    i = i + (i >> 16);
    return i & 0x3f;
}

int main() {
    ios_base::sync_with_stdio(false);
    int n; in >> n;
    vs p(n); read(p);
    int m = p[0].size();
    vll d(1 << m);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int mask = 0;
            for (int k = 0; k < m; ++k) {
                if (p[i][k] == p[j][k])
                    mask |= 1 << k;
            }
            d[mask] |= 1LL << i;
            d[mask] |= 1LL << j;
        }
    }
    for (int mask = d.size() - 1; mask >= 0; --mask) {
        for (int bit = 0; bit < m; ++bit) if (mask & (1 << bit)) {            
            d[mask ^ (1 << bit)] |= d[mask];
        }
    }
    vd paths(m + 1);
    for (int mask = 0; mask < d.size(); ++mask) {
        int moves = bit_count(mask) + 1;
        for (int bit = 0; bit < m; ++bit) {
            int newmask = mask | (1 << bit);
            if (newmask == mask) continue;
            ll added = d[mask] ^ d[newmask];
            paths[moves] += bit_count(added & 0xFFFFFFFF) + bit_count(added >> 32);
        }
    }
    double res = 0;
    for (int i = 1; i <= m; ++i) {
        double t = paths[i];
        for (int j = 0; j < i; ++j) {
            t *= 1. * (i - j) / (m - j);
        }
        res += t;
    }
    res /= n;
    out.setf(ios::fixed); out.precision(10); out << res;
    return 0;
}

