void mm_er(  )
{
   // printf("dire= %d m_er%d\n",dire,m_er);
    if( dire == 1 ) ////向左走
    {
        if( m_er == 1 )
        {
            m_er++;
            dire = ( dire+1 )%2 ;
        }
        else  m_er--;
    }
    else
    {
        if( m_er == n )
        {
            m_er--;
            dire = ( dire+1 )%2 ;
        }
        else  m_er++;
    }
}

void mm_m1( int i )
{
  // printf("dire= %d m=%d\n",dire,m);
    if( ss[i] == '0' ) // //车move
    {
        if( dire == 0 ) //// Controller向右走
        {
            if( m < m_er ){
                if(m!=1)  m--;
            }
            else if( m < n ) m++;
        }
        else  //// Controller向左走
        {
            if( m > m_er ){
                if( m != n ) m++;
            }
            else if( m > 1 ) m--;
        }
    }
    else  ////车idle
    {
        if( dire == 0 )//// Controller向右走
            m=m_er-1;
        else // // Controller向左走
            m=m_er+1;
    }
}

