    {
        if(m==m_er&&i!=0)
        {
            cnt=i;
            return false;
        }
        if(ss[i]=='0')
        {
            if(i+1<l&&m_er==n-1&&m==n&&dire==0&&ss[i+1]=='0'){
                cnt=i+1;
                return false;
            }
            if(i+1<l&&m_er==2&&m==1&&dire==1&&ss[i+1]=='0'){
                cnt=i+1;
                return false;
            }

        }
        mm_er( );
        mm_m1( i );
        //printf("i= %d  %d %d\n",i,m,m_er);
    }
    return true;
}

