#include <iostream>

using namespace std;
const int MAX_DIGIT = 10, MAX_LENGTH = 101, MODULO = 1000 * 1000 * 1000 + 7;
int numberOfOccurance[MAX_DIGIT], numberLength;
long long answer[MAX_DIGIT][MAX_LENGTH], chooseMem[MAX_LENGTH][MAX_LENGTH];

int choose (int r, int n) {
	if (r == 0 or r == n) {
		return 1;
	}
	if (r > n or r < 0) {
		return 0;
	}
	if (chooseMem[r][n] != -1) {
		return chooseMem[r][n];
	}
	return chooseMem[r][n] = ((choose(r - 1, n - 1) + choose(r, n - 1)) % MODULO);
}

int main() {
	// INPUT PROCESS
	cin >> numberLength;
	for (int i = 0; i < MAX_DIGIT; ++i) {
		cin >> numberOfOccurance[i];
	}

	// SETTING BASE FORM FOR THE chooseMem
	{
		for (int i = 0; i < MAX_LENGTH; ++i) {
			for (int j = 0; j < MAX_LENGTH; ++j) {
				chooseMem[i][j] = -1;
			}
		}
	}

/*
	answer[i][j] is defined as followed:
		it hold the answer of this problem if we had to create a number from digit i to MAX_DIGIT (like from 4 to 9),
		and alsi it means that the answer number should exactly have j digits, now to calculate such DP we say that, 
		let's say we want to calculate the answer for k-th digit, so we say that the answer is equal to sum of all answers
		of answer[k + 1][j - numberOfAppearencesOfKthDigit] * the bionamial choosing of numberOfAppearencesOfKthDigit places
		from all j places for the k-th digit!
*/

	// DP base form
	for (int i = 0; i <= numberLength; ++i) {
		if (i >= numberOfOccurance[MAX_DIGIT - 1]) {
			answer[MAX_DIGIT - 1][i] = 1; 
		}
		else {
			answer[MAX_DIGIT - 1][i] = 0;
		}
	}

	// DP Update
	for (int maxNumber = MAX_DIGIT - 2; maxNumber > 0; --maxNumber) {
		for (int length = numberOfOccurance[maxNumber]; length <= numberLength; ++length) {
			for (int maxNumberOccurance = numberOfOccurance[maxNumber]; maxNumberOccurance <= length; ++ maxNumberOccurance) {
				answer[maxNumber][length] += answer[maxNumber + 1][length - maxNumberOccurance] * choose(maxNumberOccurance, length);
				answer[maxNumber][length] %= MODULO;
				//if (answer[maxNumber][length] > 0) cerr << maxNumber << " " << length << " -> " << maxNumberOccurance << " : " << answer[maxNumber][length] << endl;
			}
		}
	}

	// only note that since the number can't start with leading 0 (zeroes), we cannot choose the first place of the j -> j - 1
	for (int length = numberOfOccurance[0]; length <= numberLength; ++length) {
		for (int maxNumberOccurance = numberOfOccurance[0]; maxNumberOccurance <= length; ++ maxNumberOccurance) {
			answer[0][length] += (answer[1][length - maxNumberOccurance] * choose(maxNumberOccurance, length - 1));
			answer[0][length] %= MODULO;
			//if (answer[0][length] > 0) cerr << 0 << " " << length << " -> " << maxNumberOccurance << " : " << answer[0][length] << endl;
		}
	}

	// ans can be any length so we just sum up any lengths that has all digits in them (their "i" in "dp[i][j]" is equal to 0)
	long long ans = 0;
	for (int i = 1; i <= numberLength; ++i) {
		ans += answer[0][i];
		ans %= MODULO;
		//cerr << i << " : " << answer[0][i] << "	";
	}
	cout << ans << endl;
	return 0;
}

