int dotN, jumpK, disM, colC;
void add(int &fir, long long sec) {
	fir = (long long) (fir + sec) % mod;
}
struct Matrix{
	int num[210][210], row, col;
	void init(int sze) {
		row = col = sze;
		memset(num, 0, sizeof(num));
		for (int rowI = 0; rowI < row; ++rowI) {
			num[rowI][rowI] = 1;
		}
	}
	void init2(int r, int c) {
		row = r, col = c;
		memset(num, 0, sizeof(num));
	}
	Matrix operator = (const Matrix d) {
		row = d.row;
		col = d.col;
		for (int rowI = 0; rowI < row; ++rowI) {
			for (int colJ = 0; colJ < col; ++colJ) {
				num[rowI][colJ] = d.num[rowI][colJ];
			}
		}
		return (*this);
	}
	Matrix operator * (const Matrix d) const {	//注意，假如在main函数里进行矩阵乘法的话，ret数组的空间算在main函数里，那么就有可能爆main函数的空间
		Matrix ret;
		memset(ret.num, 0, sizeof(ret.num));
		ret.row = row;
		ret.col = d.col;
		for (int rowI = 0; rowI < ret.row; ++rowI) {
			for (int colJ = 0; colJ < ret.col; ++colJ) {
				for (int mid = 0; mid < col; ++mid) {
					add(ret.num[rowI][colJ], 1ll * num[rowI][mid] * d.num[mid][colJ]);
				}
			}
		}
		return ret;
	}
	Matrix power(int up) const {
		Matrix ret, base = (*this);
		ret.init(row);
		while (up) {
			if (up & 1) ret = ret * base;
			base = base * base;
			up >>= 1;
		}
		return ret;
	}
} ans, base, orig;

int pos(int er, int san) {
	return er * colC + san;	//这里应该是er（开始从下标从1开始时），不应该是 er + 1（因为一个在第i行第j列的点，编号应该是(i-1)*col+j而不是i*col+j）纸袋分析法
}
int bitCount(int st) {
	int ret = 0;
	for (int weiI = 0; weiI < 4; ++weiI) {
		if (st & (1 << weiI)) {
			++ret;
		}
	}
	return ret;
}
void init() {
	scanf("%d%d%d", &dotN, &jumpK, &disM);
	colC = 1 << disM;
	ans.init(colC * (jumpK + 1));
	orig.init2(1, colC * (jumpK + 1));
	orig.num[0][0] = 1;	//注意赋初始值！
	base.init2(colC * (jumpK + 1), colC * (jumpK + 1));
	for (int jumpJ = 0; jumpJ <= jumpK; ++jumpJ) {
		for (int stK = 0; stK < (1 << disM); ++stK) {
			if (! (stK & (1 << disM - 1))) {
			//注意运算的优先级！ !和&的优先级一样高，所以要把后面的那串括起来 
				add(base.num[pos(jumpJ, stK << 1)][pos(jumpJ, stK)], 1);
				add(base.num[pos(jumpJ, stK << 1 | 1)][pos(jumpJ, stK)], 1);
			} else {
				if (jumpJ >= 1) {
					add(base.num[pos(jumpJ - 1, (stK - (1 << disM - 1)) << 1)][pos(jumpJ, stK)], 
						1ll * (1 + bitCount((stK - (1 << disM - 1)) << 1)));
					//注意在这里计算的时候要开 long long!!! 
					add(base.num[pos(jumpJ - 1, (stK - (1 << disM - 1)) << 1 | 1)][pos(jumpJ, stK)], 
						1ll * (1 + bitCount((stK - (1 << disM - 1)) << 1 | 1)));
				}
			}
		}
	}
}

int main() {
	init();
	int cnt = 0;
	ans = orig * base.power(dotN);
	for (int stK = 0; stK < (1 << disM); ++stK)
		add(cnt, ans.num[0][pos(jumpK, stK)]);
	printf("%d\n", cnt);
	return 0;
}

