const int maxn = 4e5 + 20, inf = 1e17, Mod = (1ll << 32);
int n, p, q, ent[maxn], ans;

int choose(int x, int y){
	if(x > y) return 0;
	if(x == y || x == 0)return 1;
	vector <int> tmp;
	for(int i = 0; i < x; i++)tmp.push_back(y - i);
	for(int i = 2; i <= x; i++){
		//cout << x << " : " << y << endl;
		int tmpp = i, tmppp = 0;
		while(tmpp != 1){
			int tmpppp = __gcd(tmpp, tmp[tmppp]);
			tmp[tmppp] /= tmpppp;
			tmpp /= tmpppp;
			tmppp++;
		}
	}
	int res = 1;
	for(int i = 0; i < x; i++){
		res = (res * tmp[i]) % Mod;
	}
	return res;
}

int32_t main(){
    cin >> n >> p >> q;
    p = min(p, n - 1);
    for(int i = 0; i <= p; i++){
    	//cout << i << endl;
		ent[i] = choose(i, n);
	}

	for(int i = 1; i <= q; i++){
		int tmp1 = 0, tmp2 = 1;
		for(int j = 0; j <= p; j++){
			tmp1 = (tmp1 + ent[j] * tmp2) % Mod;
			tmp2 = (tmp2 * i) % Mod;
		}
		ans = (ans ^ (i * tmp1)) % Mod;
	}
    cout << (ans + Mod) % Mod;
}

