    }
    //cout<<badnum<<" "<<over<<"\n";
    owo(i, 0, n/2) {
        if(arr[i]!=arr[n-i-1]) {
            if(arr[i]!=badnum&&arr[n-i-1]!=badnum){
                mins.senpai(val[i]);
                mins.senpai(val[n-i-1]);
            }
        }else {
            if(arr[i]==badnum)continue;
            mins.senpai(max(val[i], val[n-i-1]));
        }
    }
    sort(mins.begin(), mins.end());
    owo(i, 0, over) {
        lose+=mins[i];
    }
    cout<<(sum-lose)<<"\n";
    return 0;
}

