const int N=32;
const int M=35;
const int P=(int)1e9+7;
int q;
int dp1[M][2][2][2],dp2[M][2][2][2],X[M],Y[M],K[M];
inline void Add(int &a,int b){
	a=(a+b)%P;
}
int solve(int x,int y,int k){
	if(x<0||y<0)return 0;
	memset(dp1,0,sizeof(dp1));
	memset(dp2,0,sizeof(dp2));
	for(int i=1;i<=N;i++){
		X[i]=(x&1),Y[i]=(y&1),K[i]=(k&1);
		x>>=1,y>>=1,k>>=1;
	}
	reverse(X+1,X+N+1),reverse(Y+1,Y+N+1),reverse(K+1,K+N+1);
	dp1[1][1][1][1]=1;
	for(int i=1;i<N;i++)
		for(int j=0;j<2;j++)
			for(int k=0;k<2;k++)
				for(int t=0;t<2;t++)
					for(int x=0;x<2;x++)
						for(int y=0;y<2;y++){
							if(!dp1[i][j][k][t])continue;
							int z=x^y;
							if(j&&(x>X[i+1]))continue;
							if(k&&(y>Y[i+1]))continue;
							if(t&&(z>K[i+1]))continue; 
							Add(dp1[i+1][j&(x==X[i+1])][k&(y==Y[i+1])][t&(z==K[i+1])],dp1[i][j][k][t]);
							Add(dp2[i+1][j&(x==X[i+1])][k&(y==Y[i+1])][t&(z==K[i+1])],dp2[i][j][k][t]);
							Add(dp2[i+1][j&(x==X[i+1])][k&(y==Y[i+1])][t&(z==K[i+1])],dp1[i][j][k][t]*((ll)z<<(N-1-i))%P);
						}
	int res=0;
	for(int i=0;i<2;i++)
		for(int j=0;j<2;j++)
			for(int t=0;t<2;t++)
				Add(res,(dp1[N][i][j][t]+dp2[N][i][j][t])%P);
	return res;
}
int main(){
	Rd(q);
	while(q--){
		int x1,y1,x2,y2,k,ans=0;
		Rd(x1),Rd(y1),Rd(x2),Rd(y2),Rd(k);
		x1--,y1--,x2--,y2--,k--;
		ans=(ans+solve(x2,y2,k))%P;
		ans=(ans-solve(x1-1,y2,k)+P)%P;
		ans=(ans-solve(x2,y1-1,k)+P)%P;
		ans=(ans+solve(x1-1,y1-1,k))%P;
		printf("%d\n",ans);
	}
	return 0;
}

