class ShortestPathWeightedGraph {
private:
  int N;
  vector<vector<pair<int,long long> > > adj;
  vector<long long> dist;
public:
  ShortestPathWeightedGraph(int N)
  {
    this->N = N;
    adj.resize(N);
  }
  void add(int u, int v, long long weight)
  {
    adj[u].push_back(make_pair(v, weight));
  }
  int shortest(int from, int to)
  {
    dist.resize(N);
    fill(dist.begin(), dist.end(), -1);
    priority_queue<pair<long long, int> > q;
    q.push(make_pair(0, from));
    dist[from] = 0;
    while (!q.empty())
    {
      int u = q.top().second;
      ll distu = -q.top().first;
      q.pop();
      if (dist[u] < distu) continue;
      for (int i = 0; i < adj[u].size(); i++)
      {
        int v = adj[u][i].first;
        long long weight = adj[u][i].second;
        if (dist[v] == -1 || dist[u] + weight < dist[v])
        {
          dist[v] = dist[u] + weight;
          q.push(make_pair(-dist[v], v));
        }
      }
    }
    return dist[to];
  }
};


