const int MAX = 7e5+1;
const int MOD = 1e6+3;

int fac[MAX], infac[MAX];

int Pow(int x, int y) {
	int curr = 1;
	while(y > 0) {
		if(y % 2 != 0) curr = (curr*x) % MOD;
		x = (x*x) % MOD;
		y /= 2;
	}

	return curr;
}

void precompute(int s) {
	fac[0] = 1;
	for(int i = 1; i <= s; i++) fac[i] = (fac[i-1]*i) % MOD;
	infac[s] = Pow(fac[s], MOD-2);
	for(int i = s-1; i >= 0; i--) infac[i] = ((i+1)*infac[i+1]) % MOD;
}

int bi(int n, int r) {
	return ((fac[n]*infac[r]) % MOD * infac[n-r]) % MOD;
}

signed main() {
	int n, c, total = 0;
	cin >> n >> c;
	precompute(n+c-1);
	for(int i = 1; i <= n; i++) total = (total+bi(i+c-1, i)) % MOD;
	cout << total;
}

