ll mem[50][50][50];
ll solve(int l , int r , int h) // we use the third dimension h to detect the case of restriction of none
{
    if(l>r || l==r)
        return 1;
    ll &ret=mem[l][r][h];
    if(ret!=-1)
        return ret;
    ret=0;
    for(int i=l; i<=r; i++)
    {
        ll tmp=0;
        if(i-l>=h-1 || r-i>=h-1)
        {
            ll r1 , r2 , r3 , r4;
            if(i-l>=h-1)
                r1=solve(l , i-1 , max(h-1 , 0) );
            else
                r1=solve(l , i-1 , 0);
            if(r-i>=h-1)
                r2=solve(i+1 , r , max(h-1 , 0) );
            else
                r2=solve(i+1 , r , 0);
            tmp=r1*r2;
            //cout<<"out"<<" "<<tmp<< endl;
            if(i-l>=h-1 && r-i>=h-1)
            {
                // here we calculates the possible trees that some part of it have no restriction
                r3=solve(l , i-1 , 0); // no res
                r3-=r1; // remove duplication
                r4=solve(i+1 , r , 0);
                r4-=r2; // remove duplication
                // missed calculation
                tmp+=r3*r2;
                tmp+=r4*r1;
                //cout<<endl<<"IN"<<" "<<tmp<< endl;
            }
        }
        ret+=tmp;
    }
    return ret;
}
