inline ll add_mod(ll a, ll b, const ll mod = MOD){
//    if(a<0) a += mod;
//    if(b<0) b += mod;
	return ((a>=0 ? a : a+mod)%mod + (b>=0 ? b : b+mod)%mod)%mod;
}

inline ll sub_mod(ll a, ll b, const ll mod = MOD){
	ll result = ((a>=0 ? : a+mod)%mod - (b>=0 ? b : b+mod)%mod);
	return (result >= 0 ? result : result + mod)%mod;
}

inline ll mult_mod(ll a, ll b, const ll mod = MOD){
	return ((a>=0? a : a+mod)%mod * (b>=0 ? b : b+mod)%mod)%mod;
}

ll fast_expo(ll x, ll y, const ll mod = MOD){
	ll ans = 1;
	while(y > 0){
		if(y%2 == 1)    ans = mult_mod(x, ans, mod);
		x = mult_mod(x, x, mod);
		y /= 2;
	}
	return ans;
}

inline ll div_mod(ll a, ll b, const ll mod = MOD){
	return mult_mod(a, fast_expo(b, mod - 2, mod), mod);
}

ll ncr(ll n, ll r){
	if(n == 0)
	return 1;
	// cout << n space r << endl;
	if(r == 0 or r == n){
		return 1;
	}
	else return ncr(n-1, r) + ncr(n-1, r - 1);
}

