intreg combinari(intreg n,intreg k)
{
//combinari de n luate cate k
    if (k>n) return 0;
    n%=mod;
    intreg rasp=1;
    for(int i=0;i<k;++i)
    {
        rasp=rasp*(n-i)%mod;
        rasp=rasp*invers[i+1]%mod;
    }
    return rasp;
}

