inline int inc(int& x, int y) {
	return (((x += y) < D)? x: (x -= D));
}
inline int add(int x, int y) {
	return (((x + y) < D)? x + y: ((x + y) - D));
}
inline int mul(int x, int y) {
	return ((1ll * x * y) % D);
}
int f(int x) {
	return (~mf[x]? mf[x]: (mf[x] = mul(x, f(x - 1))));
}
inline istream& operator >> (istream &in, song &x) {
	in >> x.t >> x.g;
	return in;
}
inline int multi(int& x, int y) {
	return (x = mul(x, y));
}
void init() {
	memset(mf, -1, sizeof mf);
	mf[0] = 1;
	dp1[0][0] = dp23[0][0][0] = jav[0][0][0][0] = 1;
}
void inp() {
	cin >> n >> T;
	song tmp;
	for (int i = 0; i < n; i++) {
		cin >> tmp;
		if (tmp.g == 1)
			for (int i = num[1]; i >= 0; i--)
				for (int j = dur[1]; j >= 0; j--)
					inc(dp1[i + 1][j + tmp.t], dp1[i][j]);
		else {
			for (int i = num[2]; i >= 0; i--)
				for (int j = num[3]; j >= 0; j--)
					for (int k = dur[2] + dur[3]; k >= 0; k--)
						((tmp.g == 2)? inc(dp23[i + 1][j][k + tmp.t], dp23[i][j][k]): inc(dp23[i][j + 1][k + tmp.t], dp23[i][j][k]));
		}
		dur[tmp.g] += tmp.t;
		num[tmp.g]++;
	}
}
void solve() {
	upd();
	calc();
}
void upd() {
	int i[G + 1];
	for (i[1] = 0; i[1] <= num[1]; i[1]++)
		for (i[2] = 0; i[2] <= num[2]; i[2]++)
			for (i[3] = 0; i[3] <= num[3]; i[3]++)
				for (int prev = 0; prev <= 3; prev++) {
					int tmp = jav[i[1]][i[2]][i[3]][prev];
					if (tmp == 0)
						continue;
					for (int next = 1; next <= 3; next++)
						if (next != prev && i[next] + 1 <= num[next]) {
							i[next]++;
							inc(jav[i[1]][i[2]][i[3]][next], tmp);
							i[next]--;
						}
				}
}
void calc() {
	for (int i = 0; i <= num[1]; i++)
		for (int j = 0; j <= dur[1]; j++) {
			if (T < j)
				break;
			for (int k = 0; k <= num[2]; k++)
				for (int h = 0; h <= num[3]; h++) {
					int nat = mul(dp1[i][j], dp23[k][h][T - j]);
					multi(nat, mul(f(i), mul(f(k), f(h))));
					for (int next = 1; next <= 3; next++)
						inc(ans, mul(nat, jav[i][k][h][next]));
				}
		}
}

