const ll MOD = 1000 * 1000 * 1000 + 9;
ll n,m,k;
ll fexp(ll a, ll p)
{
    ll res=1;
    while(p){
        if(p&1){
            res=(res*a)%MOD;
            p--;
        }
        a=(a*a)%MOD;
        p/=2;
    }
    return res;
}
bool f(ll x)
{
//    ll n1 = n-x*k, m1=m-x*k;
//    ll q=n1/k;
    return m-(n%k)-(n-n%k)/k*(k-1)<=x;
}
ll bs(ll l, ll r)
{
//    cout<<"l: "<<l<<" r: "<<r<<endl;
    if(r-l<=1){
        if(f(r))
            return f(l)?l:r;
        return r;
    }
    ll med=(l+r)/2;
    if(f(med))
        return bs(l,med);
    return bs(med,r);
}
