using namespace std;

const int oo = 0x3fffffff;
const int MAXN = 10;
const int MAXM = 100;

struct SInformation
{
    int a, b, c;
};

struct SEarn
{
    int price;
    int limit;
};

SInformation info[MAXN][MAXM];
SEarn earn[MAXM];
int n, m, cap;

inline bool cmp(const SEarn &a, const SEarn &b)
{
    return a.price > b.price;
}

void init(void)
{
    cin >> n >> m >> cap;
    for (int i = 0; i < n; i++)
    {
        string s;
        cin >> s;
        for (int j = 0; j < m; j++)
        {
            cin >> info[i][j].a >> info[i][j].b >> info[i][j].c;
        }
    }
}

void solve(void)
{
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            for (int k = 0; k < m; k++)
            {
                earn[k].price = max(info[j][k].b - info[i][k].a, 0);
                earn[k].limit = info[i][k].c;
            }
            sort(earn, earn + m, cmp);
            int sum = 0;
            int t = cap;
            for (int k = 0; k < m; k++)
            {
                if (t <= earn[k].limit)
                {
                    sum += t * earn[k].price;
                    break;
                }
                sum += earn[k].limit * earn[k].price;
                t -= earn[k].limit;
            }
            ans = max(sum, ans);
        }
    }
    cout << ans << endl;
}

int main(void)
{
    ios::sync_with_stdio(false);
    init();
    solve();
    return 0;
}

