    }
    int ans = 0;
    for (int i=0; i<n; i++)
        for (int j=0; j<n; j++)
        {
            if (i == j)
                continue;
            priority_queue < pair <int, int> > q;
            for (int l=0; l<m; l++)
                    q.push(make_pair(b[j][l] - a[i][l], c[i][l]));
            int t = k;
            int res = 0;
            while (!q.empty() && t > 0)
            {
                int x = q.top().first, y = q.top().second;
                int d = min(t, y);
                q.pop();
                if (x <= 0)
                    continue;
                if (y-d != 0)
                    q.push(make_pair(x, y-d));
                res += x*d;
                t -= d;
            }
            ans = max(ans, res);
        }
    cout << ans;
    return 0;
}

