int c[11][101];

int ta[11][101];
int tb[11][101];
int tc[11][101];

int main() {
	int n, m, k;
	cin >> n >> m >> k;
	string s;
	REP(i, n) {
		cin >> s;
		REP(j, m) {
			cin >> ta[i][j] >> tb[i][j] >> tc[i][j];
		}
	}
	int ans = 0;
	REP(i, n) REP(j, n) if ( i != j ) {
		int res = 0;
		REP(ii, n) REP(jj, m) {
			a[ii][jj] = ta[ii][jj];
			b[ii][jj] = tb[ii][jj];
			c[ii][jj] = tc[ii][jj];
		}
		REP(ii, k) {
