struct Planet
{
    vector<int> b, s, c;

    void add(int bb, int ss, int cc)
    {
        b.push_back(bb);
        s.push_back(ss);
        c.push_back(cc);
    }
};

int n, m, k;
vector<Planet> P;

struct good
{
    int s;
    int b;
    int c;

    good(int b, int s, int c) : b(b), c(c), s(s) {}

    bool operator <(good g)
    {
        int p1 = s - b,
            p2 = g.s - g.b;
        if (p1 == p2)
            return c > g.c;
        return p1 > p2;
    }
};


int solve(int i, int j)
{
    vector<good> g;
    for (int q = 0; q < m; ++q)
    {
        if (P[i].c[q] == 0)
            continue;
        g.push_back(good(P[i].b[q], P[j].s[q], P[i].c[q]));
    }

    sort(g.begin(), g.end());

    int left(k), need(0), profit(0);
    for (int q=0; q<g.size(); ++q)
    {
        if (left == 0) break;
        if (g[q].b < g[q].s)
        {
            int bo = min(g[q].c, left);
            left -= bo;
            need += bo * g[q].b;
            profit += bo * g[q].s;
        }
    }

    return profit - need;
}

int main()
{
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    string s;
    cin >> n >> m >> k;
    for (int i=0; i<n; ++i)
    {
        cin >> s;
        P.push_back(Planet());
        for (int j=0; j<m; ++j)
        {
            int s, b, c;
            cin >> b >> s >> c;
            P.back().add(b, s, c);
        }
    }

    int result = 0, r;
    for (int i=0; i<n; ++i)
    {
        for (int j=0; j<n; ++j)
        {
            if (i != j)
            {
                r = solve(i, j);
                result = max(result, r);
            }
        }
    }

    cout << result;
    return 0;
}

