int n , m , k , buy[200][200] , sell[200][200] , val[200][200] , maxval = 0;
string s;

int Try(int from , int to)
{
    int used = 0;
    int pr = 0;
    int lf[200];
    for (int i = 1 ; i <= m ; i ++ )
        lf[i] = val[from][i];
    while ( used != k )
    {
        int best = -1;
        for (int i = 1 ; i <= m ; i ++ )
            if ( lf[i] != 0 && ((sell[to][best] - buy[from][best]) < (sell[to][i] - buy[from][i])  || best == -1) && (sell[to][i] - buy[from][i]) > 0 )
                best = i;
        if ( best == -1 )
            break;
        int get = min(lf[best] , k - used);
        used += get;
        lf[best] -= get;
        pr += get * (sell[to][best] - buy[from][best]);
    }
    return pr;
}

int main()
{
