  i=l;
  j=m;
  do
  {
    while(A[i]>z)
      i++;
    while(A[j]<z)
      j--;
    if (i<=j)
    {
      swap(A[i],A[j]);
      swap(B[i],B[j]);
      i++;
      j--;
    }
  }while(i<=j);
  if (i<m) quick123(i,m);
  if (l<j) quick123(l,j);
}

