int dp (int i, int k) {
    if (i == m || k <= 0)
        return 0;

    int & me = memo[i][k];
    if (visi[i][k] == turn)
        return me;
    visi[i][k] = turn;

    me = dp(i+1, k);
    int pr = be[b][i]-cs[a][i];

    if (pr <= 0)
        return me;

    for (int j = 1; j <= min(qt[a][i], k); j++) {
        me = max(me, pr*j + dp(i+1, k-j));
    }

    return me;
}

