struct product {
    int bvalue;
    int svalue;
    int quantity;
}; 

struct planet {
    std::vector<struct product> merc;
};

int max_profit (struct planet a, struct planet b, int m, int k) {
    std::multiset<std::pair<int,int>> profit_table;

    for (int i = 0; i < m; ++i) {
        std::pair<int,int> profit_merc;
        profit_merc.first = a.merc[i].bvalue - b.merc[i].svalue;
        profit_merc.second = a.merc[i].quantity;
        profit_table.insert(profit_merc);
    }

    int profit = 0;
    for (auto merc_profit : profit_table) {
        if (merc_profit.first > 0) break;
        if (k > merc_profit.second) {
            profit += -merc_profit.first*merc_profit.second;
            k -= merc_profit.second;
        } else {
            profit += -merc_profit.first*k;
            break;
        }
    }

    return profit;
}

