using namespace std;
long long NWD(long long a, long long b) { return (b == 0) ? a : NWD(b, a % b); }
inline long long NWW(long long a, long long b) { return a / NWD(a, b) * b; }
inline long long normalize(long long x, long long MOD) { return ((x % MOD) + MOD) % MOD; }
class GCD_Type { public: long long x, y; };
GCD_Type exGCD(long long a, long long b)
{
	if (b == 0) return{ 1, 0 };
	GCD_Type pom = exGCD(b, a % b);
	return{ pom.y, pom.x - (a / b) * pom.y };
}
using CRT_Var_Type = long long;
class CRT_Equation_Type
{
public:
	CRT_Var_Type a, m;
	inline bool operator==(const CRT_Equation_Type& other)
	{
		return a == other.a && m == other.m;
	}
	inline bool operator!=(const CRT_Equation_Type& other)
	{
		return a != other.a || m != other.m;
	}
};
class ChineseRemainderTheorem // system of equations x = ai (mod mi) i = 0,1,2,...
{
	vector<CRT_Equation_Type>equations;
public:
	static constexpr CRT_Equation_Type Failed = { -1, -1 }; // returned when no solutions
	void clear() // clears system of equations
	{
		equations.clear();
	}
	void addEquation(CRT_Var_Type a, CRT_Var_Type m) // adds equation of form x = a (mod m)
	{
		a %= m; if (a < 0) a += m;
		equations.push_back({ a, m });
	}
	CRT_Equation_Type solve()
	{
		if (equations.empty() == true) return Failed;
		CRT_Equation_Type ans = equations[0];
		for (int i = 1; i < equations.size(); i++)
		{
			CRT_Equation_Type next = equations[i];
			CRT_Var_Type g = NWD(ans.m, next.m);
			if (ans.a % g != next.a % g) return Failed;
			GCD_Type Bezout = exGCD(ans.m / g, next.m / g);
			CRT_Var_Type lcm = ans.m / g * next.m;
			ans.a = (ans.a % lcm + (next.a - ans.a) / g * Bezout.x % (next.m / g) * ans.m % lcm) % lcm;
			if (ans.a < 0) ans.a += lcm;
			ans.m = lcm;
		}
		return ans;
	}
};
long long n, m, x, y, vx, vy, wynik = LLONG_MAX;
ChineseRemainderTheorem Uklad;
int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> n >> m >> x >> y >> vx >> vy;
	if (vx == 0)
	{
		if (x == 0 || x == n) cout << x << " " << (~vy ? m : 0) << endl;
		else return cout << -1 << endl, 0;
	}
	else if (vy == 0)
	{
		if (y == 0 || y == m) cout << (~vx ? n : 0) << " " << y << endl;
		else return cout << -1 << endl, 0;
	}
	else
	{
		for (int i = 0; i < 4; i++)
		{
			Uklad.addEquation(vx * ((i / 2) * n - x), 2 * n);
			Uklad.addEquation(vy * ((i % 2) * m - y), 2 * m);
			auto SystemSolution = Uklad.solve();
			if (SystemSolution != ChineseRemainderTheorem::Failed) wynik = min(wynik, SystemSolution.a);
			Uklad.clear();
		}
		x = normalize(x + wynik * vx, 2 * n);
		y = normalize(y + wynik * vy, 2 * m);
		(wynik == LLONG_MAX) ? (cout << -1 << endl) : (cout << x << " " << y << endl);
	}

	getchar();
	getchar();
	return 0;
}

