constexpr int MOD = 998244353;
constexpr int MAXN = 3008;

int d[MAXN][MAXN];
int mi[MAXN][MAXN];

int solve()
{ 
	using namespace std;
	int N, M, A, B;
	cin >> N >> M >> A >> B;

	int g, x, y, z;
	cin >> g >> x >> y >> z;

	for (int i = 0; i < N; ++i) 
	{
		for (int j = 0; j < M; ++j) 
		{
			d[i][j] = g;
			g = (g * 1LL * x + y) % z;
		}
	}

	for (int i = 0; i < N; ++i) 
	{
		deque< pair<int, int > > Q;

		for (int j = 0; j < M; ++j) 
		{
			while (!Q.empty() && Q.back().first >= d[i][j])
				Q.pop_back();

			Q.push_back(make_pair(d[i][j],j) );

			while (!Q.empty() && Q.front().second < j - B + 1)
				Q.pop_front();

			mi[i][j] = Q.front().first;
		}

	}

	for (int j = 0; j < M; ++j) {
		deque< pair< int, int > > Q;
		for (int i = 0; i < N; ++i) {
			while (!Q.empty() && Q.back().first >= mi[i][j])
				Q.pop_back();

			Q.push_back(make_pair(mi[i][j], i));

			while (!Q.empty() && Q.front().second < i - A + 1)
				Q.pop_front();

			mi[i][j] = Q.front().first;
		}
	}

	long long sum = 0;
	for (int i = A-1; i < N; ++i) {
		for (int j = B-1; j < M; ++j) sum += (long long)mi[i][j];
	}

	cout << sum << endl;

	// g[0]  given
	// g[1] = (g[0] * x + y) mod z
	// g[2] = (g[1] * x + y) mod z = (g[0]*x^2 + y * x + y ) mod z
	// g[3] = (g[2] * x + y) mod z = (g[0]*x^3 + y * x^2 + y * x + y) mod z

	// g[i] = (g[0] * x^i + y*(x^(i-1) + x^(i-2) + ... + x^0) ) mod z

	return 0;
}

