							//std::cout << "cost is " << cost6 << ", (" << i << ", " << j << ", " << k << ", " << ii << ", " << jj << ", " << kk << ")\n";
							if(i + j + k + ii + jj + kk < a[on])
								nxt[a[on] - (i + j + k + ii + jj + kk) - 1]++;
							ans = (ans + cost6 * dp(on + 1, prv, nxt)) % MOD;
							if(i + j + k + ii + jj + kk < a[on])
								nxt[a[on] - (i + j + k + ii + jj + kk) - 1]--;
							prv[0] -= j - i;
							prv[1] -= k - j;
							prv[2] -= -k;
							nxt[0] -= jj - ii;
							nxt[1] -= kk - jj;
							nxt[2] -= -kk;
						}
					}
				}
			}
		}
	}
	//std::cout << "on " << on << ", (" << prv[0] << ", " << prv[1] << ", " << prv[2] << ") - (" << nxt[0] << ", " << nxt[1] << ", " << nxt[2] << ") ans is " << ans << "\n";
