int egal_drepte(double A, double B, double C, double A1, double B1, double C1){
	if(A1 * A == 0 && A1 + A != 0) return 0;
	if(B1 * B == 0 && B1 + B != 0) return 0;
	if(C1 * C == 0 && C1 + C != 0) return 0;
	double v[6]; int  nr = 0;
