const int inf=0x3f3f3f3f;
char mp[30][30];
int n;
int a[50][26];
int dp[50][(1<<21)];
int dfs(int dep,int sta)
{
    int num=0;
    if(dp[dep][sta]!=inf /*|| dp[dep][sta]!=-inf*/)return dp[dep][sta];
    for(int i=0,k=dep;i<n;i++,k--)
    {
        if(sta>>i &1)
        {
            if(mp[k][i]=='a')num++;
            else if(mp[k][i]=='b')num--;
            break;
        }
    }
    if(dep>=2*n-2)return dp[dep][sta]=num;

    int &tmp=dp[dep][sta];
    if(dep%2!=0)
    {
        tmp=-inf;
        for(int i=0;i<26;i++)
        {
            int next=a[dep+1][i]&(sta|(sta<<1));
            if(next==0)continue;
            tmp=max(tmp,dfs(dep+1,next)+num);
        }
    }
    else
    {
        for(int i=0;i<26;i++)
        {
            int next=a[dep+1][i]&(sta|(sta<<1));
            if(next==0)continue;
            tmp=min(tmp,dfs(dep+1,next)+num);
        }
    }
    return tmp;
}

