const int MAXN = 1e6;
const int MOD = 1e9 + 7;

bool tree = true;
set<int> xs, ys;

int binpow(int a, int p) {
    if (p == 1)
        return a % MOD;

    if (!p)
        return 1;

    if (p & 1)
        return (binpow(a, p - 1) * a) % MOD;
    else
        return (binpow(a, p / 2) * binpow(a, p / 2)) % MOD;
}

vector<char> used(MAXN, false);

map<int, set<pair<int, int>>> x, y;
map<int, pair<int, int>> cbyid;

vector<vector<int>> g(MAXN);

void dfs(int v, int p = -1) {
    if (used[v]) {
        if (used[v] == 1) {
            tree = false;
        }
        used[v] = 2;
        return;
    }

    used[v] = true;
    auto coords = cbyid[v];
    xs.insert(coords.first);
    ys.insert(coords.second);

    for (auto i : g[v])
        if (i != p)
            dfs(i, v);

    used[v] = 2;
}

