        int choose = (long long)(amount-dist )*(amount - dist)%moder;

        int some = (long long)factor[dist+1] * factor[ amount - dist -1 ] %moder;

        result = ( result + (long long)choose*some%moder )%moder;
    }

    printf("%d", result );
}

