typedef long long LL;
LL N = 10000001;

LL* primes = new LL[N];
LL* primecounts = new LL[N];
LL* smallprime = new LL[N];
LL* mobiusval = new LL[N];
LL* divisorcounts = new LL[N];
LL* divisortotals = new LL[N];

LL mobius(LL n, LL p)
{
    if(n==1)
        return -1;
    else
    {
        if(smallprime[n]==p)
            return 0;
        else
            return -1*mobius(n/smallprime[n], smallprime[n]);
    }
}


int main()
{


    for(LL i=0; i<N; i++)
    {
        primes[i] = 1;
        smallprime[i] = 0;
        divisorcounts[i] = 0;
    }


    primes[0] = 0;
    primes[1] = 0;
    for(LL i=2; i< 4000; i++)
    {
        LL c = 0 ;
        while(c<N)
        {
            if(i!=c)
                primes[c] = 0;
            if(smallprime[c]==0)
                smallprime[c]=i;
            c += i;
        }
    }
    for(LL i=2; i<N; i++)
    {
        if (smallprime[i]==0)
            smallprime[i] = i;
    }

    mobiusval[0] = 0;
    primecounts[0] = 0;
    for(LL i=1; i<N; i++)
    {
        primecounts[i] = primecounts[i-1]+primes[i];
        mobiusval[i] = mobius(i,10000001);
    }


    LL n;
    cin>>n;
    LL ans = 0;




    for(LL i=2; i<n+1; i++)
        ans += mobiusval[i]*(n/i)*(n/i);
    ans -= (n-1);
    ans = ans/2;

    LL m = LL( pow((n+ 0.5), 0.5) );

    for(LL i=2; i<n+1; i++)
        divisorcounts[smallprime[i]]++;

    divisortotals[0] = 0;
    for(LL i=1; i<n+1; i++)
    {
        divisortotals[i] = divisortotals[i-1]+divisorcounts[i];
    }


    LL dis3=0,dis2;
    for(LL i=m+1; i<=n; i++)
    {
        if(primes[i]==1)
        {
            dis3+=(divisortotals[i-1] - divisortotals[n/i])*divisorcounts[i];
        }
    }

    LL a = primecounts[n] - primecounts[n/2];
