using namespace std;
const int NN = 5100;
INT dp[NN], t[2];
int p[2];
int main() {
	for(int i = 0; i < 2; i ++) cin >> p[i] >> t[i];
	int h, s;
	cin >> h >> s;
	for(int i = 1; i <= h; i ++) {
		dp[i] = 1e18;
		for(int j = 1; j <= h; j ++) {
			for(int k = 0; k < 2; k ++) {
				INT T = t[k] * j;
				if(T < t[k ^ 1]) continue;
				INT tmp = min(5000ll, (T - t[k^1]) / t[k^1]) * (p[k^1] - s);
				tmp += (j - 1) * (p[k] - s);
				tmp += (p[1] + p[0] - s);
				dp[i] = min(dp[i], T + dp[max(0ll, i - tmp)]);
			}
		}
		INT st = 0, ed = 1LL * 5001 * min(t[1], t[0]);
		while(st + 1 < ed) {
			INT md = (st + ed) >> 1;
			INT tmp = 0;
			for(int k = 0; k < 2; k ++) {
				tmp += (md / t[k]) * (p[k] - s);
			}
			if(tmp >= i) ed = md;
			else st = md;
		}
		dp[i] = min(dp[i], ed);
	}
	cout << dp[h] << endl;
}

