const int mod = 998244353;

      // int md = 1000000007;
long long binpow(long long a, long long n)
{
	if (n == 0)return 1;
	if (n % 2 == 0)
	{
		long long b = (binpow(a, n / 2))%mod;
		return b * b%mod;
	}
	else
		return (binpow(a, n - 1) * a)%mod;
}

