template<class T> inline T mypow (T x, int n)
{
	if (n == 0)
		return 1;
	T y = 1;
	while (n > 1) {
		if (n % 2 == 0) {
			x = x*x;
			n = n / 2;
		}
		else {
			y = x*y;
			x = x*x;
			n = (n - 1) / 2;
		}
	}
	return x*y;
}
