constexpr int N = 1<<19, P = 998244353,
	gen = 3, INF = 0x3f3f3f3f;
int n, k, m, _f; vint f, g;

inl ll fpow (ll a, ll b) {
	ll res = 1; a %= P;
	for (; b; b >>= 1) {
		if (b & 1) res = res * a % P;
		a = a * a % P;
	}
	return res;
}
inl void henkan (vint &f, int l) {
	static int tr[N], lst = tr[0] = 0;
	if (lst != l) { lst = l; 
		for (int i = 1; i < 1<<l; ++i)
			tr[i] = tr[i>>1]>>1|((1<<l-1) * (i & 1)); }
	for (int i = 1; i < 1<<l; ++i)
		if (tr[i] < i) swap (f[tr[i]], f[i]);
}
#define clog2(x) ceil (log2 (x))
inl void NTT (vint &f, int l, bool rev) {
	f.resize (1<<l, 0); henkan (f, l);
	for (int len = 2; len <= 1<<l; len <<= 1) {
		const int w_n = fpow (gen, (P-1)/len);
		ll w = 1, g, h;
		for (int st = 0; st < 1<<l; st += len, w = 1)
			for (int i = st; i < st + len/2; ++i, (w *= w_n) %= P)
				g = f[i], h = f[i + len/2] * w % P,
				f[i] = (g + h) % P,
				f[i + len/2] = (P + g - h) % P;
	}
	if (!rev) return;
	const ll invl = fpow (1<<l, P - 2);
	for (int i = 0; i < 1<<l; ++i)
		f[i] = f[i] * invl % P;
	reverse (begin (f) + 1, end (f));
}

inl void pow2 (vint &f, int mod = INF) {
	int len = f.size () * 2 - 1, l = clog2 (len);
	NTT (f, l, 0);
	for (int i = 0; i < 1<<l; ++i)
		f[i] = (ll) f[i] * f[i] % P;
	NTT (f, l, 1);
	f.resize (mod < INF ? mod : len, 0);
}

