bool chk(string x, string y)
{
  if (y.size() < x.size())
    return false;
  else
  {
    int n1 = x.size();
    int n2 = y.size();
    int diff = n2 - n1;
    for (int i = 0; i <= diff; i++)
    {
      string sa(diff - i, '1'); string sb(i, '1');
      string temp = sa + x + sb;
      if (temp == y) return true;
    }
    return false;
  }

}



