inline void matMult(Matrix &m, Matrix &m1, Matrix &m2)
{
	REP(i,0,1)
	{
		REP(j,0,1)
		{
			m.mat[i][j]=0;
			REP(k,0,1)
			{
				m.mat[i][j]=(m.mat[i][j]+m1.mat[i][k]*m2.mat[k][j]);
			}
		}
	}
}

inline Matrix expo(Matrix &M, LL n)
{
	Matrix ret;
	ret.init();

	if(n==0) return ret;
	if(n==1) return M;

	Matrix P=M;

	while(n!=0)
	{
		if(n&1)
		{
			aux=ret;
			matMult(ret,aux,P);
		}

		n>>=1;

		aux=P; matMult(P,aux,aux);
	}

	return ret;
}


