    Matrix M;
    M.mat[0][0]=1;
    M.mat[0][1]=1;
    M.mat[1][0]=1;
    M.mat[1][1]=0;
    Matrix res=expo(M,n-1);
    return res.mat[0][0]*2+res.mat[0][1];
}

