const int md = 1e9+7;


int n, dp[N][1010][2];
int calc(int idx, int open, bool canTake)
{

	if(idx == n*2)
		return 0;

	if(dp[idx][open][canTake]!=-1)
		return dp[idx][open][canTake];

	int ret = 0;
	bool canOpen = (open+1) <= (n*2-idx-1);
	bool canClose =  open>0;

	if(canOpen && canClose)
	{

		if(canTake)
		{

			int takeRight = calc(idx+1, open+1, 1) + calc(idx+1, open-1, 0);
			int takeLeft = calc(idx+1, open+1, 0) + calc(idx+1, open-1, 1);
			ret = 1 + max(takeRight, takeLeft);

		}else{

			ret = calc(idx+1, open+1, 1) + calc(idx+1, open-1, 1);

		}

	}else if(canOpen){

		ret = canTake+calc(idx+1, open+1, !canTake);

	}else if(canClose){

		ret = canTake+calc(idx+1, open-1, !canTake);

	}
	return dp[idx][open][canTake] = ret % md;
}
