void Dijkstra(const int64 source) {
    MinCells = vector<int64>(K, oo);
    priority_queue<int64, vector<int64>, greater<int64>> vertices;
    vertices.push(source);
    while (!vertices.empty()) {
        int64 x = vertices.top();
        vertices.pop();
        if (MinCells[x % K] < oo)
            continue;
        MinCells[x % K] = x;
        for (int64 &e: Edges)
            if (MinCells[(x + e) % K] == oo)
                vertices.push(x + e);
    }
}

void GetAccessibleCells() {
    Dijkstra(1);
    Heap = priority_queue<Cell>();
    for (int i = 0; i < N; ++i)
        if (Used[i] == 0 && Cells[i].position >= MinCells[Cells[i].position % K])
            Heap.push(Cells[i]);
}

void Read() {
    int64 H;
    cin >> H >> N >> M >> K;
    Cells = vector<Cell>(N);
    Used = vector<int>(N, 0);
    for (int i = 0; i < N; ++i) {
        cin >> Cells[i].position >> Cells[i].value;
        Cells[i].index = i;
    }
    Edges.push_back(K);
    GetAccessibleCells();
}

int main() {
    Read();
    for (; M > 0; --M) {
        int type;
        cin >> type;
        if (type == 1) {
            int64 edge;
            cin >> edge;
            Edges.push_back(edge);
            GetAccessibleCells();
        }
        if (type == 2) {
            int index, cost;
            cin >> index >> cost;
            --index;
            Cells[index].value -= cost;
            if (Used[index] == 0 && Cells[index].position >= MinCells[Cells[index].position % K])
                Heap.push(Cells[index]);
        }
        if (type == 3) {
            while (!Heap.empty() && (Used[Heap.top().index] == 1 || Heap.top().value != Cells[Heap.top().index].value))
                Heap.pop();
            if (Heap.empty()) {
                printf("0\n");
            } else {
                printf("%d\n", Heap.top().value);
                Used[Heap.top().index] = 1;
                Heap.pop();
            }
        }
    }
    return 0;
}

