#include<bits/stdc++.h>
using namespace std;
const int INF=0x3f3f3f3f;
typedef long long ll;
typedef pair<int,int> PI;
deque<PI> dq[4];
int dp[2][2][100010];
int main(){
	int n,k,last=0,l,r;
	scanf("%d%d",&n,&k);
	memset(dp[0],0x3f,sizeof dp[0]);
	dp[0][0][0]=0;
	for(int i=1;i<=k;i++){
		int cur=i&1,pre=!cur;
		scanf("%d%d",&l,&r);
		for(int j=0;j<4;j++) dq[j].clear();
		memset(dp[cur],0x3f,sizeof dp[cur]);
		int min_diff[4]={l-last,l-last,0,1},max_diff[4]={r-1-last,r-last,r-l,r-l};
		int pre_layer[4]={0,0,1,1},cur_layer[4]={0,1,0,1};
		int add[4]={2,1,1,2};
		int idx[4]={0,0,0,0};
		for(int w=0;w<=n;w++){
			for(int j=0;j<4;j++){
				while(w-idx[j]>=min_diff[j]){
					while(!dq[j].empty() && dq[j].back().first>=dp[pre][pre_layer[j]][idx[j]])
						dq[j].pop_back();
					dq[j].push_back(PI(dp[pre][pre_layer[j]][idx[j]],idx[j]));
					idx[j]++;
				}
				while(!dq[j].empty() && w-dq[j].front().second>max_diff[j])
					dq[j].pop_front();
				if(dq[j].empty()) dp[cur][cur_layer[j]][w]=min(dp[cur][cur_layer[j]][w],INF);
				else dp[cur][cur_layer[j]][w]=min(dp[cur][cur_layer[j]][w],dq[j].front().first+add[j]);
			}
			if(w-(r-last)>=0) dp[cur][0][w]=min(dp[cur][0][w],dp[pre][0][w-(r-last)]);
			dp[cur][1][w]=min(dp[cur][1][w],dp[pre][1][w]);
		}
		last=r;
	}
	int ans=min(n-(2*n-last)>=0?dp[k&1][0][n-(2*n-last)]:INF,dp[k&1][1][n]);
	if(ans==INF) puts("Hungry");
	else printf("Full\n%d\n",ans);
	return 0;
}

