int find( int x ) {
	if ( x == parent[x] ) return x;
	return parent[x] = find(parent[x]);
}

void merge(int a, int b) {
	a = find(a); b = find(b);
	if ( a == b ) return;
	nc --;
	parent[b] = a;
}

ll fmp(ll x, int e) {
	if ( e == 0 ) return 1;
	ll w = fmp(x, e/2);
	w = (w * w) % MOD;
	if ( e&1 ) w = (w * x) % MOD;
	return w;
}

