void merge(int u, int v) {
	u = getroot(u), v = getroot(v);
	if(u != v) {
		sz[u] += sz[v];
		snm[v] = u;
	}
}

int isok(ll a, ll b, ll p) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % p;
		}
		a = a * a % p;
		b >>= 1;
	}
	return(res == 1 ? p : 1);
}

int binpow(ll a, ll b) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % mod;
		}
		a = a * a % mod;
		b >>= 1;
	}
	return(res);
}

