        cin >> c[i];
    sort(c, c + N);
    int mask = 0, cur = 0;
    for (; cur < N && c[cur] == 1; cur++)
        mask |= 1 << cur;
    cout << (solve(mask) ? "YES" : "NO") << endl;
    return 0;
}

