int pw(int a,int p) {
    int r=1;
    for(;p;p>>=1,a=mul(a,a)) if(p&1)
        r=mul(r,a);
    return r;
}
void pre() {
    f[0]=1;
    FOR(i,1,200000)
        f[i]=(LL)i*f[i-1]%mod;
    f_inv[200000]=pw(f[200000],mod-2);
    FORD(i,200000-1,0)
        f_inv[i]=(LL)(i+1)*f_inv[i+1]%mod;    
}
int C(int n,int m) {
    int c=f[n];
    c=mul(c,f_inv[m]);
    c=mul(c,f_inv[n-m]);
    return c;
}
