struct el {
    int value;
    int ind;
};

bool cmp (el a, el b) {
    return a.value < b.value;
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);


    int n, val; cin >> n;
    vector<el> v(n);
    map<int, int> m;

    for (int i = 0; i < n; i++) {
        cin >> val;
        el e = {val, i};
        v[i] = e;
        m[i] = val;
    }

    sort(v.begin(), v.end(), cmp);

    long long int ans = 0;
    for (int i = 0; i < n; i++) {
        map<int, int>::const_iterator pos = m.find(v[i].ind);
        if (pos != m.begin() && pos != --m.end())
            ans += min(prev(pos)->second, next(pos)->second);
        else if (m.size() > 2) ans += v[i].value;
        m.erase(pos);
    }

    cout << ans;

    return 0;
}

