ll cal(ll i)
{
    if(i==0)
    {
        return 1;
    }
    ll ini_sum=2*i*i-2*i+1;
    ll up = x-(i-1),down=x+(i-1),left=y-(i-1),right=y+(i-1),f=0,f1=0;
    if(left<1)
