/**
 * @namespace factorial
 * @brief 順列数関連の関数のまとめ
 * @details
 *   - combination
 *   - permutation
 *   - multiChoose
 */
namespace factorial {
    //! 順列数を格納する配列のサイズ
    constexpr int size =
#    ifdef FACTORIAL_SIZE
        FACTORIAL_SIZE;
#    else
        3123456;
#    endif
    //! 前計算ができているかどうかのフラグ
    bool is_build = false;

    //! 順列数を格納する配列
    ModInt factorial[size];
    //! (順列数)^-1を格納する配列
    ModInt inverse_factorial[size];

    /**
     * @brief 順列数の前計算
     * @details
     *   順列数と，その逆元を[0,size)まで求める.
     *   計算量は，O(size + log(mod))
     */
    void build() {
        is_build     = true;
        factorial[0] = 1;
        for (int i = 1; i < size; i++) {
            factorial[i] = factorial[i - 1] * i;
        }
        inverse_factorial[size - 1] = inv(factorial[size - 1]);
        for (int i = size - 1; i >= 1; i--) {
            inverse_factorial[i - 1] = inverse_factorial[i] * i;
        }
    }

    /**
     * @brief nPkを求める
     * @details
     *   前計算がしてあれば O(1)．前計算してない場合は is_build
     * を読み取って前計算をする．
     */
    inline ModInt permutation(int n, int k) {
        if (k < 0 || k > n) return ModInt::raw(0);
        if (!is_build) build();
        return factorial[n] * inverse_factorial[n - k];
    }

    /**
     * @brief nCkを求める
     * @details
     *   前計算がしてあれば O(1)．前計算してない場合は is_build
     * を読み取って前計算をする．
     */
    inline ModInt combination(int n, int k) {
        if (k < 0 || k > n) return ModInt::raw(0);
        if (!is_build) build();
        return factorial[n] * inverse_factorial[k] * inverse_factorial[n - k];
    }
} // namespace factorial
  /* #endregion */
  /* #endregion */
  /*</body>*/
#endif

namespace factorial {
    /**
     * @brief 重複組合せ
     * @param n 何種類のものを
     * @param r いくつ並べるか
     * @return ModInt nHr
     */
    ModInt multiChoose(int n, int r) {
        if (n == 0) {
            return ModInt(r == 0 ? 1 : 0);
        }
        if (r == 0) {
            return ModInt(1);
        }
        return combination(n + r - 1, r);
    }

    /**
     * @brief 上限付き重複組合せ
     * @details 計算量 O(min(n, r / lim))
     * @param n 何種類のものを
     * @param r いくつ並べるか
     * @param lim 1種類のものを選べる上限
     * @return ModInt
     */
    ModInt multiChoose(int n, int r, int lim) {
        if (n == 0) {
            return ModInt(r == 0 ? 1 : 0);
        }
        if (lim <= 0 && r > 0) {
            return ModInt(0);
        }
        if (r == 0) {
            return ModInt(lim < 0 ? 0 : 1);
        }
        ModInt ret = 0;
        for (int i : range(n + 1)) {
            if (i * (lim + 1) > r) break;
            ret += ((i & 1) ? mod - 1 : 1) * combination(n, i)
                   * multiChoose(n, r - i * (lim + 1));
        }
        return ret;
    }
} // namespace factorial


int main() {
    /* write here */
    int p, s, r;
    scanf("%d%d%d", &p, &s, &r);
    ModInt ret = 0;
    for (int top : range(r, s + 1)) {
        ModInt tot = 0;
        for (int q : range(p)) {
            if (top * q > s - top) break;
            tot +=
                factorial::combination(p - 1, q)
                * factorial::multiChoose(p - q - 1, s - top - top * q, top - 1)
                * inv(q + 1);
        }
        ret += tot;
    }
    ret *= inv(factorial::multiChoose(p, s - r));
    printf("%lld\n", *ret);
    return 0;
}

