vector<int64_t> fac({1});

int64_t e525()
{
    while(fac.back() * (int64_t) fac.size() < 1 + (int64_t)1e16)
        fac.push_back(fac.back() * (int64_t) fac.size());

    DEBUG(fac.size());
    size_t n, k;
    int64_t sum;
    cin >> n >> k >> sum;

    vector<int64_t> a(n);
    cin >> a;

    /* maximum sum that we can get with the remaining items */
    /* if j out of k factorials are already used            */
    vector<vector<int64_t>> ub(n + 1, vector<int64_t>(k + 1));
    for(size_t i = n - 1; i < n; -- i)
        for(size_t j = k; j < k + 1; -- j)
            if(j == k || (int64_t) fac.size() < a[i] + 1 || sum < fac[a[i]])
                ub[i][j] = min(sum, a[i] + ub[i + 1][j]);
            else
                ub[i][j] = min(sum, max(a[i] + ub[i + 1][j], fac[a[i]] + ub[i + 1][j + 1]));

    vector<map<int64_t, int64_t>> cnt(k + 1);
    cnt[0][0] = 1;

    for(size_t i = 0; 2 * i < n; ++i)
        for(size_t j = min(i + 1, k); j < k + 1; --j) /* used */
        {
            if(j < k && a[i] < (int64_t) fac.size() && fac[a[i]] < sum + 1){
                const auto rest = ub[i + 1][j + 1] + fac[a[i]];

                auto iter = sum < rest + 1 ? begin(cnt[j]) : cnt[j].lower_bound(sum - rest);

                for(; iter != end(cnt[j]); ++ iter)
                    if(iter->first + fac[a[i]] < sum + 1)
                        cnt[j + 1][iter->first + fac[a[i]]] += iter->second;
                    else
                        break;

                if (ub[i + 1][j + 1] < sum)
                    cnt[j + 1].erase(begin(cnt[j + 1]), cnt[j + 1].lower_bound(sum - ub[i + 1][j + 1]));
            }

            const auto rest = ub[i + 1][ j ] + a[i];
            vector<pair<int64_t, int64_t>> buf;
            auto iter = sum < rest + 1 ? begin(cnt[j]) : cnt[j].lower_bound(sum - rest);

            for(; iter != end(cnt[j]); ++ iter)
                if(iter->first + a[i] < sum + 1)
                    buf.emplace_back(iter->first + a[i], iter->second);
                else
                    break;

            if(ub[i + 1][j] < sum)
                cnt[j].erase(begin(cnt[j]), cnt[j].lower_bound(sum - ub[i + 1][j]));

            for(const auto & pr: buf)
                cnt[j][pr.first] += pr.second;
        }

    vector<unordered_map<int64_t, int64_t>> half;
    for(auto & m: cnt)
        half.emplace_back(begin(m), end(m)), m.clear();

    cnt[0][0] = 1;

    for(size_t i = (n + 1) / 2; i < n; ++ i)
        for(size_t j = k; j < k + 1; --j) /* used */
        {
            if(j < k && a[i] < (int64_t) fac.size() && fac[a[i]] < sum + 1){
                auto iter = begin(cnt[j]); // sum < rest + 1 ? begin(cnt[j]) : cnt[j].lower_bound(sum - rest);

                for(; iter != end(cnt[j]); ++ iter)
                    if(iter->first + fac[a[i]] < sum + 1)
                        cnt[j + 1][iter->first + fac[a[i]]] += iter->second;
                    else
                        break;

            }
            vector<pair<int64_t, int64_t>> buf;
            auto iter = begin(cnt[j]); // sum < rest + 1 ? begin(cnt[j]) : cnt[j].lower_bound(sum - rest);

            for(; iter != end(cnt[j]); ++ iter)
                if(iter->first + a[i] < sum + 1)
                    buf.emplace_back(iter->first + a[i], iter->second);
                else
                    break;

            for(const auto & pr: buf)
                cnt[j][pr.first] += pr.second;
        }

    int64_t val = 0;

    for(size_t i = 0; i < cnt.size(); ++ i)
        for(const auto & pr: cnt[i])
            if(pr.first < sum + 1)
                for(size_t j = 0; i + j < k + 1; ++ j)
                {
                    const auto iter = half[j].find(sum - pr.first);
                    if(iter != end(half[j]))
                        val += pr.second * iter->second;
                }
            else
                break;

    return val;
}

