using namespace std;

long long N, K, A, B;

int main() {
    cin >> N >> K >> A >> B;

    long long cost = 0;

    if (K == 1) 
    { cout << (A * (N - 1)) << endl; return (0); }

    while (N != 1) {
        if (N % K == 0) {
            cost += min(A * (N - (N / K)), B);
            N = N / K;
        }

        else { 
            if (N < K) { cost += (A * (N - 1)); N = 1; }
            else {
                cost += (A * (N % K));
                N -= (N % K);
            }
        }
    }

    cout << cost << endl;
    return (0);
}

