struct rib {  
    int b, u, c, f , back;  
};
int dx[] = {1 , -1 , 0 , 0};
int dy[] = {0 , 0 , 1 , -1};
vector <rib> g[maxn];
int n , m;
int s , t;
int V;
void add_rib (int a, int b, int u, int c) {  
    // u = capacity  
    // c = cost per flow (maybe double)  
    // add edge between a and b  
    rib r1 = { b, u, c, 0, (int)g[b].size() };  
    rib r2 = { a, 0, -c, 0, (int)g[a].size() };  
    g[a].push_back (r1);  
    g[b].push_back (r2);  
}
int mcmf(){
	int flow = 0,  cost = 0;  
    while (flow < inf) {  
        vector<int> id (V, 0);  
        vector<int> d (V, inf);  
        vector<int> q (V);  
        vector<int> p (V);  
        vector<int> p_rib (V);  
        int qh=0, qt=0;  
        q[qt++] = s;  
        d[s] = 0;  
        while (qh != qt) {  
            int v = q[qh++];  
            id[v] = 2;  
            if (qh == V)  qh = 0;  
            for (int i=0; i<g[v].size(); ++i) {  
                rib & r = g[v][i];  
                if (r.f < r.u && d[v] + r.c < d[r.b]) {  
                    d[r.b] = d[v] + r.c;  
                    if (id[r.b] == 0) {  
                        q[qt++] = r.b;  
                        if (qt == V)  qt = 0;  
                    }  
                    else if (id[r.b] == 2) {  
                        if (--qh == -1)  qh = V-1;  
                        q[qh] = r.b;  
                    }  
                    id[r.b] = 1;  
                    p[r.b] = v;  
                    p_rib[r.b] = i;  
                }  
            }  
        }  
        if (d[t] == inf)  break;  
        int addflow = inf - flow;  
        for (int v=t; v!=s; v=p[v]) {  
            int pv = p[v];  int pr = p_rib[v];  
            addflow = min (addflow, g[pv][pr].u - g[pv][pr].f);  
        }  
        for (int v=t; v!=s; v=p[v]) {  
            int pv = p[v];  int pr = p_rib[v],  r = g[pv][pr].back;  
            g[pv][pr].f += addflow;  
            g[v][r].f -= addflow;  
            cost += g[pv][pr].c * addflow;  
        }  
        flow += addflow;  
    }
    return cost;
}

