const int N = 1009;
int T = 0, cst[N * N];

void build(int b, int w, int x) {
	int bb = b, tot = 0;
	while (bb != b || !T) {
		if (bb >= x)
			bb -= x;
		else
			++tot, bb += (w - x);
		cst[T++] = tot;
	}
}

ll calc(ll a, ll t) {
	return a - cst[T - 1] * (t / T) - cst[t % T];
}

ll bs(ll a, ll c) {
	if (c <= a)
		return 0;
	ll st = 1, ed = (1LL << 62);
	while (st < ed) {
		ll md = (st + ed) / 2LL;
		if (c - md > calc(a, md - 1))
			st = md + 1;
		else
			ed = md;
	}
	return st;
}

