typedef long long ll;

ll gcd(ll a, ll b){
	while(b != 0){
		a %= b;
		swap(a, b);
	}
	return a;
}

int main(){
	ll n, k; cin >> n >> k;
	ll multiple = n*k;
	ll x, y; cin >> x >> y;
	ll mn = 100000000000, mx = 0;

	for(ll i = abs(y - x); i <= multiple; i+= k){
		if(i == 0)
			continue;
		ll value = gcd(multiple, i);
		mn = min(mn, value);
		mx = max(mx, value);
	}
	for(ll i = k - y - x; i <= multiple; i+= k){
		if(i == 0)
			continue;
		ll value = gcd(multiple, i);
		mn = min(mn, value);
		mx = max(mx, value);
	}
	cout << multiple/mx << " " << multiple/mn << endl;
}


