void dfs(int b, int g, int r)
{
	if (used[b][g][r]) return;
	used[b][g][r] = true;
	if (b >= 1 && g >= 1) dfs(b - 1, g - 1, r + 1);
	if (b >= 1 && r >= 1) dfs(b - 1, g + 1, r - 1);
	if (g >= 1 && r >= 1) dfs(b + 1, g - 1, r - 1);
	if (b >= 2) dfs(b - 1, g, r);
	if (g >= 2) dfs(b, g - 1, r);
	if (r >= 2) dfs(b, g, r - 1);
}

