bool check(int x,int y,int nx,int ny,int gx,int gy)
{
    if(x==gx&&gy<y)
    {
        if(nx>x)
            return 1;
    }
    if(nx==gx&&gy<ny)
    {
        if(x>nx)
            return 1;
    }
    return 0;
}
int dx[]={0,0,-1,1};
int dy[]={1,-1,0,0};
void bfs(int sx,int sy)
{
    queue<node>q;
    d[sx][sy][0][0]=0;
    node tmp;tmp.x=sx;tmp.y=sy;tmp.s1=0;tmp.s2=0;
    q.push(tmp);
    while(!q.empty())
    {
        node now=q.front();
        q.pop();
        int x=now.x;
        int y=now.y;
        int s1=now.s1;
        int s2=now.s2;
        int nx,ny,ns1,ns2;
        for(int k=0;k<4;k++)
        {
            int nx=x+dx[k];
            int ny=y+dy[k];
            ns1=s1;ns2=s2;
            if(!in(nx,ny)||s[nx][ny]!='.')
                continue;
            for(int i=0;i<cnt;i++)
            {
                if(check(x,y,nx,ny,cx[i],cy[i]))
                    ns1^=(1<<i);
            }
            for(int i=0;i<bcnt;i++)
            {
                if(check(x,y,nx,ny,bx[i],by[i]))
                    ns2^=(1<<i);
            }
            if(d[nx][ny][ns1][ns2]==-1)
            {
                d[nx][ny][ns1][ns2]=d[x][y][s1][s2]+1;
                tmp.x=nx;tmp.y=ny;tmp.s1=ns1;tmp.s2=ns2;
                q.push(tmp);
            }
        }
    }
}

