using namespace std;
typedef long long ll;
typedef long double ldb;
const int Mod=1e9+7;
const int blo=32767;
const ldb Pi=acos(-1.0);
struct complex{
	ldb x,y;
	complex (ldb xx=0,ldb yy=0){ x=xx; y=yy;}
};
ll n; int m,bit,len,rev[550000];
ll fac[1100000],inv[1100000],invfac[1100000];
ll A[550000],B[550000],aa[550000],bb[550000];
complex a[550000],b[550000],c[550000],d[550000],
		e[550000],f[550000],g[550000],h[550000];
complex operator+(complex a,complex b){ return complex(a.x+b.x,a.y+b.y);}
complex operator-(complex a,complex b){ return complex(a.x-b.x,a.y-b.y);}
complex operator*(complex a,complex b){ return complex(a.x*b.x-a.y*b.y,a.x*b.y+a.y*b.x);} 

void FFT(complex *A,int type){
	for (int i=0;i<len;i++) 
		if (i<rev[i]) swap(A[i],A[rev[i]]);
	for (int mid=1;mid<len;mid<<=1){
		complex Wn(cos(Pi/mid),type*sin(Pi/mid));
		for (int R=mid<<1,j=0;j<len;j+=R){
			complex w(1,0);
			for (int k=0;k<mid;k++,w=w*Wn){
				complex x=A[j+k],y=w*A[j+mid+k];
				A[j+k]=x+y; A[j+mid+k]=x-y;
			}
		}
	}
}
void MTT(ll *A,ll *B,ll *res){
	memset(a,0,sizeof(a)); memset(b,0,sizeof(b));
	memset(c,0,sizeof(c)); memset(d,0,sizeof(d));
	memset(e,0,sizeof(e)); memset(f,0,sizeof(f));
	memset(g,0,sizeof(g)); memset(h,0,sizeof(h));
	for(int i=0;i<=m;i++) a[i].x=A[i]/blo,b[i].x=A[i]%blo;
	for(int i=0;i<=m;i++) c[i].x=B[i]/blo,d[i].x=B[i]%blo;
	FFT(a,1); FFT(b,1);
	FFT(c,1); FFT(d,1);
	for(int i=0;i<len;i++){
		e[i]=a[i]*c[i]; f[i]=a[i]*d[i];
		g[i]=b[i]*c[i]; h[i]=b[i]*d[i];
	}
	FFT(e,-1); FFT(f,-1);
	FFT(g,-1); FFT(h,-1);
	for (int i=0;i<=m;i++) res[i]=((ll)(e[i].x/len+0.5)%Mod*blo%Mod*blo%Mod+
									(ll)(f[i].x/len+0.5)%Mod*blo%Mod+
									(ll)(g[i].x/len+0.5)%Mod*blo%Mod+
									(ll)(h[i].x/len+0.5)%Mod)%Mod;
}
void mult(ll *A,ll *B,ll x){
    ll tmp=1;
    for (int i=0;i<=m;i++) bb[i]=B[i]*tmp%Mod,tmp=tmp*x%Mod;
    for (int i=0;i<=m;i++) aa[i]=A[i];
    MTT(aa,bb,B);
}
ll C(int n,int m){
	if (n<m) return 0;
	return fac[n]*invfac[m]%Mod*invfac[n-m]%Mod;
}
int main(){
	scanf("%lld%d",&n,&m);
	if (n>m){ puts("0"); return 0;}
	fac[0]=1; for (int i=1;i<=1000000;i++) fac[i]=fac[i-1]*i%Mod;
	inv[1]=1; for (int i=2;i<=1000000;i++) inv[i]=(Mod-Mod/i)*inv[Mod%i]%Mod;
	invfac[0]=1; for (int i=1;i<=1000000;i++) invfac[i]=invfac[i-1]*inv[i]%Mod;

	len=1; bit=0; while (len<=m+m) len<<=1,bit++;
	for (int i=0;i<len;i++) rev[i]=(rev[i>>1]>>1)|((i&1)<<(bit-1));

    B[0]=1;
    for (int i=1;i<=m;i++) A[i]=invfac[i];
	ll t=2;
	while (n){
		if (n&1) mult(A,B,t);
		mult(A,A,t);
