inline void putint(int x)
{
    char s[9];
    int l = 0;
    while (x)
        s[l++] = '0' + (x % 10), x /= 10;
    while (l--)
        putc(s[l], stdout);
    putc(' ', stdout);
}

inline int getint()
{
    char ch;

    while (ch = getchar(), ch < '0' || ch > '9');

    int x = ch - '0';
    while (ch = getchar(), ch >= '0' && ch <= '9')
    {
        x *= 10;
        x += ch - '0';
    }
    return x;
}

void solve(int n)
{
    int m;
    int x, y;
    m = getint();

    Tree Car;

    for (int i = 1; i <= n; i++)
        Car.insert(mp(i, mp(0, i)));

    set<int> used;
    for (int i = 1; i <= n; i++)
        used.insert(i);

    for (int i = 0; i < m; i++)
    {
        x = getint();
        y = getint();
        used.erase(x);
        y--;

        Tree::iterator it = Car.find_by_order(y);
        if ((it -> second).first != 0 && (it -> second).first != x)
        {
            printf("-1\n");
            return;
        }
        Car.insert(mp(-i, mp(x, (it -> second).second)));
        Car.erase(it);
    }

    for (Tree::iterator it = Car.begin(); it != Car.end(); it++)
        if ((it -> second).first == 0)
            (it -> second).first = *used.begin(),
            used.erase(used.begin());

    vector<int> ans(n + 1, 0);
    vector<char> Used(n + 1, 0);

    for (Tree::iterator it = Car.begin(); it != Car.end(); it++)
        ans[(it -> second).second] = (it -> second).first;

    for (int i = 1; i <= n; i++)
        Used[ans[i]] = 1;
    bool ok = true;
    for (int i = 1; i <= n; i++)
        ok &= Used[i];
    if (!ok)
    {
        printf("-1\n");
        return;
    }

    for (int i = 1; i <= n; i++)
        putint(ans[i]);
    printf("\n");
}

