  if (x >= mod) x -= mod;
}
int sum(int x, int y) {
  add(x, y);
  return x;
}
int mult(int x, int y) {
  return (x * 1ll * y) % mod;
}

ll f, w, h;
int fact[N], rev[N];

int pw(int x, int y) {
  int res = 1;
  while (y) {
    if (y & 1) res = mult(res, x);
    x = mult(x, x), y >>= 1;
  }
  return res;
}
void precalc() {
  fact[0] = fact[1] = rev[1] = rev[0] = 1;
  rep(i, 2, N - 1) {
    fact[i] = mult(fact[i - 1], i);
    rev[i] = pw(fact[i], mod - 2);
  }
}
int C(ll n, ll k) {
  if (n < k) return 0;
  return mult(mult(fact[n], rev[n - k]), rev[k]);
  int res = 1;
  rep(i, n - k + 1, n)
    res = mult(res, i);
  rep(i, 2, k)
    res = mult(res, pw(i, mod - 2));
  return res;
}

