  int n = min(f, w) * 2 + (max(f, w) != min(f, w));
  rep(i, 1, f + w) {
    {
      ///W
      //if (i == n && f > w) continue;
      int W = (i + 1) / 2, F = i - W;
      add(good, mult(C(w - h * W - 1,W - 1), C(f - 1, F - 1)));
      add(total, mult(C(w - 1, W - 1), C(f - 1, F - 1)));
    }
    {
      ///F
      //if (i == n && f < w) continue;
      int F = (i + 1) / 2, W = i - F;
      add(good, mult(C(w - h * W - 1, W - 1), C(f - 1, F - 1)));
      add(total, mult(C(w - 1, W - 1), C(f - 1, F - 1)));
