string s;
pii tr[1010101];
pii merge(pii a, pii b) {
    if (b.first == 0) {
        a.second += b.second;
        return a;
    } else {
        b.first += a.first;
        return b;
    }
}
void build(int cur, int l, int r) {
    if (l == r) {
        if (s[l] == 'A') {
            tr[cur] = {0, 1};
        } else {
            tr[cur] = {1, 0};
        }
    } else {
        int m = (l + r) / 2;
        int dcur = cur + cur;
        build(dcur, l, m);
        build(dcur + 1, m + 1, r);
        tr[cur] = merge(tr[dcur], tr[dcur + 1]);
    }
}
pii get(int cur, int l, int r, int x, int y) {
    if (x > r || y < l) return {};
    if (x <= l && r <= y) return tr[cur];
    int m = (l + r) / 2;
    int dcur = cur + cur;
    return merge(get(dcur, l, m, x, y), get(dcur + 1, m + 1, r, x, y));
}

int solve() {
    string t;
    cin >> s >> t;
    int n = (int) s.size();
    s += t;
    int sn = (int) s.size();
    build(1, 0, sn - 1);
    int q;
    cin >> q;
    string ans;
    while (q--) {
        int l[2], r[2];
        FI(2) cin >> l[i] >> r[i];
        l[1] += n;
        r[1] += n;
        FI(2) l[i]--, r[i]--;
        pii a = get(1, 0, sn - 1, l[0], r[0]);
        pii b = get(1, 0, sn - 1, l[1], r[1]);
        if (a.first > b.first || a.first % 2 != b.first % 2 || a.second < b.second) {
            ans += '0';
            continue;
        }
        ans += ((a.first == b.first && a.second % 3 == b.second % 3) ||
                (a.first != b.first && a.first > 0) ||
                (a.second > b.second && a.first != b.first)) ? '1' : '0';
    }
    cout << ans << endl;
    // + A
    // - AAA



    // BBBBBBBBAAA
    // BBBBBBBBAAAAAAA
    return 0;
}

