int tmp[N], m;
int n;

#define ls (u << 1)
#define rs (u << 1 | 1)
#define sz(u) (tr[u].r - tr[u].l + 1)

struct build {
  int l, r;
  int tag, lb, rb;
  int cnt;
} tr[N << 2];

void pushup(int u) {
  tr[u].lb = tr[ls].lb;
  tr[u].rb = tr[rs].rb;
  tr[u].cnt = tr[ls].cnt + tr[rs].cnt - (tr[ls].rb && tr[rs].lb);
  return ;
}

void pushdown(int u) {
  if (!tr[u].tag) return ;
  tr[ls].tag = tr[rs].tag = 1;
  tr[ls].lb = 1, tr[ls].rb = 1, tr[ls].cnt = 1;
  tr[rs].lb = 1, tr[rs].rb = 1, tr[rs].cnt = 1;
  tr[u].tag = 0;
}

void build(int u, int l, int r) {
  tr[u].l = l, tr[u].r = r;
  tr[u].tag = 0;
  if (l == r) {
    return ;
  }

  int mid = (l + r) >> 1;
  build(ls, l, mid);
  build(rs, mid + 1, r);
}

void update(int u, int l, int r) {
  if (tr[u].l == l && tr[u].r == r) {
    tr[u].tag = 1;
    tr[u].lb = 1, tr[u].rb = 1, tr[u].cnt = 1;
    return ;
  }
  pushdown(u);

  int mid = (tr[u].l + tr[u].r) >> 1;
  if (r <= mid) update(ls, l, r);
  else if (l > mid) update(rs, l, r);
  else {
    update(ls, l, mid);
    update(rs, mid + 1, r);
  }
  pushup(u);
}

