		for (int j = 0; j < n; j++) if (isdigit(b[i][j]) && b[i][j] > '0') {
			int u = n * n + i * n + j + 1; R[u][N - 1] = b[i][j] - '0'; neigh[u].push_back(N - 1); neigh[N - 1].push_back(u);
		}
	int f;
	while ((f = getFlow()) != 0) res += f;
	printf("%d\n", res);
