    cola[enq++] = s;
    lev[s] = 1;
    while( deq < enq && !lev[t] ){
        int u = cola[deq++];
        for( int e = last[u]; e; e = nxt[e] ){
            int v = ady[e];
            if( !lev[v] && flow[e] < cap[e] ){
                lev[v] = lev[u] + 1;
                cola[enq++] = v;
            }
        }
    }
    return lev[t];
}
int dfs( int u, int F ){
    if( u == t ) return F;
    for( int e = now[u], f = 0; e; e = now[u] = nxt[e] ){
        int v = ady[e];
        if( lev[u] < lev[v] && flow[e] < cap[e] &&
            (f = dfs( v , min( F , cap[e] - flow[e] ) )) ){
            flow[e] += f;
            flow[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int max_flow(){
    int F = 0, f = 0;
    while( bfs() ){
        for( int i = 0; i <= n; i++ ) now[i] = last[i];
        while( (f = dfs( s , oo )) ) F += f;
    }
    return F;
}

