int augment( int u ){

	if( u == 1 ) return INF;
	vis[u] = true;

	REP( i, SIZE(gr[u]) ) if( !vis[gr[u][i]] && cap[u][gr[u][i]] ){
		int r = augment( gr[u][i] );
		if( r ){
			parent[ gr[u][i] ] = u;
			return MIN( r, cap[u][ gr[u][i] ] );
		}
	}

	return 0;

}

int maxflow(){
	int ans = 0;
	int flow = 0;

	parent[0] = -1;
	do{	
		ans += flow;

		REP( i, M ) vis[i] = false;
		flow = augment(0);

		if (!flow) return ans;

		int v = 1;
		while( v != 0 ){
			int u = parent[v];
			cap[u][v] -= flow;
			cap[v][u] += flow;
			v = u;
		}
	} while( flow );

	return ans;
}

