int dinic(int nodenum,int src,int tc)
{
    int u,v,s;
    int max_flow=0;
    int i;
    int temp;
    int now;
    int rear;
    int hh;
    while(bfs(nodenum,src,tc))
    {
        now=src;
        rear=0;
        for(i=0;i<=nodenum;i++)//记得全部要复制
            cur[i]=head[i];
        while(cur[src]!=-1)
        {
            hh=cur[now];
            u=edge[hh].u;
            v=edge[hh].v;
            s=edge[hh].s;
            if(now!=tc && hh!=-1 && s>0 && dis[now]!=-1 && dis[now]+1==dis[v])    //s > eps
            {
                queue[rear++]=hh;
                now=v;
            }
            else if(now == tc)
            {
                temp=inf;
                for(i=rear-1;i>=0;i--)
                    temp=Min(temp,edge[queue[i]].s);
                max_flow+=temp;
                for(i=rear-1;i>=0;i--)
                {
                    edge[queue[i]].s-=temp;
                    edge[queue[i]^1].s+=temp;
                    if(edge[queue[i]].s == 0)    // fabs(edge[queue[i]].s) < eps
                        rear=i;
                }
                now=edge[queue[rear]].u;
            }
            else
            {
                while(rear>0 && now!=src && cur[now]==-1)
                    now=edge[queue[--rear]].u;
                cur[now]=edge[cur[now]].next;
            }
        }
    }
    return max_flow;
}
