void bfs(int n) {
        queue<pair<int, int> > q;
        for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                        d[i][j] = INF;
                        if (sci[i][j] == 'Z') {
                                q.push(make_pair(i, j));
                                d[i][j] = 0;
                        }
                }
        }
        while (!q.empty()) {
                int x = q.front().first;
                int y = q.front().second;
                q.pop();
                for (int k = 0; k < 4; ++k) {
                        int xx = x + dx[k];
                        int yy = y + dy[k];
                        if (0 <= xx && xx < n && 0 <= yy && yy < n
                                        && isdigit(sci[xx][yy]) && d[xx][yy] == INF) {
                                d[xx][yy] = d[x][y] + 1;
                                q.push(make_pair(xx, yy));
                        }
                }
        }
}

void gao(int n, int m, int sx, int sy) {
        queue<pair<int, int> > q;
