{

    int u=Q.front();
    Q.pop();

    for(int i=0;i<G[u].size();++i)
    {
    int id=G[u][i];
    int v=e[id].v;

    if(dist[v]==-1 && e[id].flow<e[id].capacity)
        {
        dist[v]=dist[u]+1;
        Q.push(v);
        if(v==sink)
        return true;
        }
    }

}
return false;
}

ll sendFlow(int u,int flow)
{
if(flow==0)
return 0;

if(u==sink)
return flow;



