bool make_level_graph(int s, int t) {
    memset(d, -1, sizeof d);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while(not q.empty()) {
        int u = q.front();
        q.pop();
        for(int v : adj[u]) {
            if(c[u][v] - f[u][v] > 0 and d[v] == -1) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
    return d[t] != -1;
}
bool dfs(int u, int t) {
    if(u == t) return true;
    for(int& i = adj_ptr[u]; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(d[v] == d[u] + 1 and c[u][v] - f[u][v] > 0 and dfs(v, t)) {
            p[v] = u;
            return true;
        }
    }
    return false;
}
bool find_aug_path(int s, int t) {
    memset(p, -1, sizeof p);
    p[s] = 0;
    return dfs(s, t);
}
