{
	memset(now,0,sizeof(now));
	memset(head,-1,sizeof(head));
	cnt=0;
	for(int time=1;time<=t;time++)
	{
		for(int x=1;x<=n;x++)
		{
			for(int y=1;y<=n;y++)
			{
				if(maze[time-1][x][y])
					maze[time][x][y]=maze[time-1][x][y];
				else
				{
					for(int k=0;k<4;k++)
					{
						int xx=x+b[k][0];
						int yy=y+b[k][1];
						if(xx<=0||yy<=0||xx>n||yy>n)
							continue;
						if(maze[time-1][xx][yy]==2)
							maze[time][x][y]=2;
					}
				}
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=n;j++)
		{
			if(sci[i][j])
			{
				memset(vis,false,sizeof(vis));
				dfs(i,j,i,j,0);
			}
		}
	}
	for(int i=1;i<=t;i++)
		for(int x=1;x<=n;x++)
			for(int y=1;y<=n;y++)
				for(int xx=1;xx<=n;xx++)
					for(int yy=1;yy<=n;yy++)
				dp[i][x][y][xx][yy]|=dp[i-1][x][y][xx][yy];
}

