int dfs(int v, int sink, int flow = 2e9) {
	if (v == sink)
		return flow;
	if (mark[v]++)
		return 0;
	for (int e = head[v]; ~e; e = prev[e]) if (cap[e]) {
		int u = to[e];
		int x = dfs(u, sink, min(flow, cap[e]));
		if (x) {
			cap[e] -= x;
			cap[e ^ 1] += x;
			return x;
		}
	}
	return 0;
}

int max_flow(int source, int sink) {
	int res = 0;
	while (true) {
		memset(mark, 0, sizeof mark);
		int add = dfs(source, sink);
		res += add;
		if (!add)
			break;
	}
	return res;
}

