using namespace std;
typedef long long ll;
const int mod=998244353,N=200200,G=3,Gi=332748118;
ll power(ll base,ll b){
	ll ret=1;
	while(b){
		if(b&1)ret=ret*base%mod;
		base=base*base%mod;
		b>>=1;
	}
	return ret;
}
int limit,len,last=-1,pos[N];
ll G0[N],G1[N],G2[N],g[N],F0[N],F1[N],F2[N]; 
//F0是两端都没有距离为2的点 
//F1是一端有距离为2的点  (答案统计时有两种方案数相同的情况)
//F2是两端都有距离为2的点  
inline void getlen(int n){
	limit=1,len=0;
	while(limit<n)limit<<=1,++len;
	if(last==limit)return;
	last=limit;
	for(int i=1;i<limit;++i)
		pos[i]=(pos[i>>1]>>1)|((i&1)<<(len-1));
}
inline void ntt(ll *a,int n,int type){
	for(int i=0;i<limit;++i)
		if(i<pos[i])swap(a[i],a[pos[i]]);
	for(int mid=1;mid<limit;mid<<=1){
		ll wn=power((type==1?G:Gi),(mod-1)/(mid<<1));
		for(int j=0;j<limit;j+=(mid<<1)){
			ll w=1;
			for(int k=0;k<mid;++k,w=w*wn%mod){
				ll x=a[j+k],y=a[j+mid+k]*w%mod;
				a[j+k]=(x+y)%mod;
				a[j+mid+k]=(x-y+mod)%mod;
			}
		}
	}
	if(type==-1){
		ll inv=power(limit,mod-2);
		for(int i=0;i<n;++i)a[i]=a[i]*inv%mod;
		for(int i=n;i<limit;++i)a[i]=0;
	}
}
ll f[N],h[N],tmp[N];
void calc(ll *a,int n,ll *b,int m,ll *c,int nm=-1){
	if(nm==-1)nm=n+m-1;
	getlen(nm);
	for(int i=0;i<n;++i)f[i]=a[i];
	for(int i=n;i<limit;++i)f[i]=0;
	for(int i=0;i<m;++i)h[i]=b[i];
	for(int i=m;i<limit;++i)h[i]=0;
	ntt(f,nm,1),ntt(h,nm,1);
	for(int i=0;i<limit;++i)f[i]=f[i]*h[i]%mod;
	ntt(f,nm,-1);
	for(int i=0;i<nm;++i)c[i]=f[i];
}
void CDQ(int l,int r){
	if(l==r){
		F0[l]=(F0[l]+G0[l])%mod;
		F1[l]=(F1[l]+G1[l])%mod;
		F2[l]=(F2[l]+G2[l])%mod;
		return;
	}
	int mid=(l+r)>>1;
	CDQ(l,mid);
	calc(F0+l,mid-l+1,G0,r-l+1,tmp+l,r-l+1);
	for(int i=mid+1;i<=r;++i)F0[i]=(F0[i]+tmp[i])%mod;
	calc(F0+l,mid-l+1,G1,r-l+1,tmp+l,r-l+1);
	for(int i=mid+1;i<=r;++i)F1[i]=(F1[i]+tmp[i])%mod;
	calc(F1+l,mid-l+1,G1,r-l+1,tmp+l,r-l+1);
	for(int i=mid+1;i<=r;++i)F0[i]=(F0[i]+tmp[i])%mod;
	for(int i=mid+1;i<=r;++i)F2[i]=(F2[i]+tmp[i])%mod;
	calc(F1+l,mid-l+1,G2,r-l+1,tmp+l,r-l+1);
	for(int i=mid+1;i<=r;++i)F1[i]=(F1[i]+tmp[i])%mod;
	calc(F2+l,mid-l+1,G2,r-l+1,tmp+l,r-l+1);
	for(int i=mid+1;i<=r;++i)F2[i]=(F2[i]+tmp[i])%mod;
	//注意是左边对右边的贡献 
	CDQ(mid+1,r);
}
