	scanf("%d",&n);
	g[0]=g[2]=1;
	for(int i=4;i<=n;++i)g[i]=(g[i-2]+g[i-4])%mod;
	for(int i=1;i<=n;++i)G0[i]=1LL*(i-1)*(i-1)%mod*g[i-1]%mod;
	for(int i=2;i<=n;++i)G1[i]=1LL*(i-1)*(i-1)%mod*g[i-2]%mod;
	for(int i=3;i<=n;++i)G2[i]=1LL*(i-1)*(i-1)%mod*g[i-3]%mod;
	CDQ(1,n); 
	ll Ans=1LL*n*(G0[n]+G2[n])%mod;//可以旋转n次
	for(int i=2;i<=n-2;++i){
		Ans=(Ans+(G0[i]*F0[n-i]%mod+2LL*G1[i]*F1[n-i]%mod+G2[i]*F2[n-i]%mod)*(ll)i%mod)%mod;//把第一个相对的点对旋转到1-n+1处 
	} 
	printf("%lld\n",(Ans%mod+mod)%mod);
	return 0;
}

