int gao() {
	int mask = 0, po = 0;
	for (int i = 0; i < 5; ++i) {
		for (int j = c0[i]; j <= c1[i]; j += 2) {
			if (s[i][j] == 'O') {
				mask |= (1 << po);
			}
			++po;
		}
	}
	int &ret = dp[mask];
	if (ret == -1) {
		ret = 0;
		for (int i = 0; i < 5 && !ret; ++i) {
			for (int j = c0[i]; j <= c1[i] && !ret; j += 2) {
				if (s[i][j] != 'O')
					continue;
				for (int k = 0; k < 6 && !ret; ++k) {
					int ii = i, jj = j;
					while (ii >= 0 && ii < 5 && jj >= c0[ii] && jj <= c1[ii] && s[ii][jj] == 'O') {
						s[ii][jj] = 'X';
						ii += di[k];
						jj += dj[k];
						if (!gao()) {
							ret = 1;
							break;
						}
					}
					while (ii != i || jj != j) {
						ii -= di[k];
						jj -= dj[k];
						s[ii][jj] = 'O';
					}
				}
			}
		}
	}
	return ret > 0;
}


