vector<int> f;
vector<int> computePrefix(string pat)
{
    int m = pat.size();
    vector<int> lp(m);
    for(int i = 1, k = 0; i < m; i++)
    {
        while(k > 0 && pat[k] != pat[i])
            k = lp[k - 1];
        if(pat[k] == pat[i])
            lp[i] = ++k;
        else
            lp[i] = k;
    }
    return lp;
}
int solve(int i, int j, int k)
{
    if(k == a[2])
        return -1e9;
    if(i == a[0] || j == a[1])
        return 0;
    int &x = dp[i][j][k];
    if(x != -1)
        return x;
    int z1 = solve(i + 1, j, k), z2 = solve(i, j + 1, k), z3 = -1e9;
    if(s[0][i] == s[1][j])
    {
        int l = k;
        while(l > 0 && s[2][l] != s[0][i])
            l = f[l - 1];
        if(s[2][l] == s[0][i])
            ++l;
        z3 = 1 + solve(i + 1, j + 1 , l);
    }
