int phi[N];

void initPhi() {
  for (int i = 2;i < N;i++) {
    if (!phi[i]) {
      for (int k = i;k < N;k += i) {
        if (!phi[k]) phi[k] = k;
        phi[k] = phi[k] / i * (i - 1);
      }
    }
  }
}
vector<int> factor[N];
void initFactor() {
  for (int i = 1; i < N; i++) {
    for (int j = i; j < N; j += i) {
      factor[j].push_back(i);
    }
  }
}

int gcd(int a, int b) {
  return b ? gcd(b, a % b) : a;
}

void solve() {
  initPhi();
  initFactor();

  int n;
  cin >> n;
  int64_t ans = 0;
  for (int c = 1; c < n - 1; c++) {
    for (int d : factor[n - c]) {
      ans += 1LL * c * d / gcd(c, d) * phi[(n - c) / d] % P;
    }
  }
  cout << ans % P << endl;
}

int main(){
  solve();
}

