#define LL long long
using namespace std;
LL gao(LL l1,LL r1,LL l2,LL r2)
{
    if(l1==l2&&r1==r2)
        return 0;
    if(r1<=l2)
        return l2-r1+1;
    else
        return l1-r2+1;
}
long long L(LL x,LL m)
{
    if(x>0)
    {
        LL y=x%m;
        return (x-y)/m;
    }
    else
    {
        x=-x;
        LL y=x%m;
        return -(x+(m-y))/m;
    }
}
long long R(long long x,LL m)
{
    if(x>0)
    {
        LL y=x%m;
        return (x+m-y)/m;
    }
    else
    {
        x=-x;
        LL y=x%m;
        return -(x-y)/m;
    }
}
int main()
{
    long long a,b,x1,y1,x2,y2;
    cin>>a>>b>>x1>>y1>>x2>>y2;
    a*=2,b*=2;
    LL u1=R(x1+y1,a);
    LL d1=L(x1+y1,a);
    LL u2=R(x2+y2,a);
    LL d2=L(x2+y2,a);
    LL ans=gao(d1,u1,d2,u2);
    u1=R(y1-x1,b);
    d1=L(y1-x1,b);
    u2=R(y2-x2,b);
    d2=L(y2-x2,b);
    ans=max(ans,gao(d1,u1,d2,u2));
    cout<<ans;
}

