int solve(int m, int n){
	if(n == 1)return -1;
    else if(n == 2 && m > 3)return -1;
    else if(n == 3 && m > 5)return -1;
    else if(n == 2 && m == 2)return 5;
    else if(m == 3 && n == 2)return 11;
    else if(n >= 2*m)return 1;
    else if(n > m && n < 2*m)return 3;
    else if(n == 3){
    	if(m == 3)return 5;
    	else if(m == 4)return 9;
    	else if(m == 5)return 11;
	}else{
		int n7 = (n-1)/2;
		int nl = (n-2)/2;

		m -= n;
		m++;
		int curr = 5;
		while(1){
			if(curr == 7)m -= n7;
			else m -= nl;
			if(m <= 0)return curr;
			curr += 2;
		}
	}
}
