ull ret;

void dfs(int depth, ull cur, int cnt, int hi) {
  if(depth >= 10 || cnt > n) return;
  if(cnt == n) {
    ret = min(ret, cur);
    return;
  }
  for(int i = 1; i <= hi; i++) {
    if(cnt * (i + 1) > n) break;
    cur *= (ull)p[depth];
    dfs(depth+1, cur, cnt*(i+1), i);
  }
}

