bitset<maxn> isprime;
void init(){
    isprime.reset(); isprime.flip();
    primes.pb(2ll);
    for(ll e = 4; e < maxn; e += 2) isprime[e] = 0;
    for(ll e = 3; e < maxn; e += 2) if(isprime[e]){
        primes.pb(e);
        for(ll f = e*e; f < maxn; f += e) isprime[f] = 0;
    }
}
bool isp(ll n){
    if(n == 2) return true;
    if(n < 2 || !(n&1)) return false;
    for(ll e = 3; e*e <= n; e += 2) if(n%e == 0) return false;
    return true;
}
ll solve(ll index, ll number){
    if(index < 0 || number < primes[index]) return 0ll;
    number /= primes[index];
    ll ans = number;
    for(int e = 0; e < index; e++) ans -= solve(e, number);
    return ans;
}
