ll bin[N];
ll qpow(ll a, ll b)
{
    ll res=1;
    while(b){
        if(b&1)res=res*a%P;
        a=a*a%P;
        b>>=1;
    }
    return res;
}
void NTT(ll *a, ll k, ll op)
{
    for (ll i = 0; i < k; i++)
        bin[i] = (bin[i >> 1] >> 1) | ((i & 1) * (k >> 1));
    for (ll i = 0; i < k; i++)
        if (i < bin[i])
            swap(a[i], a[bin[i]]);
    for (ll i = 1; i < k; i <<= 1)
    {
        ll wn = qpow(yg, op == 1 ? (P - 1) / (2 * i) : (P - 1) - (P - 1) / (2 * i)), w, t;
        for (ll j = 0; j < k; j += i << 1)
        {
            w = 1;
            for (ll k = 0; k < i; k++)
            {
                t = a[i + j + k] * w % P;
                w = w * wn % P;
                a[i + j + k] = (a[j + k] - t + P) % P;
                a[j + k] = (a[j + k] + t) % P;
            }
        }
    }
    if (op == -1)
    {
        ll Inv = qpow(k, P - 2);
        for (ll i = 0; i < k; i++)
            a[i] = a[i] * Inv % P;
    }
}
void get_s2(){
    fac[0] = inv[0] = 1;
    for (int i = 1; i <= k; i++)
        fac[i] = fac[i - 1] * i % P, inv[i] = qpow(fac[i], P - 2);
    for (int i = 0; i <= k; i++)
        f[i] = (qpow(-1, i) + P) % P * inv[i] % P;
    for (int i = 0; i <= k; i++)
        g[i] = qpow(i, k) * inv[i] % P;
    ll len = 1;
    while (len < (k + 1) << 1)
        len <<= 1;
    NTT(f, len, 1);
    NTT(g, len, 1);
    for (int i = 0; i < len; i++)
        S2[i] = (f[i] * g[i]) % P; 
    NTT(S2, len, -1);
}
