  for (int i = 1; i <= n; ++i) fac[i] = mul(fac[i - 1], i);
  ifac[n] = inv(fac[n]);
  for (int i = n - 1; i >= 0; --i) ifac[i] = mul(ifac[i + 1], i + 1);
}

int dp(int s, int c) {
  if (!s) return 1;
  if (c == k) return 0;
  int &res = f[s][c];
  if (res != -1) return res;
  res = 0;
  int hb = 1;
  while (hb <= s) hb <<= 1;
  hb >>= 1;
  for (int t = s; t != -1; --t) {
    t &= s;
    if (!(t & hb)) return res;
    inc(res, mul(ifac[t], k - c, dp(s ^ t, c + 1)));
  }
  return res;
}

