bool check(int d) {
    vector <int> lastDiscount(n + 1, -1);

    for (int i = 0; i < m; i++)
        if (c[i].first <= d)
            lastDiscount[c[i].second] = max(lastDiscount[c[i].second], c[i].first);

    vector <vector <int>> off(d + 1);
    for (int i = 1; i <= n; i++)
        if (lastDiscount[i] != -1)
            off[lastDiscount[i]].push_back(i);

    vector <int> need = k;
    int cur_money = 0;
    for (int cur_day = 1; cur_day <= d; cur_day++) {
        cur_money++;

        if (cur_day > d)
            continue;

        for (auto it: off[cur_day])
            if (cur_money >= need[it]) {
                cur_money -= need[it];
                need[it] = 0;
            }
            else {
                need[it] -= cur_money;
                cur_money = 0;
                break;
            }
    }

    return accumulate(need.begin(), need.end(), 0) * 2 <= cur_money;
}

