const int inf = 1e9;
int n, m, k, c, d;
const int N = 4 * 55 * 105 * 105;

int mn[55 * 105][55 * 105];
int id[55 * 105][55 * 105];
int cnt[55 * 105];
struct MCMF {
    int n, m;
    void init(int _N) {
        n = _N;
        m = 0;
    }
    int S[N], E[N], F[N], C[N];
    void add_edge(int s, int e, int c) {
        S[m] = s;
        E[m] = e;
        F[m] = 0;
        C[m] = c;
        m++;
    }
    int solve(int st, int ed) {
        int ans = 0;
        for (int it = 1; it <= k; it++) {
            vector<vector<int>> edge(n);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    mn[i][j] = inf;
                }
            }
            for (int i = 0; i < m; i++) {
                if (F[i]) {
                    mn[E[i]][S[i]] = min(mn[E[i]][S[i]], -C[i]);
                    if (mn[E[i]][S[i]] == -C[i]) id[E[i]][S[i]] = ~i;
                    edge[E[i]].push_back(S[i]);
                }
                else {
                    mn[S[i]][E[i]] = min(mn[S[i]][E[i]], C[i]);
                    if (mn[S[i]][E[i]] == C[i]) id[S[i]][E[i]] = i;
                    edge[S[i]].push_back(E[i]);
                }
            }
            for (int i = 0; i < n; i++) {
                vector<int> nw;
                for (int j : edge[i]) {
                    if (cnt[j]++ == 0) nw.push_back(j);
                }
                edge[i] = nw;
                for (int j : edge[i]) {
                    cnt[j] = 0;
                }
            }
            vector<int> D(n, inf);
            vector<int> P(n, 0);
            D[st] = 0;
            int loop = 1;
            while (loop) {
                loop = 0;
                for (int i = 0; i < n; i++) {
                    for (int j : edge[i]) {
                        if (mn[i][j] < inf && D[i] + mn[i][j] < D[j]) {
                            D[j] = D[i] + mn[i][j];
                            P[j] = i;
                            loop = 1;
                        }
                    }
                }
            }
            fflush(stdout);
            ans += D[ed];
            for (int x = ed; x != st; x = P[x]) {
                int p = P[x];
                if (id[p][x] < 0) {
                    int idx = ~id[p][x];
                    F[idx] = 0;
                }
                else {
                    int idx = id[p][x];
                    F[idx] = 1;
                }
            }
        }
        return ans;
    }
} F;

