int64_t GCD(int64_t m ,int64_t n)
{
    int64_t temp1 =max(m,n);
    int64_t temp2 =min(m,n);
    m=temp1;
    n=temp2;
    if(m%n==0)
    {
        return n;
    }
    else
    {
        return GCD(m%n,n);
    }
}

int64_t divisors (int64_t n,vector<int64_t> &V)
{
    int64_t ans=1;
    while(n%2==0)
    {
        n=n/2;
          V.push_back(2);
        ans++;
    }
    for(int64_t i=3;i*i<=n;i+=2)
    { int64_t cnt =1;
        while(n%i==0)
        {
            n=n/i;
            V.push_back(i);

            cnt++;
        }
        ans *=cnt;
    }
    if(n>1)
    {
        V.push_back(n);
        ans *=2;
    }

    return ans;
}



