}

int64_t calpow(int64_t B, int64_t pow, int64_t mod)
{
  int64_t mul = 1;
  while (pow > 0)
  {
    if (pow & 1)
    {
      mul = ((B % mod) * (mul % mod)) % mod;
      pow--;
    }
    else
    {
      B = ((B % mod) * (B % mod)) % mod;
      pow /= 2;
    }
  }
  return mul;
}


