int64_t nCrModPFermat(int64_t n,int64_t r, int64_t p)
{

    if (n < r)
        return 0;

    if (r == 0)
        return 1;


    return (fac[n] * modInverse(fac[r], p) % p
            * modInverse(fac[n - r], p) % p)
           % p;
}

