void MAXHEAPIFY(int64_t *A,vector< string> V,int64_t i,int64_t n) //If at any node there is a parent node whose child's value is greater thanit ,then this will modiify the heap accordingly.
{
    int64_t MAX =i;
    int64_t l = (2*i); //Left child.
    int64_t r = (2*i)+1; //Right child.

    if((l<=n) && (compare(V[A[l]-1],V[A[MAX]-1])))
    {
        MAX =l;
    }
    if((r<=n) && (compare(V[A[r]-1],V[A[MAX]-1])))
    {
        MAX =r;
    }
    if(MAX!=i)
    {

        swap(A[i],A[MAX]); // Exchange child with parent.

        MAXHEAPIFY(A,V,MAX,n);// Check for cases of violation at new positon.
    }
    else
    {return;}
}
void BuidHeap(int64_t *A,vector< string> V,int64_t n) // Buids a heap structure out of any array.
{
       for(int64_t i = (n/2);i>=1;i--)
       {
           MAXHEAPIFY(A,V,i,n);

       }
}
void HeapSort(int64_t *A,vector< string> V,int64_t n)//sorts the array using heap structure.
{
    BuidHeap(A,V,n);


    for(int64_t i =n;i>=2;i--)
    {
        swap(A[1],A[i]);
        MAXHEAPIFY(A,V,1,i-1);
    }
}
