DB fix(DB a) {
	a = fabs(a);
	a = min(a, PI * 2 - a);
	return a;
}

bool check(const Point &a, const Point &b, const Circle &c) {
	Line l(a, b);
	Point nor = normal(l.vec()), ip = llint(l, Line(c.c, c.c + nor));
	return c.in(ip) && onseg(ip, a, b);
}

