DB cal(const Point &p) {
	if (check(p, B, C2)) {
		DB a[2], b[2];
		tangent(p, C2, a);
		tangent(B, C2, b);
		DB da = FINF;
		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < 2; j++) {
				da = min(fix(a[i] - b[j]), da);
			}
		}
		return (veclen(C2.point(a[0]) - p) + veclen(C2.point(b[0]) - B) + da * C2.r) / v;
	}
	return veclen(p - B) / v;
}

