// f は k 次多項式を 0 から k で評価した値が入る
//sum {0<=i<=inf} a^i f[i]
mint exp_poly_sum_limit(const mint a,const vc<mint>&f){
	assert(a!=1);
	int k=si(f)-1;
	if(a==0){
		return f[0];
	}else{
		vc<mint> g(k+1);
		{
			mint r=1;
			rep(i,k+1){
				g[i]=f[i]*r;
				r*=a;
			}
		}
		mint c;
		{
			mint w,r=1;
			rep(i,k+1){
				w+=choose(k+1,i)*r;
				r*=-a;
				c+=g[k-i]*w;
			}
			c/=mint(1-a).pow(k+1);
		}
		return c;
	}
}

