#include <bits/stdc++.h>
using namespace std;

int MOD;

int64_t power_mod(int64_t num, int power){
    int64_t prod = 1;
    num %= MOD;
    while(power > 0){
        if(power&1) prod = prod * num % MOD;
        num = num * num % MOD;
        power >>= 1;
    }
    return prod;
}

int64_t extgcd(int64_t a, int64_t b, int64_t& x, int64_t& y){
    int64_t d = a;
    if(b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a/b) * x;
    }else{
        x = 1; y = 0;
    }
    return d;
}

int64_t inv_mod(int64_t a, int mod){
    int64_t x, y;
    extgcd(a, mod, x, y);
    return (mod + x%mod) % mod;
}

int64_t mod(int64_t a, int64_t m) {
    return (a % m + m) % m;
}

pair<int64_t, int64_t> crt(int64_t b1, int64_t m1, int64_t b2, int64_t m2){
    int64_t p, q;
    int64_t d = extgcd(m1, m2, p, q);
    if((b2-b1) % d != 0) return {-1, -1};
    int64_t m = m1 * (m2/d);
    int64_t tmp = (b2 - b1) / d * p % (m2/d);
    int64_t r = mod(b1 + m1 * tmp, m);
    return make_pair(r, m);
}

vector<pair<int, int>> prime_division(int n){
    vector<pair<int, int>> ret;
    for(int i=2; i*i<=n; i++){
        int cnt = 0;
        while(n % i == 0){
            n /= i;
            cnt++;
        }
        if(cnt) ret.emplace_back(i, cnt);
    }
    if(n > 1) ret.emplace_back(n, 1);
    return ret;
}

vector<pair<int, int>> primes;
int64_t ppow[10];
vector<pair<int64_t, int>> fact[10];
void add(int64_t& a, int64_t b, int mod){
    a = (a+b) % mod;
}
void mul(int64_t& a, int64_t b, int mod){
    a = a*b % mod;
}

void prepare_mod(){
    primes = prime_division(MOD);
    int sz = primes.size();
    for(int t=0; t<sz; t++){
        int p = primes[t].first;
        ppow[t] = 1;
        for(int i=0; i<primes[t].second; i++) ppow[t] *= p;
        auto& f = fact[t];
        f.resize(100001);
        f[0] = {1, 0};
        for(int i=1; i<=100000; i++){
            f[i] = f[i-1];
            int n = i;
            while(n%p == 0){
                n /= p;
                f[i].second++;
            }
            mul(f[i].first, n, ppow[t]);
        }
    }
}

int64_t comb(int N, int K, int pi){
    auto &a = fact[pi][N], &b = fact[pi][K], &c = fact[pi][N-K];
    auto& p = primes[pi];
    int pp = ppow[pi];
    int pw = a.second - b.second - c.second;
    if(pw >= p.second) return 0;
    int64_t v = a.first;
    mul(v, inv_mod(b.first, pp), pp);
    mul(v, inv_mod(c.first, pp), pp);
    while(pw--) mul(v, p.first, pp);
    return v;
}

int64_t calc(int L, int N){
    pair<int64_t, int64_t> ans = {0, 1};
    for(int pi=0; pi<primes.size(); pi++){
        int64_t r = 0;
        for(int s=L; s<=N; s++){
            int X = (s-L)/2;
            int64_t res = comb(s, X, pi);
            mul(res, comb(N, s, pi), ppow[pi]);
            add(r, res, ppow[pi]);
        }
        ans = crt(ans.first, ans.second, r, ppow[pi]);
    }
    return ans.first;
}

int main(){
    int N, L, R;
    cin >> N >> MOD >> L >> R;

    prepare_mod();

    int ans = (MOD + calc(L, N) - calc(R+1, N)) % MOD;
    cout << ans << endl;
    return 0;
}

