#include<bits/stdc++.h>

using namespace std;

typedef long long LL;

const int maxn = 2e5 + 10;
const LL mod = 1e9 + 7;

int n, q;
LL A[maxn], W[maxn];
LL B[2][maxn<<1];

LL Sum(int f, int i){
    LL res = 0;
    while(i){
        res += B[f][i];
        if(f) res = (res % mod + mod) % mod;
        i -= i & -i;
    }
    return res;
}

void Add(int f, int i, LL x){
    while(i < maxn){
        B[f][i] += x;
        if(f) B[f][i] = (B[f][i] % mod + mod) % mod;
        i += i & -i;
    }
}

LL gets(int x, int y, int f){
    if(f == 0) return y >= x ? Sum(f, y) - Sum(f, x - 1) : 0;
    return (Sum(f, y) - Sum(f, x - 1) + mod) % mod;
}

int get_pos(int x, int y){
    int lb = x, rb = y;
    while(lb < rb){
        int mid = (lb + rb) >> 1;
        if(gets(x, mid, 0) >= gets(mid + 1, y, 0)) rb = mid;
        else lb = mid + 1;
    }
    return rb;
}

LL solve(LL x, LL y){
    if(x == y) return 0;
    int p = get_pos(x, y);

    LL res = 0;
    res = (res + gets(x, p, 0) % mod * (A[p] - p) % mod) % mod;
    res = (res - gets(x, p, 1) + mod) % mod;
    res = (res - gets(p, y, 0) % mod * (A[p] - p) % mod + mod) % mod;
    res = (res + gets(p, y, 1)+ mod) % mod;

    return (res % mod + mod) % mod;
}

int main(){
//    freopen("in.txt", "r", stdin);

    scanf("%d %d", &n, &q);
    for(int i = 1; i <= n; i++){
        scanf("%lld", A + i);
    }
    for(int i = 1; i <= n; i++){
        scanf("%lld", W + i);
        Add(0, i, W[i]);
        Add(1, i, W[i] * (A[i] - i) % mod);
    }

    while(q--){
        LL x, y;
        scanf("%lld %lld", &x, &y);

        if(x < 0){
            x = -x;
            Add(0, x, -W[x]);
            Add(1, x, -W[x] * (A[x] - x));
            W[x] = y;
            Add(0, x, W[x]);
            Add(1, x, W[x] * (A[x] - x));
        }else{
            printf("%lld\n", solve(x, y));
        }
    }

    return 0;
}

