int main(void)
{
    long long i,j,k,m,n,a,b,x,y;
    float min,mi;
    while(cin>>x>>y>>n)
    {
        if(y<=n)
        {
            a=x;
            b=y;
        }
        else
        {
            min=1;
            for(i=1;i<=n;i++)
            {
                k=i*x/y;
                mi=(double)x/y-(double)k/i;
                if(mi<min)
                {
                    min=mi;
                    a=k;
                    b=i;
                }
                mi=(double)(k+1)/i-(double)x/y;
                if(mi<min)
                {
                    min=mi;
                    a=k+1;
                    b=i;
                }
            }
        }
        if(a>b)
        {
            m=a;
            n=b;
        }
        else
        {
            m=b;
            n=a;
        }
        if(n==0) m=1;
        else
        {
            while(n)
            {
                j=m%n;
                m=n;
                n=j;
            }
        }
        if(j!=1)
        {
            a=a/m;
            b=b/m;
        }
        cout<<a<<"/"<<b<<endl;
    }
    return 0;
}

