            temp = tempa/tempb;

            if(temp < min){
                mina = floor(a);
                minb = b;
                min = temp;
            }
            else if (temp == min){
                if(floor(a) < mina){
                    mina = floor(a);
                    minb = b;                   
                }
            }

            diff(x,y,ceil(a),b,tempa,tempb);        
            temp = tempa/tempb;

            if(temp < min){
                mina = ceil(a);
                minb = b;
                min = temp;
            }
            else if (temp == min){
                if(ceil(a) < mina){
                    mina = ceil(a);
                    minb = b;                   
                }
            }
        }
    }

    int gc = gcd (mina, minb);
    if (gc != 1){       
        mina = mina/gc;
        minb = minb/gc;
    }

