            }
        }
    }

    // special case, numbers that are a prefix of N:
    int64_t cur = 0;
    string curst;

    for (int len = 1; len <= SZ(n_str); ++len) {
        curst += n_str[len - 1];
        cur = 10 * cur + (n_str[len - 1] - '0');

        int64_t val = 1; // 1-based
        string tmp = "";
        for (int pos = 0; pos < SZ(curst); ++pos) {
