    mulself(pom, dwu[m - j][k]);
    mulself(pom, ile[k]);
    int pom3 = dp3[i][j];
    mulself(pom3, ile[k]);
    add(pom3, mul(dp1[k], dp2[i][j]));
    mulself(pom3, dwu[m - j][k]);
    add(dp2[i + k + 1][j + k],  pom);
    add(dp3[i + k + 1][j + k],  pom3);
  }
  cout << dp3[n + 1][m] << "\n";
}

