LL find(LL n){
    int ex = num(n);
    LL cur = 0, ad = 1;
    for(int i = 0; i <= ex-1; i++){
            cur += ad;
            ad *= 10;
    }
    if(cur <= n) return cur;
    return ((cur-1)/10);
