const int N=255;
const int mod=1e9+7;
int n,m,a[N],len,coef[N],dp[N];long long k;
void Inc(int &x,int y){x+=y;x>=mod?x-=mod:x;}
struct poly{
	int s[N];
	poly(){memset(s,0,sizeof(s));}
	void print(){
		for(int i=0;i<len;++i)printf("%d ",s[i]);
		puts("");
	}
};
poly operator + (poly a,poly b){
	for(int i=0;i<len;++i)Inc(a.s[i],b.s[i]);
	return a;
}
poly operator * (poly a,poly b){
	static int tmp[N<<1];
	for(int i=0;i<len;++i)
		for(int j=0;j<len;++j)
			Inc(tmp[i+j],1ll*a.s[i]*b.s[j]%mod);
	for(int i=len+len;i>=len;--i)
		if(tmp[i]){
			for(int j=1;j<=len;++j)Inc(tmp[i-j],1ll*coef[j]*tmp[i]%mod);
			tmp[i]=0;
		}
	for(int i=0;i<len;++i)a.s[i]=tmp[i],tmp[i]=0;
	return a;
}
poly fastpow(poly x,long long y){
	poly res;res.s[0]=1;
	while(y){if(y&1)res=res*x;x=x*x;y>>=1;}
	return res;
}
int main(){
	scanf("%d%d%lld",&n,&m,&k);
	for(int i=1;i<=n;++i)scanf("%d",&a[i]);
	for(int i=1,x;i<=m;++i)scanf("%d",&x),++coef[x],len=max(len,x);
	poly S,T;len==1?T.s[0]=coef[1]:T.s[1]=1;
	for(int i=1;i<=n;++i)S=S+fastpow(T,a[i]);
	S=fastpow(S,k);
	for(int i=dp[0]=1;i<len;++i)
		for(int j=1;j<=i;++j)
			Inc(dp[i],1ll*coef[j]*dp[i-j]%mod);
	int ans=0;
	for(int i=0;i<len;++i)Inc(ans,1ll*dp[i]*S.s[i]%mod);
	printf("%d\n",ans);return 0;
}

