struct post {
	int pos[3];
	int st[3];
	int mv;
};
inline int code(const post& p) {
	int q = p.mv;
	rept(i,3) q = q * 44 + p.pos[i];
	rept(i,3) q = q * 5 + p.st[i];
	return q;
}
inline post decode(int q) {
	post p;
	FORD(i,2,0) {
		p.st[i] = q % 5;
		q /= 5;
	}
	FORD(i,2,0) {
		p.pos[i] = q % 44;
		q /= 44;
	}
	p.mv = q;
	return p;
}
