int ans = 0;
bool used[100000001];
int fm[3],ft[3];
queue<int> q;

inline void add(const post &p) {
	rept(i,3) {
		if (p.pos[i] < 0) return;
		if (p.pos[i] > ans) ans = p.pos[i];
	}
	int qq = code(p);
	if (used[qq]) return;
	used[qq] = 1;
	q.push(qq);
}
int main()
{
	//freopen("input.txt","r",stdin);
	//freopen("output.txt","w",stdout);

	post p;
	C(p.pos); C(p.st); p.mv = 0;
	rept(i,3) {
		scanf("%d%d%d",&p.pos[i], &fm[i], &ft[i]);
		p.pos[i]+=2;
	}
	add(p);
	while (!q.empty()) {
		post cur = decode(q.front());
		/*if (cur.pos[0] == 6 + 1 && cur.pos[1] == 4 + 1 && cur.pos[2] == 5 + 1 && cur.mv==5 && cur.st[2] = 1 + 1) {
			a = a;
		}*/
		q.pop();
		// move
		rept(i,3) {
			if (cur.mv & 1 << i) continue;
			if (cur.st[i] !=0 && cur.st[i] !=4) continue;
			bool ok = 1;
			rept(j,3) {
				if (cur.st[j] == i + 1) {
					ok = 0;
					break;
				}
			}
			if (!ok) continue;
			FOR(dx, -fm[i], fm[i]) {
				if (!dx) continue;
				post nx = cur;
				nx.pos[i] += dx;
				int o = 0;
				rept(z,3) {
					if (nx.pos[z] == nx.pos[i]) ++o;
				}
				if (o > 1) continue;
				nx.mv |= 1 << i;
				add(nx);
			}
		}

		// lift
		rept(i,3) {
			if (cur.st[i] != 0) continue;
			bool ok = 1;
			rept(j,3) {
				if (cur.st[j] == i + 1) {
					ok = 0;
					break;
				}
			}
			if (!ok) continue;
			rept(j,3) {
				if (i == j) continue;
				if (cur.pos[j] != cur.pos[i] + 1 && cur.pos[j] != cur.pos[i] - 1) continue;
				bool ok = 1;
				rept(z, 3) {
					if (cur.st[z] == j + 1) {
						ok = 0;
						break;
					}
				}
				if (!ok) continue;
				post nx = cur;
				nx.st[i] = j + 1;
				nx.pos[j] = nx.pos[i];
				if (nx.st[j] != 0 && nx.st[j] != 4) {
					rept(z,3) nx.pos[z] = cur.pos[i];
				}
				add(nx);
			}
		}

		// throw
		rept(i,3) {
			if (cur.st[i] == 0 || cur.st[i] == 4) continue;
			bool ok = 1;
			rept(j,3) {
				if (cur.st[j] == i + 1) {
					ok = 0;
					break;
				}
			}
			if (!ok) continue;

			FOR(dx, -ft[i], ft[i]) {
				if (!dx) continue;
				bool ok = 1;
				rept(z, 3) {
					if (cur.pos[z] == dx + cur.pos[i]) continue;
				}
				post nx = cur;
				int pt = cur.st[i] - 1;
				nx.pos[pt] = cur.pos[i] + dx;
				if (cur.st[pt] > 0 && cur.st[pt] < 4) nx.pos[cur.st[pt] - 1] = cur.pos[i] + dx;
				nx.st[i] = 4;
				add(nx);
			}
		}
	}


	printf("%d\n", ans - 2);
}

