bool ok(int l1,int l2)
{
    if(l1)
    {
        if(s[l1]==s[l2+1])
            return 0;
        for(int i=l1-1,j=l2;i>0;i--,j--)
        {
            if(s[i]!=s[j])
                return 0;
        }
    }
    return 1;
}
Mat pows(Mat x,int y)
{
    Mat ans;
    for(int i=0;i<l;i++)
        ans.v[i][i]=1;
    while(y)
    {
        if(y%2)
            ans=x*ans;
        x=x*x;
        y>>=1;
    }
    return ans;
}

