int tmp[2][2], res[2][2], bin[2][2];
void mul(int a[2][2], int b[2][2], int c[2][2]) {
	rep (i, 0, 1) rep (j, 0, 1) {
		tmp[i][j] = 0;
		rep (k, 0, 1) tmp[i][j] = (tmp[i][j] + 1ll * a[i][k] * b[k][j]) % mod;
	}
	rep (i, 0, 1) rep (j, 0, 1) c[i][j] = tmp[i][j];
}

void power(int a[2][2], ll p) {
	rep (i, 0, 1) rep (j, 0, 1)
		res[i][j] = (i == j), bin[i][j] = a[i][j];
	while (p) {
		if (p & 1) mul(res, bin, res);
		mul(bin, bin, bin); p >>= 1;
	}
	rep (i, 0, 1) rep (j, 0, 1)
		a[i][j] = res[i][j];
}

int MA[2][2], MB[2][2];
int getfib(ll k) {
	MB[0][0] = MB[1][0] = MB[0][1] = 1; MB[1][1] = 0;
	MA[0][0] = 1; MA[1][0] = 0;
	power(MB, k - 1);
	mul(MB, MA, MA);
	return MA[0][0];
}

int nxt[maxn];
int calc(char s[maxn], int ls, char t[maxn], int lt) {
	int k, res = 0;
	nxt[1] = k = 1; res = 0;
	//printf("%s\n", t + 1);
	rep (i, 2, ls) {
		while (k >= 2 && s[i] != s[k]) k = nxt[k-1];
		if (s[i] == s[k]) k++;
		nxt[i] = k;
		//printf("%d\n", nxt[i]);
	}
	k = 1;
	rep (i, 1, lt) {
		while (k >= 2 && t[i] != s[k]) k = nxt[k-1];
		if (t[i] == s[k]) k++;
		//printf("%d %d\n", i, k);
		if (k == ls + 1) res++, k = nxt[k-1];
	}
	return res;
}

int flag[maxn];
char revB[maxn], revt[maxn];
int solve(char A[maxn], int lA, char B[maxn], int lB, char t[maxn], int lt) {
	rep (i, 1, lt - 1) flag[i] = 0;
	rep (i, 1, lB) revB[i] = B[lB+1-i];
	rep (i, 1, lt) revt[i] = t[lt+1-i];
	int k; nxt[1] = k = 1;
	rep (i, 2, lt) {
		while (k >= 2 && t[i] != t[k]) k = nxt[k-1];
		if (t[i] == t[k]) k++;
		nxt[i] = k;
	}
	k = 1;
	rep (i, 1, lA) {
		while (k >= 2 && A[i] != t[k]) k = nxt[k-1];
		if (A[i] == t[k]) k++;
		if (k == lt + 1) k = nxt[k-1];
	}
	while (k >= 2) {
		flag[lt-(k-1)]++;
		k = nxt[k-1];
	}
	nxt[1] = k = 1;
	rep (i, 2, lt) {
		while (k >= 2 && revt[i] != revt[k]) k = nxt[k-1];
		if (revt[i] == revt[k]) k++;
		nxt[i] = k;
	}
	k = 1;
	rep (i, 1, lB) {
		while (k >= 2 && revB[i] != revt[k]) k = nxt[k-1];
		if (revB[i] == revt[k]) k++;
		if (k == lt + 1) k = nxt[k-1];
	}
	while (k >= 2) {
		flag[k-1]++;
		k = nxt[k-1];
	}	
	int res = 0;
	rep (i, 1, lt - 1)
		if (flag[i] == 2) res++;
	return res;
}
