} *M[71][31];
Matrix* Matrix::operator *(Matrix b) {
    int i, j, k;
    Matrix* ret = new Matrix(N);
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            LL cans = 0;
            for (k = 0; k < N; k++) {
                cans += m[i][k] * ((LL)b.m[k][j]);
                cans %= MOD;
            }
            ret->m[i][j] = cans;
        }
    }
