inline void mkay(int &a)
{
	if(a >= mod)
		a -= mod;
	else if(a < 0)
		a += mod;
}

struct matrix
{
	int val[maxn][maxn];
	int n;
	matrix(int nn=0, int x = 0)
	{
		n = nn;
		for (int i=0; i<n; i++)
			for (int j=0; j<n; j++)
				if (i != j)
					val[i][j] = 0;
				else
					val[i][j] = x;
	}
	int* operator[] (int x)
	{
		return val[x];
	}
	matrix operator * (matrix b)
	{
		matrix ans(n, 0);
		for(int i=0; i<n; i++)
			for(int j=0; j<n; j++)
				for(int k=0; k<n; k++)
					mkay(ans[i][k] += 1LL * val[i][j] * b[j][k] % mod);
		return ans;
	}
	matrix operator + (matrix b)
	{
		matrix ans(n , 0);
		for(int i = 0; i < n; i++)
			for(int j = 0; j < n; j++)
				ans[i][j] = (val[i][j] + b[i][j]);
		return ans;
	}
	bool operator == (matrix b)
	{
		if(n != b.n)
			return 0;

		for(int i = 0; i < n; i++)
			for(int j = 0; j < n; j++)
				if(val[i][j] != b[i][j])
					return 0;
		return 1;
	}
};

matrix operator ^ (matrix a, ll b)
{
	matrix ans(a.n, 1);
	while(b)
	{
		if (b & 1)
			ans = ans * a;
		a = a * a;
		b >>= 1;
	}
	return ans;
}

int k;

matrix a[maxb] , shift[maxb];

ll val[maxb];

matrix get(ll n , int ind)
{
	if(!n)
		return matrix(k + 1 , 1);

	for(int i = ind; i >= 0; i--)
		if(n >= val[i])
		{
			matrix tmp = get(n % val[i] , i - 1);
			int x = n / val[i];

			matrix ans = a[i];
			for(int j = 1; j < x; j++)
			{
				ans = ans * shift[k - 1];
				ans = ans * a[i];
			}
			ans = ans * shift[k - 1];
			ans = ans * tmp;
			ans = ans * shift[x - 1];
			return ans;
		}

	cout << 1/0 << endl;
	return matrix(k + 1 , -800);
}

int main()
{
