	ll n;
	cin >> n >> k;

	val[0] = 1;

	int last = maxb;
	for(int i = 1; i < maxb; i++)
	{
		if(val[i - 1] >= inf / k)
		{
		    val[i] = inf;
		    last = i;
		    break;
		}
		else
			val[i] = val[i - 1] * k;
	}

	shift[0] = matrix(k + 1 , 1);
	shift[1] = matrix(k + 1);

	for(int i = 0; i < k; i++)
		shift[1][i][(i - 1 + k) % k] = 1;
	shift[1][k][k] = 1;

	for(int i = 2; i < k; i++)
		shift[i] = shift[i - 1] * shift[1];

	for(int i = 0; i < maxb; i++)
		a[i] = matrix(k + 1 , 1);

	for(int i = 0; i <= k; i++)
		a[0][i][0] = 1;

	for(int i = 1; i < last; i++)
	{
		matrix tmp = a[i - 1];

		a[i] = a[i - 1];

		for(int j = 1; j < k; j++)
		{
			a[i] = a[i] * shift[k - 1];
			a[i] = a[i] * tmp;
		}

		a[i] = a[i] * shift[k - 1];
	}

	matrix ans(k + 1);
	ans[0][k] = 1;

	ans = ans * get(n , last - 1);

	int res = 0;
	for(int i = 0; i <= k; i++)
		mkay(res += ans[0][i]);

	cout << res << endl;
}

