mat mat_mul(mat a, mat b)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			res[i][j] = 0;
			FOR(k, 0, K + 1)
			{
				res[i][j] += a[i][k] * b[k][j];
				res[i][j] %= INF;
			}
		}
	}
	return res;
}
mat shift(mat a, int x)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			if (a[i][j] == 0) continue;
			if (i == j) res[i][j] = a[i][j];
			else res[i][(j + x) % K] = a[i][j];
		}
	}
	return res;
}

int32_t main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> N >> K;
	while(N)
	{
		num.PB(N % K);
		N /= K;
	}
	// for (int x : num)
	// {
	// 	cerr << x << ' ';
	// }
	// cerr << endl;
	FOR(i, 0, K)
	{
		base[0][i].resize(K + 1);
		FOR(j, 0, K + 1) base[0][i][j].resize(K + 1);
		FOR(j, 0, K + 1)
		{
			base[0][i][j][j] = 1;
		}
		FOR(j, 0, K + 1)
		{
			base[0][i][j][i] = 1;
		}
	}
	FOR(i, 1, SZ(num))
	{
		pref[i - 1][0] = base[i - 1][0];
		FOR(j, 1, K)
		{
			pref[i - 1][j] = mat_mul(pref[i - 1][j - 1], base[i - 1][j]);
		}
		suf[i - 1][K - 1] = base[i - 1][K - 1];
		FORD(j, K - 1, 0)
		{
			suf[i - 1][j] = mat_mul(base[i - 1][j], suf[i - 1][j + 1]);
		}
		base[i][0] = pref[i - 1][K - 1];
		FOR(j, 1, K)
		{
			base[i][j] = mat_mul(suf[i - 1][j], pref[i - 1][j - 1]);
		}
	}
	trans.resize(K + 1);
	FOR(i, 0, K + 1) trans[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			trans[i][j] = 0;
		}
		trans[i][i] = 1;
	}
	int sum = 0;
	FORD(i, SZ(num), 0)
	{
		int x = num[i];
		//multiply by
		FOR(j, 0, x)
		{
			trans = mat_mul(trans, base[i][sum]);
			sum++; if (sum >= K) sum -= K;
		}
	}
	ans = 1;
	FOR(i, 0, K)
	{
		ans += trans[K][i];
		ans %= INF;
	}
	cout << ans << '\n';
	return 0;
	//base[i] tells you the transition matrix for 0....k^i - 1
	//trans has the transition matrix for 1!
}

