vec solve (long long n, vec v, int at) {
  if (n == 0) return v;
  int w = val (n / k);
  v = solve (n / k, v, at + 1);
  for (int i = 0; i < n % k; i++) {
    v = mult (E[at][(w + i) % k], v);
  }
  return v;
}

