    int shift = 0;
    for (int i = 0; i < sz(v); ++i) {
        shift += v[i];
    }
    for (int i = 0; i < k; ++i) {
        M[i] = matr();
        pref[i] = matr();
        suff[i] = matr();
    }
    for (int i = 0; i < sz(v); ++i) {
        shift -= v[i];
        for (int j = v[i] - 1; j >= 0; --j) {
            if (i == 0) {
                res = get((shift + j) % k) * res;
                continue;
            }
            res = M[(shift + j) % k] * res;
        }
        if (i == 0) {
            for (int i = 0; i < k; ++i) {
                M[i] = matr();
                for (int j = k - 1; j >= 0; --j) {
