    for (int i = 1; i < n; ++i) {
      mat.mul(A[m][i]);
    }
    return mat;
  }
  Matrix mat = solve(n / k, m + 1);
  int x = digsum(n / k);
  for (int i = 0; i < n % k; ++i) {
    mat.mul(A[m][(x + i) % k]);
  }
  return mat;
}

