  REP (i, k) {
    A[0][i].init(k + 1, 0);
    REP (j, k + 1) {
      A[0][i].a[j][j] = 1;
      A[0][i].a[j][i] = 1;
    }
  }
  for (int m = 1; pow(k, m) - 1000 <= n; ++m) {
    pre_calc(m - 1);
