    void set() {
      init() ;
      for (int i = 1; i <= n; i++) {
        a[i][i] = 1;
      }
    }
    Matrix operator * (const Matrix &rhs) const {
      Matrix ans;
      ans.n = n;
      static long long tmp[MAXN][MAXN];
      static const long long MODLL = (LL) MOD * MOD;
      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
          tmp[i][j] = 0;
        }
      }
      for (int i = 1; i <= n; i++) {
        for (int k = 1; k <= n; k++) {
          for (int j = 1; j <= n; j++) {
            tmp[i][j] += (LL) a[i][k] * rhs.a[k][j];
            if (tmp[i][j] >= MODLL) tmp[i][j] -= MODLL;
          }
        }
      }

      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
          ans.a[i][j] = tmp[i][j] % MOD;
        }
      }

      return ans;
    }
  };
