					if (qs.size() > 3 && qt.size() == 2) {
						auto p1 = qs.front(); qs.pop_front();
						auto p2 = qs.front(); qs.pop_front();
						auto p3 = qs.front(); qs.pop_front();

						auto p4 = qt.front(); qt.pop_front();

						res.emplace_back(p1.second + p2.second + p3.second, p4.second);
						qs.front().second += p4.second;

						qt.front().second += p3.second;
						qt.push_front(p2);
						qt.push_front(p1);
						continue;
					} else if (qs.size() == 2 && qt.size() > 3) {
						auto p1 = qs.front(); qs.pop_front();

						auto p2 = qt.front(); qt.pop_front();
						auto p3 = qt.front(); qt.pop_front();
						auto p4 = qt.front(); qt.pop_front();

						res.emplace_back(p1.second, p2.second + p3.second + p4.second);

						qs.front().second += p4.second;
						qs.push_front(p3);
						qs.push_front(p2);


						qt.front().second += p1.second;

						continue;
					} 

					int cnt = qs.front().second;
					int cnt1 = qt.front().second;

					res.emplace_back(cnt, cnt1);
					qs.pop_front();
					qt.pop_front();

					qs.front().second += cnt1;
					qt.front().second += cnt;
				}
		}
		return res;
	}
};


