        if(Ks[0].size()==1&&Ks[1].size()==1)    break;
        if(Ks[0].size()==1){
            if(Ks[1].size()<=3){
                if(Ks[1].front()==Ks[0].front())
                    change(0,1);
                else
                    change(1,1);
            }
            else{
                if(Ks[1].front()==Ks[0].front())
                    change(0,3);
                else
                    change(1,3);
            }
        }
