int bad(string &s, char c){
	int an = s.back() != c;
	for(int i=1; i<s.size(); i++)
        if (s[i] != s[i - 1])++an;
	return an;
}

int ind(int d, string &s){
	if (d == 0)return 0;
	int c = 0;
	for(int i=0; i<s.size();i++){
		if (i + 1 == (int)s.size())return s.size();
		if (s[i] != s[i + 1])++c;
		if (c == d)return i + 1;
	}
	return 0;
}

void trm(string &a, string &b){
	while (!a.empty() && a.back() == 'a')a.pop_back();
	while (!b.empty() && b.back() == 'b')b.pop_back();
}

void kil(string &a, string &b, vector<pair<int, int> > &an){
	trm(a, b);
	while (!a.empty() || !b.empty()){
		an.push_back(make_pair(a.size(), b.size()));
		swap(a, b);
		trm(a, b);
	}
}

vector<pair<int, int> > go(string a, string b){
	vector<pair<int, int> > an;
	int abad = bad(a, 'a'), bbad = bad(b, 'b');
	int df = abs(abad - bbad);
	int need = df >> 1;
	if (need == 0)kil(a, b, an);
	else {
		string *bg = &a, *sm = &b;
		if (abad < bbad)swap(bg, sm);
		int bgn = ind(need, *bg);
		if (df & 1 && (*bg)[bgn - 1] != (*sm)[0])++need;
		string na, nb;
		int lsm = 0, lbg = need;
		if (bbad > 0)++lsm, ++lbg;
		if (sm == &a){
			int inda = ind(lsm, a), indb = ind(lbg, b);
			na = b.substr(0, indb) + a.substr(inda);
			nb = a.substr(0, inda) + b.substr(indb);
			an.push_back(make_pair(inda, indb));
		}else {
			int inda = ind(lbg, a), indb = ind(lsm, b);
			na = b.substr(0, indb) + a.substr(inda);
			nb = a.substr(0, inda) + b.substr(indb);
			an.push_back(make_pair(inda, indb));
		}
		kil(na, nb, an);
	}
	return an;
}

