        //printf("%d %d -> %c %c\n", la, lb, kuraca, kuracb);
        //printf("%d\n", la + lb);
        if (kuraca != kuracb) {
            if (lb <= 2) {
                if (la <= 3) query(1, 1);
                else query(3, 1);
            } else query(1, 1);
        } else {
            if (lb == 1) {
                if (la <= 3) query(1, 0);
                else query(3, 0);
