struct Seg
{
    int l, r, id;

    Seg() : l(), r(), id() {}

    Seg(int _l, int _r, int _id) : l(_l), r(_r), id(_id) {}
};

struct Dp
{
    long long dp[N];

    Dp()
    {
        memset(dp, 0, sizeof dp);
    }

    void operator += (int id)
    {
        for (int i = N - sz[id] - 1; i >= 0; i--)
            dp[i + sz[id]] = max(dp[i + sz[id]], dp[i] + sum[id]);
    }
};

int k;

long long ans = 0;

void solve(int l, int r, vector <Seg> &segs, Dp &dp)
{
    if (l == r)
    {
        long long psum = 0;
        for (int i = 0; i <= min(k, sz[l]); i++)
        {
            if (i != 0)
                psum += a[l][i - 1];
            ans = max(ans, psum + dp.dp[k - i]);
        }
        return;
    }
    int m = (l + r) / 2;
    vector <Seg> lsegs, rsegs;
    Dp ldp = dp, rdp = dp;

    for (Seg seg : segs)
    {
        if (seg.l <= l && seg.r >= m)
           ldp += seg.id;
        else if (seg.l <= m)
            lsegs.push_back(seg);

        if (seg.l <= m + 1 && seg.r >= r)
            rdp += seg.id;
        else if (seg.r >= m + 1)
            rsegs.push_back(seg);
    }

    solve(l, m, lsegs, ldp);
    solve(m + 1, r, rsegs, rdp);

}

