    {
        forn(i, k + 1) dp[z + 1][i] = dp[z][i];
        fore(i, L, M - 1) {
            int sz = a[i].size();
            ford(j, k - sz + 1) uax(dp[z + 1][j + sz], dp[z + 1][j] + s[i]);
        }
        dnc(M, R, z + 1);
