	for (int i =0; i < n; i++)
	{
		add(1, 0, treesize - 1, 0, i - 1, {len[i], sum[i]});
		add(1, 0, treesize - 1, i + 1, n - 1, {len[i], sum[i]});
	}
	ks.resize(k + 1);
	go(1, 0, treesize - 1, 0, n - 1);
	cout << answer << endl;
    return 0;
}

