inline ll intersect(ll a, ll b) {
	if (a > b)return 0;
	return (b - a + 1)*(b - a+2) / 2;

}

ll update(int a, int b) {
	if (a > b)return 0;
	int frm = a;
	ll ret = intersect(a, b);
	map<int, int>::iterator it = used.upper_bound(a);
	if (it != used.begin()) {
		it--;
		if (it->second >= b)return 0;
		if (it->second >= a) {
			ret -= intersect(a, it->second);
			frm = it->second;
		}
		it++;
	}
	while (it != used.end() && it->second <= b) {
		destroy.push(it->first);
//		frm = max(it->first, frm);
		ret -= intersect(it->first, it->second) - intersect(it->first, frm);
		frm = it->second;

		it++;
	}
	if (it != used.end()) {
		ret -= intersect(it->first, b) - intersect(it->first, frm);


	}
	while (!destroy.empty()) {
		used.erase(destroy.top());
		destroy.pop();

	}
	used[a] = b;
	return ret;

}
