        cov[rt<<1]=cov[rt<<1|1]=mi[rt<<1]=mi[rt<<1|1]=mx[rt<<1]=mx[rt<<1|1]=cov[rt];
        sum[rt<<1]=1ll*(len+1)/2ll*cov[rt];
        sum[rt<<1|1]=1ll*len/2ll*cov[rt];
        cov[rt]=0;
    }
}

void upd(int L,int R,int x,int l,int r,int rt){
    if(L>r||R<l||mi[rt]>=x) return;
    int m=(l+r)>>1;
    if(L<=l&&r<=R&&mx[rt]<=x){
        mi[rt]=mx[rt]=cov[rt]=x;
        sum[rt]=1ll*x*(r-l+1);
        return;
    }
    down(rt,r-l+1);
    if(L<=m) upd(L,R,x,lson);
    if(R>m) upd(L,R,x,rson);
    up(rt);
}

