struct segment_tree
{
    // st.set_vars ( n , 0 , arr ) ;
    // st.construct ( ) ;
    // st.get_sum ( 1 , 3 )
    // st.update_range ( 1 , 5 , 10 ) ; // add 10 to all nodes so difference = 10

    #define seg_size 1 << 19
    int n , init ;
    int * arr ;
    lli tree [ seg_size ] ;
    lli lazy [ seg_size ] ;
    int small [ seg_size ] ;
    int big [ seg_size ] ;

    void set_vars ( int _n , int _init , int * _arr = NULL )
    {
        n = _n ;
        init = _init ;
        arr = _arr ;
        //fill_n ( & small [ 0 ] , seg_size , 0 ) ;
        //fill_n ( & big [ 0 ] , seg_size , 0 ) ;
        if ( init != 0 )
        {
            fill_n ( & tree [ 0 ] , seg_size , init ) ;
            fill_n ( & lazy [ 0 ] , seg_size , init ) ;
        }
    }

    void updaterange_util ( int si , int ss , int se , int us , int ue , lli diff )
    {
        if ( lazy [ si ] != init )
        {
            small [ si ] = big [ si ] = lazy [ si ] ;
            tree [ si ] = ( se - ss + 1 ) * lazy [ si ] ;
            if ( ss != se )
            {
                lazy [ si * 2 + 1 ] = lazy [ si ] ;
                lazy [ si * 2 + 2 ] = lazy [ si ] ;
            }
            lazy [ si ] = init ;
        }
        if ( ss > se || ss > ue || se < us || small [ si ] >= diff )
        {
            return ;
        }
        if ( ss >= us && se <= ue && big [ si ] <= diff )
        {
            tree [ si ] = ( se - ss + 1 ) * diff ;
            small [ si ] = big [ si ] = diff ;
            if ( ss != se )
            {
                lazy [ si * 2 + 1 ] = diff ;
                lazy [ si * 2 + 2 ] = diff ;
            }
            return ;
        }
        int mid = ( ss + se ) / 2 ;
        updaterange_util ( si * 2 + 1 , ss , mid , us , ue , diff ) ;
        updaterange_util ( si * 2 + 2 , mid + 1 , se , us , ue , diff ) ;
        small [ si ] = min ( small [ si * 2 + 1 ] , small [ si * 2 + 2 ] ) ;
        big [ si ] = max ( big [ si * 2 + 1 ] , big [ si * 2 + 2 ] ) ;
        tree [ si ] = tree [ si * 2 + 1 ] + tree [ si * 2 + 2 ] ;
    }

    void update_range ( int us , int ue , lli diff )
    {
       updaterange_util ( 0 , 0 , n - 1 , us , ue , diff ) ;
    }
} st ;

