struct nodetree
{
    int l,r;
    long long x,y;
    long long lazy;
    long long sum;
}a[maxn<<2];

void push_up(int i)
{
    a[i].x=min(a[2*i].x,a[2*i+1].x);
    a[i].y=max(a[2*i].y,a[2*i+1].y);
    a[i].sum=a[2*i].sum+a[2*i+1].sum;
}

void push_down(int i)
{
    if(a[i].l!=a[i].r&&a[i].lazy!=-1)
    {
        a[2*i].x=a[2*i].y=a[i].lazy;
        a[2*i].sum=a[i].lazy*(a[2*i].r-a[2*i].l+1);
        a[2*i].lazy=a[i].lazy;

        a[2*i+1].x=a[2*i+1].y=a[i].lazy;
        a[2*i+1].sum=a[i].lazy*(a[2*i+1].r-a[2*i+1].l+1);
        a[2*i+1].lazy=a[i].lazy;

        a[i].lazy=-1;
    }
}

void init(int i,int l,int r)
{
    a[i].l=l;
    a[i].r=r;
    a[i].lazy=-1;
    if(l==r)
    {
        a[i].x=l;
        a[i].y=l;
        a[i].sum=l;
        return;
    }
    int mid=(l+r)/2;
    init(2*i,l,mid);
    init(2*i+1,mid+1,r);
    push_up(i);
}

long long find(int i,int num)
{
    push_down(i);
    if(a[i].y<=num)
        return a[i].r;
    if(a[i].x>=num)
        return -1;

    int tmp=find(2*i+1,num);
    if(tmp!=-1)
        return tmp;
    else
        return find(2*i,num);
}

void insert(int i,int x,int y,long long num)
{
    push_down(i);
    int l=a[i].l,r=a[i].r;
    if(l==x&&r==y)
    {
        a[i].x=num;
        a[i].y=num;
        a[i].sum=(r-l+1)*num;
        a[i].lazy=num;
        return;
    }
    int mid=(l+r)/2;
    if(y<=mid)
        insert(2*i,x,y,num);
    else if(x>=mid+1)
        insert(2*i+1,x,y,num);
    else
    {
        insert(2*i,x,mid,num);
        insert(2*i+1,mid+1,y,num);
    }
    push_up(i);
}

void update(int x,int y,int num)
{
    if(x>y)
        return;
    int tmp=find(1,num);
    tmp=min(tmp,y);
    if(tmp>=x)
        insert(1,x,tmp,num);
}

