int debug = 0;

//-------------------------------------------------------------------------
const int maxn = 2e5 + 10;
int a[maxn], n;
ll sum;
ll ans[maxn];
set<pair<pii, int> > S;
vector<int> H[maxn], v[maxn];
set<pair<pii, int> > :: iterator it, it2;
//-------------------------------------------------------------------------

void divide(int x){
    it = S.lower_bound(mp(mp(x + 1, 0), -1));
    if(it == S.begin()) return;
    --it;
    pair<pii, int> t = *it;
    if(t.st.nd < x) return;
    S.erase(it);
    S.insert(mp(mp(t.st.st, x), t.nd));
    if(t.st.nd >= x + 1) S.insert(mp(mp(x + 1, t.st.nd), t.nd));
}

void remove(int x){
    divide(x - 1);
    while(S.rbegin()->st.st >= x){
        pair<pii, int> t = *S.rbegin();
        sum -= (ll)t.nd * (t.st.nd - t.st.st + 1);
        S.erase(t);
    }
}

void maximize(int l, int r, int maxi){
    it = S.lower_bound(mp(mp(l, 0), 0));
    pair<pii, int> t;
    t.st.st = l, t.nd = maxi;
    while(it != S.end()){
        if(it->nd >= maxi) break;
        if(it->st.st > r) break;
        t.st.nd = it->st.nd;
        sum -= (ll)it->nd * (it->st.nd - it->st.st + 1);
        it2 = it; it2++; S.erase(it); it = it2;
    }
    if(t.st.st <= t.st.nd){
        sum += (ll)t.nd * (t.st.nd - t.st.st + 1);
        S.insert(t);
    }
}

int main(){
    if(debug) freopen("in.txt", "r", stdin);
