    while(~scanf("%d", &n)){
        sum = 0;
        S.clear();
        FOR(i, 0, maxn - 1) v[i].clear(), H[i].clear();
        FOR(i, 1, n){
            scanf("%d", &a[i]);
            sum += i;
            H[a[i]].pb(i);
            S.insert(mp(mp(i, i), i));
        }
        FOR(i, 1, maxn - 1){
            for(int j = i; j < maxn; j += i)
                foreach(it, H[j]) v[i].pb(*it);
        }
        ans[maxn - 1] = (ll)n * (n + 1) >> 1;
        ROF(i, maxn - 2, 1){
            int l = v[i].size() - 1;
            if(l <= 0) { ans[i] = ans[i + 1]; continue; }
            sort(v[i].begin(), v[i].end());
            remove(v[i][1] + 1);
            divide(v[i][0]);
            maximize(v[i][0] + 1, n, v[i][l]);
            maximize(1, v[i][0], v[i][l - 1]);
          //  divide(v[i][0]);
           // maximize(v[i][0] + 1, v[i][l]);
            ans[i] = (ll)S.rbegin()->st.nd * (n + 1) - sum;
        }
        ll tot = 0;
        ans[0] = 0;
        FOR(i, 1, maxn - 2) tot += (ll)i * (ans[i + 1] - ans[i]);
        printf("%lld\n", tot);
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////////////////////
    return 0;
}

/*
    assume that a[x] and a[y]'s gcd is largest
    if the interval [i,j] deleted not included subscript x or y, then f(i,j) still equal to gcd(a[x], a[y])
    therefore we enumerate the maximum of gcd(from max(a[1..n]) down to 1)
    for each gcdi we enumerate there may exist some element in array a[] which can be divided by gcdi
    we record their subscript then sort these subscripts
    assume there are k elements we record (k >= 2)
    it's clear that only three situations should be thought about
    1. we reserve the first and second sorted elements we record
       that is we can remove any interval[i, j] in interval[a[second]+1, n], and f(i, j) still equals to gcdi
    2. we reserve last two sorted elements we record
       that is we can remove any interval[i, j] in interval[1, a[k-1]-1], and f(i, j) still equals to gcdi
    3. we reserve the first and last sorted elements we record
       that is we can remove any interval[i, j] in interval[a[first]+1, a[last]-1], and f(i,j) still equals to gcdi
    then we donate board[i] as we can remove any interval[i, j] in interval[i, board[i]] it's clear that board[i] should be maximum
    if board[i] equals to n+1 we say all of intervals started with subscript i can be removes and then we will not care it any more
    we set cnt[1] donating the sum of remaining intervals should be removed and the initial of cnt[1] = n*(n+1)/2 and tot_cnt = n*(n+1)
    if there are another x intervals be removed, then we add x to cnt[1] (cnt[1] = cnt[1'] + x)
    the sum of remaining intervals should be removed equals tot_cnt - cnt[1] (cnt_inv[gcdi-1] = tot_cnt - cnt[1])
    and x equals to cnt_inv[gcdi] - cnt_inv[gcdi-1] (cnt_inv[gcdi] - cnt_inv[gcdi-1] = tot_cnt - cnt[1'] - (tot_cnt - (cnt[1'] + x)) = -cnt[1'] + cnt[1'] + x = x)
    and the contribution of gcdi to answer equals to (cnt_inv[gcdi] - cnt_inv[gcdi-1]) * gcdi
*/
#include <iostream>
