using namespace std;
typedef long long LL;

const int MAXN = 200000 + 5;

int n;
int a[MAXN];
int exist[MAXN];
int _max;
int lazy[4*MAXN];
int board[4*MAXN];
long long cnt[4*MAXN];
long long tot_inv, cnt_inv[MAXN];

void pushup(int index) {
    board[index] = min(board[index*2], board[index*2+1]);
    cnt[index] = cnt[index*2] + cnt[index*2+1];
}

void pushdown(int index) {
    if (lazy[index] == 1) {
        long long s  = (cnt[index]/board[index]) / 2 + (cnt[index]/board[index]) % 2;
        cnt[index*2] = s * board[index];
        cnt[index*2+1] = cnt[index] - s * board[index];
        board[index*2] = board[index*2+1] = board[index];
        lazy[index*2] = lazy[index*2+1] = 1;
        lazy[index] = 0;
    }
}

void build(int index, int l, int r) {
    if (l == r) {
        board[index] = l;
        cnt[index] = l;
        return;
    }

    int mid = (l+r) / 2;
    build(index*2, l, mid);
    build(index*2+1, mid+1, r);
    pushup(index);
}

void update(int index, int l, int r, int left, int right, int BOARD) {
    if (left <= l && right >= r) {
        if (BOARD > board[index]) {
            board[index] = BOARD;
            cnt[index] = LL(r-l+1) * BOARD;
            lazy[index] = 1;
        }
        return;
    }
    pushdown(index);
    int mid = (l+r) / 2;
    if (left <= mid)
        update(index*2, l, mid, left, right, BOARD);
    if (mid+1 <= right)
        update(index*2+1, mid+1, r, left, right, BOARD);
    pushup(index);
}

int find(int index, int l, int r, int BOARD) {
    if (l == r)
        return l;

    int mid = (l+r) / 2;
    pushdown(index);
    if (board[index*2+1] < BOARD)
        return find(index*2+1, mid+1, r, BOARD);
    else
        return find(index*2, l, mid, BOARD);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }

    memset(exist, 0, sizeof(exist));
    for (int i = 1; i <= n; i++) {
        exist[a[i]] = i;
        _max = max(_max, a[i]);
    }

    build(1, 1, n);
    tot_inv = LL(n) * (n+1);
    cnt_inv[_max+1] = tot_inv - cnt[1]; cnt_inv[0] = 3;
    for (int i = _max; i >= 1; i--) {
        vector<int> v;

        v.clear();
        for (int j = i; j <= _max; j += i) {
            if (exist[j] > 0)
                v.push_back(exist[j]);
        }

        cnt_inv[i] = tot_inv - cnt[1];
        int k = v.size();
        if (k < 2)
            continue;

        sort(v.begin(), v.end());
        if (v[1]+1 <= n) {
            update(1, 1, n, v[1]+1, n, n+1);
        }
        if (board[1] < v[k-1]) {
            int pos = find(1, 1, n, v[k-1]);
            pos = min(pos, v[k-1]-1);
            update(1, 1, n, v[0]+1, pos, v[k-1]);
        }
        if (board[1] < v[k-2]) {
            int pos = find(1, 1, n, v[k-2]);
            pos = min(pos, v[k-2]-1);
            update(1, 1, n, 1, pos, v[k-2]);
        }
    }

    long long ans = 0;
    for (int i = _max; i >= 1; i--)
        ans += LL(cnt_inv[i]-cnt_inv[i-1]) * i;

    printf("%I64d\n", ans);
    return 0;
}

