//线段树
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 2e5+5;
ll H[N];
int a[N];
ll c[N<<2];//sum
ll s[N<<2];//min
ll lz[N<<2];//lazy
vector<int> v[N];//ve[i]:i的倍数的下标
int u,yl,yr;
void build(int o, int l, int r){
    if (l==r){
        lz[o]=l;
        c[o]=l; 
        s[o]=l;
        return;
    }
    int mid=(l+r)>>1;
    build(o<<1,l,mid);
    build(o<<1|1,mid+1,r);
    lz[o]=-1;
    c[o]=c[o<<1]+c[o<<1|1];
    s[o]=min(s[o<<1],s[o<<1|1]);
}
void pushdown(int o, int l, int r){
    if (l==r) return;
    if (lz[o]==-1) return;
    lz[o<<1]=lz[o]; lz[o<<1|1]=lz[o];
    s[o<<1]=lz[o]; s[o<<1|1]=lz[o];
    int mid=(l+r)>>1;
    c[o<<1]=lz[o]*(mid-l+1);
    c[o<<1|1]=lz[o]*(r-mid);
    lz[o]=-1;
}
void upd(int o, int l, int r){
    if (yl<=l&&yr>=r){
        c[o]=1LL*u*(r-l+1);
        s[o]=u;
        lz[o]=u;
        return;
    }
    pushdown(o,l,r);
    int mid=(l+r)>>1;
    if (yl<=mid) upd(o<<1,l,mid);
    if (yr>mid) upd(o<<1|1,mid+1,r);
    c[o]=c[o<<1]+c[o<<1|1];
    s[o]=min(s[o<<1],s[o<<1|1]);
    if (lz[o<<1]==lz[o<<1|1]&&lz[o<<1]>=0) lz[o]=lz[o<<1];
}
int query(int o, int l, int r){//返回小于k的最右侧的nexti的下标i 
    if (l==r&&c[o]<u) return l;
    if (l==r&&c[o]>=u) return 0;
    if (lz[o]!=-1&&lz[o]<u) return r;
    if (lz[o]!=-1&&lz[o]>=u) return 0;
    int mid=(l+r)>>1;
    if (s[o<<1|1]<u) return query(o<<1|1,mid+1,r);
    else return query(o<<1,l,mid);
}
int main(){
    int n; scanf("%d",&n);
    int mx=-1;
    memset(a,0,sizeof(a));
    for (int i=1; i<=n; i++){
        int tmp; scanf("%d",&tmp);
        a[tmp]=i;//保证所有元素都不同
        mx=max(mx,tmp);
    }
    for (int i=1; i<=mx; i++){
        for (int j=1; j*i<=mx; j++){
            if (a[j*i]) v[i].push_back(a[j*i]);
        }
    }
    for (int i=0; i<=mx; i++) sort(v[i].begin(),v[i].end());
    ll sum=1LL*n*(n+1);
    build(1,1,n);
    for (int i=mx; i>=0; i--){
        H[i]=sum-c[1];
        int k=v[i].size();
        if (k<2) continue;
        u=n+1;
        yl=v[i][1]+1; yr=n;
        if (yl<=yr) upd(1,1,n);//成段更新

        u=v[i][k-1];
        int pos=query(1,1,n);//Returns rightmost index i where nexti is less than some k
        pos=min(pos,v[i][1]);
        if (pos>v[i][0]&&pos<=v[i][1]){
            yl=v[i][0]+1,yr=pos;
            upd(1,1,n);
        }

        u=v[i][k-2];
        pos=query(1,1,n);
        pos=min(pos,v[i][0]);
        if (pos>=1&&pos<=v[i][0]){
            yl=1,yr=pos;
            upd(1,1,n);
        }
    }
    ll ans=0;
    for (int i=1; i<=mx; i++) ans+=1LL*i*(H[i]-H[i-1]);
    cout<<ans<<endl;
    return 0;
}

