long long h[MAX];

struct node{
    long long s;
    int l, mn, mx;
};

node smt[4*MAX];

void combine(int id, int c1, int c2){
    smt[id].s = smt[c1].s + smt[c2].s;
    smt[id].mn = min(smt[c1].mn, smt[c2].mn);
    smt[id].mx = max(smt[c1].mx, smt[c2].mx);
}

void update(int id, int l, int r, int x, int y, int v){
    if(y < l || x > r || smt[id].mn >= v) return;
    if(x <= l && r <= y && smt[id].mx <= v){
        smt[id].mn = smt[id].mx = smt[id].l = v;
        smt[id].s = (long long)(r - l + 1)*v;
        return;
    }
    int c1 = id*2 + 1; int c2 = id*2 + 2; int mid = (l + r)/2;
    if(smt[id].l != -1){
        smt[c1].mn = smt[c1].mx = smt[c1].l = smt[c2].mn = smt[c2].mx = smt[c2].l = smt[id].l;
        smt[c1].s = (long long)(mid - l + 1)*smt[id].l;
        smt[c2].s = (long long)(r - (mid + 1) + 1)*smt[id].l;
        smt[id].l = -1;
    }
    update(c1, l, mid, x, y, v);
    update(c2, mid + 1, r, x, y, v);
    combine(id, c1, c2);
}

void update(int x, int y, int v){
    update(0, 0, n - 1, x, y, v);
}

void build(int id, int l, int r){
    smt[id].l = -1;
    if(l == r){
        smt[id].mn = smt[id].mx = smt[id].s = l;
    }else{
        int c1 = id*2 + 1; int c2 = id*2 + 2;

        build(c1, l, (l + r)/2);
        build(c2, (l + r)/2 + 1, r);

        combine(id, c1, c2);
    }
}

