using namespace std;

#define N 200008
#define M 200005

int n;
int a[N],l1[N],r1[N],l2[N],r2[N];
long long h[N];

struct Tree
{
	int maxn[4*N],minn[4*N],flag[4*N];
	long long sum[4*N];

	inline void mark(int p,int l,int r,int x)
	{
		maxn[p] = minn[p] = x;
		sum[p] = (long long)x*(r-l+1);
		flag[p] = x;
	}

	inline void push_down(int p,int l,int r)
	{
		if (flag[p])
		{
			if (l == r)	return;
			int mid = (l+r) >> 1;
			mark(p*2,l,mid,flag[p]);
			mark(p*2+1,mid+1,r,flag[p]);
			flag[p] = 0;
		}
	}

	void insert(int p,int l,int r,int ll,int rr,int x)
	{
		if (minn[p] >= x)	return;
		if(ll <= l && rr >= r && x >= maxn[p])
		{
			mark(p,l,r,x);
			return;		
		}
		if (l == r)	return;
		push_down(p,l,r);
		int mid = (l+r) >> 1;
		if (ll <= mid)	insert(p*2,l,mid,ll,rr,x);
		if (rr > mid)	insert(p*2+1,mid+1,r,ll,rr,x);
		maxn[p] = max(maxn[p*2],maxn[p*2+1]);
		minn[p] = min(minn[p*2],minn[p*2+1]);
		sum[p] = sum[p*2] + sum[p*2+1];
	}

}T;

void init()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++)
		scanf("%d", &a[i]);
}

inline void add(int j,int i)
{
	if (!l1[j])	l1[j] = i;
	else if (!l2[j]) l2[j] = i;
	r1[j] = r2[j];
	r2[j] = i;
}

void prepare()
{
	for (int i = 1; i <= n; i++)
	{
		for (int j = 1; j <= (int)sqrt((double)a[i]); j++)
		{
			if (a[i] % j != 0)	continue;
			add(j,i);
			if (a[i] / j == j)	continue;
			add(a[i]/j,i);
		}
	}
}

void work()
{
	prepare();
	long long ans = 0;
	for (int i = 1; i <= n; i++)
		T.insert(1,1,n,i,i,i);
	h[M] = (long long)n*(n+1)/2;
	for (int i = M-1; i >= 0; i--)
	{
		h[i] = h[i+1];
		if (l1[i] == r2[i])	continue;
		T.insert(1,1,n,1,l1[i],r1[i]);
		T.insert(1,1,n,l1[i]+1,l2[i],r2[i]);
		if (l2[i]+1 <= n)
			T.insert(1,1,n,l2[i]+1,n,n+1);
		h[i] = (long long)n*(n+1)-T.sum[1];
	}
	for (int i = 1; i < M; i++)
		ans += ((long long)h[i] - h[i-1]) * (i-1);
	printf("%I64d\n", ans);
}

int main()
{
	init();
	work();
	return 0; 
}

