void sadra(int l, int r, int id){
    if(sina[id] == -1)  return;
    int mid = l + r >> 1;
    upd(l, mid, id << 1, sina[id]);
    upd(mid, r, id << 1 | 1, sina[id]);
    sina[id] = -1;
}
void arpa(int s, int e, int x, int l = 0, int r = n, int id = 1){
    if(s <= l && r <= e){
	upd(l, r, id, x);
	return;
    }
    if(e <= l || r <= s)  return;
    sadra(l, r, id);
    int mid = l + r >> 1;
    arpa(s, e, x, l, mid, id << 1), arpa(s, e, x, mid, r, id << 1 | 1);
    iman[id] = iman[id << 1] + iman[id << 1 | 1];
    dj[id] = dj[id << 1];
}
int doktor(int s, int e, int x, int l = 0, int r = n, int id = 1){
    if(e <= l || r <= s || dj[id] > x)  return -1;
    if(l + 1 == r)  return l;
    int mid = l + r >> 1, ans = doktor(s, e, x, mid, r, id << 1 | 1);
    return ~ans ? ans : doktor(s, e, x, l, mid, id << 1);
}
void amir(int s, int e, int x){  arpa(s, doktor(s, e, x) + 1, x);  }
