map<long long, long long> vl;
map<long long, long long>::iterator it, it2;

long long gv(long long a, long long b){
  if (a>b) return 0;
  long long m=0;
  it=vl.upper_bound(a); --it;
  long long la=(*it).F;
  long long lb=(*it).S;
  if (lb>=b) return 0;
  while (1){
    long long ia=(*it).F;
    long long ib=(*it).S;
    m+=(b-lb)*(ia-la);
    la=max(a, ia); lb=ib;
    if (ib>b || ia>b) break;
    it2=it; ++it2;
    if (ia>=a) vl.erase(it);
    it=it2;
  }
  vl[a]=b;
  return m;
}

