typedef long long LL;

const int MAXN = 200000 + 5;

int n;
int a[MAXN];
int exist[MAXN];
int _max;
int lazy[4*MAXN];
int board[4*MAXN];
long long cnt[4*MAXN];
long long tot_inv, cnt_inv[MAXN];

void pushup(int index) {
    board[index] = min(board[index*2], board[index*2+1]);
    cnt[index] = cnt[index*2] + cnt[index*2+1];
}

void pushdown(int index) {
    if (lazy[index] == 1) {
        long long s  = (cnt[index]/board[index]) / 2 + (cnt[index]/board[index]) % 2;
        cnt[index*2] = s * board[index];
        cnt[index*2+1] = cnt[index] - s * board[index];
        board[index*2] = board[index*2+1] = board[index];
        lazy[index*2] = lazy[index*2+1] = 1;
        lazy[index] = 0;
    }
}

void build(int index, int l, int r) {
    if (l == r) {
        board[index] = l;
        cnt[index] = l;
        return;
    }

    int mid = (l+r) / 2;
    build(index*2, l, mid);
    build(index*2+1, mid+1, r);
    pushup(index);
}

void update(int index, int l, int r, int left, int right, int BOARD) {
    if (left <= l && right >= r) {
        if (BOARD > board[index]) {
            board[index] = BOARD;
            cnt[index] = LL(r-l+1) * BOARD;
            lazy[index] = 1;
        }
        return;
    }
    pushdown(index);
    int mid = (l+r) / 2;
    if (left <= mid)
        update(index*2, l, mid, left, right, BOARD);
    if (mid+1 <= right)
        update(index*2+1, mid+1, r, left, right, BOARD);
    pushup(index);
}

int find(int index, int l, int r, int BOARD) {
    if (l == r)
        return l;

    int mid = (l+r) / 2;
    pushdown(index);
    if (board[index*2+1] < BOARD)
        return find(index*2+1, mid+1, r, BOARD);
    else
        return find(index*2, l, mid, BOARD);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }

    memset(exist, 0, sizeof(exist));
    for (int i = 1; i <= n; i++) {
        exist[a[i]] = i;
        _max = max(_max, a[i]);
    }

    build(1, 1, n);
    tot_inv = LL(n) * (n+1);
    cnt_inv[_max+1] = tot_inv - cnt[1]; cnt_inv[0] = 3;
    for (int i = _max; i >= 1; i--) {
        vector<int> v;

        v.clear();
        for (int j = i; j <= _max; j += i) {
            if (exist[j] > 0)
                v.push_back(exist[j]);
        }

        cnt_inv[i] = tot_inv - cnt[1];
        int k = v.size();
        if (k < 2)
            continue;

        sort(v.begin(), v.end());
        if (v[1]+1 <= n) {
            update(1, 1, n, v[1]+1, n, n+1);
        }
        if (board[1] < v[k-1]) {
            int pos = find(1, 1, n, v[k-1]);
            pos = min(pos, v[k-1]-1);
            update(1, 1, n, v[0]+1, pos, v[k-1]);
        }
        if (board[1] < v[k-2]) {
            int pos = find(1, 1, n, v[k-2]);
            pos = min(pos, v[k-2]-1);
            update(1, 1, n, 1, pos, v[k-2]);
        }
    }

    long long ans = 0;
    for (int i = _max; i >= 1; i--)
        ans += LL(cnt_inv[i]-cnt_inv[i-1]) * i;

    printf("%I64d\n", ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N = 2e5+7;
#define div Div
vector<int> div[N];
int L[N], a[N], ps[N], toset[4*N], n;
typedef long long ll;
ll seg[4*N], mx[4*N];
inline void makeL()
{
	for (int i = 0; i < N; i++) L[i] = n;
	for (int i = 0; i < n; i++)
		L[a[i]] = min(L[a[i]], i);
	L[1] = 0;
	for (int i = 2; i < N; i++)
		for (int j = i; j < N; j += i)
			L[i] = min(L[i], L[j]);
}
inline void divisor()
{
	for (int i = 1; i < N; i++)
	{
		for (int j = i; j < N; j += i)
			div[j].push_back(i);
		div[i].shrink_to_fit();
	}
}
inline void fix (int xl, int xr, int k, int val)
{
	toset[k] = mx[k] = val;
	seg[k] = 1ll * (xr - xl) * val;
}
inline void shift(int xl, int xr, int k)
{
	if (toset[k] == -1) return;
	int val = toset[k];
	toset[k] = -1;
	int xm = (xl+xr) / 2;
	fix(xl, xm, 2*k+1, val);
	fix(xm, xr, 2*k+2, val);
}
void Set(int ql, int qr, int val, int xl = 0, int xr = N, int k = 0)
{
	if (ql >= xr || qr <= xl) return;
	if (ql <= xl && qr >= xr)
	{
		fix(xl, xr, k, val);
		return;
	}
	shift(xl, xr, k);
	int xm = (xl+xr) / 2;
	Set(ql, qr, val, xl, xm, 2*k+1);
	Set(ql, qr, val, xm, xr, 2*k+2);
	seg[k] = seg[2*k+1] + seg[2*k+2];
	mx[k] = max(mx[2*k+1], mx[2*k+2]);
}
ll get (int ql, int qr, int xl = 0, int xr = N, int k = 0)
{
	if (ql >= xr || qr <= xl) return 0;
	if (ql <= xl && qr >= xr) return seg[k];
	int xm = (xl+xr)/2;
	shift(xl, xr, k);
	return get(ql, qr, xl, xm, 2*k+1) + get(ql, qr, xm, xr, 2*k+2);
}
int f(int ql, int qr, int val, int xl = 0, int xr = N, int k = 0)
{
	// first place betwen [ql, qr) > val;
	if (ql >= xr || qr <= xl || mx[k] <= val) return qr;
	if (xr - xl == 1)
	{
		if (mx[k] > val) return xl;
		return qr;
	}
	int xm = (xl + xr) / 2;
	shift(xl, xr, k);
	int p = f(ql, qr, val, xl, xm, 2*k+1);
	if (p != qr) return p;
	return f(ql, qr, val, xm, xr, 2*k+2);
}
inline void fix (int ql, int qr, int val)
{
	int pos = f(ql, qr, val);
	Set(ql, pos, val);
}
int tmp[N];
inline void initPS()
{
	memset(ps, 0, sizeof ps);
	memset(tmp, 0, sizeof tmp);
	for (auto x : div[a[0]])
		tmp[x]++;
	for (int i = 1; i < n; i++)
	{
		int res = 0;
		for (auto x : div[a[i]])
			if (tmp[x]++)
				res = x;
		ps[i] = max(ps[i-1], res);
	}
}
inline void init()
{
	initPS();
	for (int i = 0; i < n-1; i++)
		Set(i, i+1, ps[i]);
	reverse(a, a+n);
	initPS();
	reverse(ps, ps+n);
	reverse(a, a+n);
}
void print()
{
	cout << "\nprint: \n";
	for (int i = 0; i < n; i++)
		cout << get(i, i+1) << " ";
	cout << endl;
}
int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &a[i]);
	makeL();
	divisor();
	init();
	ll ans = get(0, n-1);
	ans += ps[1];
	for (int i = n-1; i > 1; i--)
	{
		int val = a[i];
		int ql = 0, qr = i-1;
		fix(ql, qr, ps[i]);
		for (auto x : div[val])
			if (L[x] < qr)
				fix(L[x], qr, x);
		ans += get(ql, qr);
		ans += ps[i];
	}
	printf("%lld\n", ans);
	return 0;
}

