ll f[N],ans;
struct node{
	int mx,mi;
	ll sum,tag;
}tr[N*4];
inline void updata(int x){
	tr[x].mx=max(tr[x<<1].mx,tr[x<<1|1].mx);
	tr[x].mi=min(tr[x<<1].mi,tr[x<<1|1].mi);
	tr[x].sum=tr[x<<1].sum+tr[x<<1|1].sum;
}
void build(int x,int l,int r){
	if (l==r){
		tr[x].mx=tr[x].mi=tr[x].sum=l;
		return;
	}
	int mid=(l+r)>>1;
	build(x<<1,l,mid);
	build(x<<1|1,mid+1,r);
	updata(x);
}
inline  void work(int x,int l,int r,ll m){
	tr[x].mx=tr[x].mi=m;
	tr[x].sum=m*(r-l+1);
	tr[x].tag=m;
}
void pushdown(int x,int l,int r){
	if (tr[x].tag){
		if (l==r) return;
		work(x<<1,l,(l+r)>>1,tr[x].tag);
		work(x<<1|1,((l+r)>>1)+1,r,tr[x].tag);
		tr[x].tag=0; 
	}
}
void modify(int x,int l,int r,int s,int t,ll m){
	pushdown(x,l,r);
	if (tr[x].mi>=m) return;
	if (l==s && r==t && m>tr[x].mx){
		work(x,l,r,m);
		return; 
	}
	int mid=(l+r)>>1;
	if (t<=mid) modify(x<<1,l,mid,s,t,m);
	else if (s>mid) modify(x<<1|1,mid+1,r,s,t,m);
	else {
		modify(x<<1,l,mid,s,mid,m);
		modify(x<<1|1,mid+1,r,mid+1,t,m);
	}
	updata(x);
}
