#include <bits/stdc++.h>
using namespace std;

const int N = (int)2e5;
typedef int arr[N + 10];
typedef long long ll;

int n, m, cnts;
arr a, ra;

struct segm {
	int l, r, d;
}s[3 * N + 10];

struct comp {
	bool operator () (const segm &a, const segm &b) { return a.d > b.d; }
};

ll cans;
set <segm, comp> ava;

void get_seg() {
	s[++cnts] = (segm){1, n, 1};
	for (int i = 2; i <= m; ++i) {
		int l1 = m + 1, l2 = m + 1, r1 = -1, r2 = -1;
		for (int j = i; j <= m; j += i) {
			int k = ra[j]; if (!k) continue;
			if (k < l1) l2 = l1, l1 = k; else if (k < l2) l2 = k;
			if (k > r2) r1 = r2, r2 = k; else if (k > r1) r1 = k;
		}
		if (l2 == m + 1 || r1 == -1) continue;
		if (l1 + 1 < r2) s[++cnts] = (segm){l1 + 1, r2 - 1, i};
		if (r1 > 1) s[++cnts] = (segm){1, r1 - 1, i};
		if (l2 < n) s[++cnts] = (segm){l2 + 1, n, i};
	}
}

bool cmp(const segm &a, const segm &b) { return (a.l < b.l) || (a.l == b.l && a.r < b.r); }

void insert(int st, segm ins) {
	if (ava.empty()) { cans += (ll)(ins.r - st + 1) * (ll)ins.d, ava.insert(ins); return; }
	set <segm, comp> :: iterator it = ava.lower_bound(ins), tmp;
	if (it == ava.end()) {
		--it;
		if (ins.r > (*it).r) cans += (ll)(ins.r - (*it).r) * (ll)ins.d, ava.insert(ins);
		return;
	}
	int lst = st - 1;
	if (it != ava.begin()) {
		--it;
		if (ins.r <= (*it).r) return;
		cans += (ll)ins.d * (ll)(ins.r - (*it).r);
		lst = (*it).r, ++it;
	}
	else cans += (ll)ins.d * (ll)(ins.r - st + 1);
	for ( ; it != ava.end() && (*it).r <= ins.r; ) {
		cans -= (ll)(*it).d * (ll)((*it).r - lst);
		tmp = it, lst = (*tmp).r, ++it, ava.erase(tmp);
	}
	if (it != ava.end()) {
		cans -= (ll)(*it).d * (ll)((*it).r - lst);
		cans += (ll)(*it).d * (ll)((*it).r - ins.r);
	}
	ava.insert(ins);
}

ll get_ans() {
	ll res = 0;
	sort(s + 1, s + cnts + 1, cmp);
	int cnt = 1;
	for (int i = 1; i <= n; ++i) {
		for ( ; cnt <= cnts && s[cnt].l == i; insert(i, s[cnt]), ++cnt);
		res += cans, cans -= (ll)(*ava.begin()).d;
		if ((*ava.begin()).r == i) ava.erase(ava.begin());
	}
	return res;
}

