ll cnt[N+5], minval[4*N+5], maxval[4*N+5], sumval[4*N+5], lazy[4*N+5];


void build(int node, int s, int e){
    if(s > e)   return;
    if(s == e){
        minval[node] = maxval[node] = sumval[node] = s;
        return;
    }
    int mid = (s+e)/2;
    build(LEFT(node), s, mid);
    build(RIGHT(node), mid+1, e);
    minval[node] = min(minval[LEFT(node)], minval[RIGHT(node)]);
    maxval[node] = max(maxval[LEFT(node)], maxval[RIGHT(node)]);
    sumval[node] = sumval[LEFT(node)] + sumval[RIGHT(node)];
}



int kth_query(int node, int s, int e, int threshold){
    if(minval[node] >= threshold)    return 0;
    if(s == e)  return s;
    int mid = (s+e)/2;
    if(minval[RIGHT(node)] < threshold)    return kth_query(RIGHT(node), mid+1, e, threshold);
    return kth_query(LEFT(node), s, mid, threshold);
}


void update(int node, int s, int e, int lo, int hi, ll val){
    if(s > e || lo > hi || val <= 0)   return;
    if(lazy[node] != 0){
        minval[node] = maxval[node] = lazy[node];
        sumval[node] = (e-s+1)*lazy[node];
        if(s != e){
            lazy[LEFT(node)] = lazy[RIGHT(node)] = lazy[node];
        }
        lazy[node] = 0;
    }
    if(lo > e || s > hi)    return;
    if(s >= lo && e <= hi){
        minval[node] = maxval[node] = val;
        sumval[node] = (e-s+1)*val;
        if(s != e){
            lazy[LEFT(node)] = lazy[RIGHT(node)] = val;
        }
        return;
    }
    int mid = (s+e)/2;
    update(LEFT(node), s, mid, lo, hi, val);
    update(RIGHT(node), mid+1, e, lo, hi, val);
    minval[node] = min(minval[LEFT(node)], minval[RIGHT(node)]);
    maxval[node] = max(maxval[LEFT(node)], maxval[RIGHT(node)]);
    sumval[node] = sumval[LEFT(node)] + sumval[RIGHT(node)];
}


ll sum_query(int node, int s, int e, int lo, int hi){
    if(s > e)   return 0;
    if(lazy[node] != 0){
        minval[node] = maxval[node] = lazy[node];
        sumval[node] = (e-s+1)*lazy[node];
        if(s != e){
            lazy[LEFT(node)] = lazy[RIGHT(node)] = lazy[node];
        }
        lazy[node] = 0;
    }
    if(lo > e || s > hi)    return 0;
    if(s >= lo && e <= hi)  return sumval[node];
    int mid = (s+e)/2;
    return sum_query(LEFT(node), s, mid, lo, hi) + sum_query(RIGHT(node), mid+1, e, lo, hi);
}


