int mn[200010*4],ch[200010*4];
ll sum[200010*4];
inline void down(int l,int r,int idx){
	if(ch[idx]!=-1){
		int mid=(l+r)>>1;
		mn[idx<<1|1]=mn[idx<<1]=ch[idx<<1]=ch[idx<<1|1]=ch[idx];
		sum[idx<<1]=(ll)(mid-l+1)*ch[idx];
		sum[idx<<1|1]=(ll)(r-mid)*ch[idx];
		ch[idx]=-1;
	}
}
void modify(int l,int r,int ql,int qr,int v,int idx){
	if(ql>qr) return;
	if(l==ql && r==qr){
		ch[idx]=mn[idx]=v;
		sum[idx]=(ll)v*(r-l+1);
	}else{
		int mid=(l+r)>>1;
		down(l,r,idx);
		if(qr<=mid) modify(l,mid,ql,qr,v,idx<<1);
		else if(ql>mid) modify(mid+1,r,ql,qr,v,idx<<1|1);
		else{
			modify(l,mid,ql,mid,v,idx<<1);
			modify(mid+1,r,mid+1,qr,v,idx<<1|1);
		}
		sum[idx]=sum[idx<<1]+sum[idx<<1|1];
		mn[idx]=min(mn[idx<<1],mn[idx<<1|1]);
	}
}
int find_left(int l,int r,int v,int idx){
	if(l==r){
		if(mn[idx]<v) return l;
		return -1;
	}
	down(l,r,idx);
	int mid=(l+r)>>1;
	if(mn[idx<<1]<v) return find_left(l,mid,v,idx<<1);
	return find_left(mid+1,r,v,idx<<1|1);
}
ll query(int l,int r,int ql,int qr,int idx){
	if(l==ql && r==qr) return sum[idx];
	int mid=(l+r)>>1;
	down(l,r,idx);
	if(qr<=mid) return query(l,mid,ql,qr,idx<<1);
	else if(ql>mid) return query(mid+1,r,ql,qr,idx<<1|1);
	return query(l,mid,ql,mid,idx<<1)+query(mid+1,r,mid+1,qr,idx<<1|1);
}
