vector<int> div[N];
int L[N], a[N], ps[N], toset[4*N], n;
typedef long long ll;
ll seg[4*N], mx[4*N];
inline void makeL()
{
	for (int i = 0; i < N; i++) L[i] = n;
	for (int i = 0; i < n; i++)
		L[a[i]] = min(L[a[i]], i);
	L[1] = 0;
	for (int i = 2; i < N; i++)
		for (int j = i; j < N; j += i)
			L[i] = min(L[i], L[j]);
}
inline void divisor()
{
	for (int i = 1; i < N; i++)
	{
		for (int j = i; j < N; j += i)
			div[j].push_back(i);
		div[i].shrink_to_fit();
	}
}
inline void fix (int xl, int xr, int k, int val)
{
	toset[k] = mx[k] = val;
	seg[k] = 1ll * (xr - xl) * val;
}
inline void shift(int xl, int xr, int k)
{
	if (toset[k] == -1) return;
	int val = toset[k];
	toset[k] = -1;
	int xm = (xl+xr) / 2;
	fix(xl, xm, 2*k+1, val);
	fix(xm, xr, 2*k+2, val);
}
void Set(int ql, int qr, int val, int xl = 0, int xr = N, int k = 0)
{
	if (ql >= xr || qr <= xl) return;
	if (ql <= xl && qr >= xr)
	{
		fix(xl, xr, k, val);
		return;
	}
	shift(xl, xr, k);
	int xm = (xl+xr) / 2;
	Set(ql, qr, val, xl, xm, 2*k+1);
	Set(ql, qr, val, xm, xr, 2*k+2);
	seg[k] = seg[2*k+1] + seg[2*k+2];
	mx[k] = max(mx[2*k+1], mx[2*k+2]);
}
ll get (int ql, int qr, int xl = 0, int xr = N, int k = 0)
{
	if (ql >= xr || qr <= xl) return 0;
	if (ql <= xl && qr >= xr) return seg[k];
	int xm = (xl+xr)/2;
	shift(xl, xr, k);
	return get(ql, qr, xl, xm, 2*k+1) + get(ql, qr, xm, xr, 2*k+2);
}
int f(int ql, int qr, int val, int xl = 0, int xr = N, int k = 0)
{
	// first place betwen [ql, qr) > val;
	//cout << ql << " " << qr << " " << val << " " << xl << " " << xr << " " << mx[k] << endl;
	if (ql >= xr || qr <= xl || mx[k] <= val) return qr;
	if (xr - xl == 1)
	{
		if (mx[k] > val) return xl;
		return qr;
	}
	int xm = (xl + xr) / 2;
	shift(xl, xr, k);
	int p = f(ql, qr, val, xl, xm, 2*k+1);
	if (p != qr) return p;
	return f(ql, qr, val, xm, xr, 2*k+2);
}

int f2(int ql, int qr, int val)
{
	int l = ql - 1, r = qr;
	while (r-l > 1)
	{
		int m = (l+r) / 2, x = get(m, m+1);
		if (x > val) r = m;
		else l = m;
	}
	return r;
}
inline void fix (int ql, int qr, int val)
{
	int pos = f(ql, qr, val);
	Set(ql, pos, val);
}
