#define lson l, mid, x<<1
#define rson mid+1, r, x<<1|1
using namespace std;
const int maxn=300005;
typedef __int64 ll;
struct node
{
    int ma;
    int mi;
    ll sum;
    int lazy;
    int l, r;
}tree[maxn*4];

ll getsum(int x)
{
    if( tree[x].lazy ) return 1LL*(tree[x].r-tree[x].l+1)*tree[x].lazy;
    else return tree[x].sum;
}

int getmax( int x )
{
    if( tree[x].lazy ) return tree[x].lazy;
    else return tree[x].ma;
}

int getmin( int x )
{
    if( tree[x].lazy ) return tree[x].lazy;
    else return tree[x].mi;
}

void pushup( int x )
{
    tree[x].sum = getsum( x << 1 ) + getsum( x << 1 | 1 );
    tree[x].ma = max( getmax(x<<1), getmax(x<<1|1) );
    tree[x].mi = min( getmin(x<<1), getmin(x<<1|1) );
}

void pushdown( int x )
{
    if( tree[x].lazy ){
        tree[x<<1].lazy = tree[x<<1|1].lazy = tree[x].lazy;
        tree[x].mi = tree[x].ma = tree[x].lazy;
        tree[x].sum = (ll)tree[x].lazy*(tree[x].r-tree[x].l+1);
        tree[x].lazy = 0;
    }
}

void build( int l, int r, int x )
{
    tree[x].l = l;tree[x].r = r;tree[x].lazy = 0;
    if( l == r ){
        tree[x].sum = tree[x].mi = tree[x].ma = l;
        return;
    }
    int mid = (l+r)>>1;
    build( lson );
    build( rson );
    pushup(x);
}

void update( int L, int R, int val, int l, int r, int x )
{
    if( R < L ) return;
    pushdown(x);// 在对区间做任何修改之前，先pushdown
    if( tree[x].mi >= val ){
        return ;
    }
    int mid = (l+r) >> 1;
    if( L == l && R == r ){
        if( tree[x].ma <= val ){
            tree[x].lazy = val;
            return ;
        }
        else{
            update( L, mid, val, lson );
            update( mid+1, R, val, rson );
            pushup(x);
            return ;
        }
    }
    if( R <= mid ) update( L, R, val, lson );
    else if( L > mid ) update( L, R, val, rson );
    else{
        update( L, mid, val, lson );
        update( mid+1, R, val, rson );
    }
    pushup(x);
}


int pos[maxn];
ll h[maxn];
vector<int>p;

int main()
{
    int i, j, n, m, x;
    scanf("%d", &n);
    for( i = 1; i <= n; i ++ ){
        scanf("%d", &x);
