    }
    build( 1, n, 1 );
    for( i = maxn-2; i >= 1; i -- ){
        p.clear();
        for( j = i+1; j < maxn; j += i+1 ){
            if( pos[j] ){
                p.push_back(pos[j]);
            }
        }
        sort( p.begin(), p.end() );
        int t = p.size();
        if( t > 1 ){
            update( 1, p[0], p[t-2], 1, n, 1 );
            update( p[0]+1, p[1], p[t-1], 1, n, 1 );
            update( p[1]+1, n, n+1, 1, n, 1 );
//            printf("id%d %d %d %d\n", i, 1,p[0],p[t-2]);
