vector<int> primes;
void calculatePrimes()
{
	primes.push_back(2);
	for (int i = 3; i < 500; i += 2)
	{
		bool bFound = false;
		int m = (int)sqrt((float)i);
		for (int j = 1; j < primes.size() && !bFound && primes[j] <= m; j++)
			bFound = ((i%primes[j]) == 0);
		if (!bFound)
			primes.push_back(i);
	}
}

void fillMap(map<int, int> & pr, map<int, vector<int>> & pos, int i, map<int, int>::iterator j, int cur)
{
	if (j == pr.end())
	{
		if (pos[cur].size() == 0 || pos[cur].back() != i)
		{
			if (pos[cur].size() < 4)
				pos[cur].push_back(i);
			else
			{
				pos[cur][pos[cur].size() - 2] = pos[cur].back();
				pos[cur][pos[cur].size() - 1] = i;
			}
		}
		return;
	}

	int mult = 1;
	int second = j->second;
	int first = j->first;
	j++;

	for (int k = 0; k <= second; k++)
	{
		fillMap(pr, pos, i, j, cur*mult);
		mult *= first;
	}
}


long long insertSegment(int from, int to, set<pair<pair<int,int>,int>> & fills)
{
	long long ar = 0;
	int st = 0;
	if (from == to) return st;
	int line = from;
	set<pair<pair<int, int>, int>>::iterator start = fills.lower_bound(mp(mp(from, to), 0));
	if (start != fills.begin()) start--;

	set<pair<pair<int, int>, int>>::iterator end = fills.upper_bound(mp(mp(to, to), 0));
	for (set<pair<pair<int, int>, int>>::iterator i = start; i != end; )
	{
		if (i->first.second >= from)
		{
			long long next = min(i->first.second, to);
			long long f = max(i->first.first, from);
			if (i->second == -1 || i->second > line)
			{
				int save = i->second;
				int end = i->first.second;
				int beg = i->first.first;
				ar += (i->second == -1)?(f + next + 1 - 2*line)*(next - f) / 2:(i->second - line)*(next - f);
				i = fills.erase(i);
				if (to == end)
				{
					if (beg < from)
						fills.insert(mp(mp(beg, from), save));
					fills.insert(mp(mp(from, to), line));
					return ar;
				}
				else if (end < to)
				{
					if (beg < from)
						fills.insert(mp(mp(beg, from), save));
				}
				else
				{
					if (beg < from)
						fills.insert(mp(mp(beg, from), save));
					fills.insert(mp(mp(from, to), line));
					fills.insert(mp(mp(to, end), save));
					return ar;
				}
			}
			else 
			{
				from = next;
				if (from == to) return st;
				i++;
			}
		}
		else i++;
	}
	return ar;
}

int main()
{
	calculatePrimes();

	int n;
	cin >> n;

	map<int, vector<int>> pos;

	for (int i = 0; i < n; i++)
	{
		int a;
		cin >> a;
		//a = rand() * 200000l / RAND_MAX;
		map<int,int> pr;
		for (int j = 0; j < primes.size() && a >= primes[j]*primes[j]; j++)
		{
			while (a%primes[j] == 0)
			{
				pr[primes[j]]++;
				a /= primes[j];
			}
		}
		if(a > 1)
			pr[a]++;
		fillMap(pr,pos,i,pr.begin(),-1);
	}

	map<int, vector<int>>::iterator i = pos.begin();


	set<pair<pair<int, int>, int>> fills;
	fills.insert(mp(mp(0, n), -1));

	long long totalsum = 0;

	while (i != pos.end())
	{
		vector<int> & cur = i->second;
		if (cur.size() <= 1) { i++; continue; }


		totalsum += insertSegment(0, cur[cur.size() - 2], fills) * i->first;
		totalsum += insertSegment(cur[0] + 1, cur.back(), fills) * i->first;
		totalsum += insertSegment(cur[1] + 1, n, fills) * i->first;

		i++;
	}
	cout << -totalsum;
