using namespace std;
typedef complex<double> point;
int x[21],y[21],angle[21];
double memo[1<<20];
int n,sx,ex;
//constexpr double PI() {return acos(-1.0);}

double fun(double sx,int i)
{
   point p1(x[i],y[i]);
   point p2(sx,0);
   point v=p2-p1; ///vecteur directeur
   v*=exp(point(0,angle[i]*Pi/180)); /// nouveau vecteur directeur
                                     /// P(t) = p1+t*v equation de la droite aprés la rotation
                                     /// y(t) = y1+t*v
                                     /// 0 = p1.Y + t*v.Y intersection avec l'axe des abcisses
   if(atan2(v.Y,v.X)>-eps) {return ex;}
   double t = -p1.Y/v.Y;
   double x = p1.X+t*v.X;
   return x;
}

double solve(int mask)
{
   if(!mask) return sx;
   double &ret=memo[mask];
   if(ret == ret) return ret;
   ret=sx;
   for(int i=mask;i;i-=i&(-i))
   {
        int j=i&(-i);
        double x=solve(mask^j);
        ret = max(ret,fun(x,log2(j)+eps));

   }
   return memo[mask]=ret = min(ret,ex*1.0);
}





int main()
{   //ifstream cin("in");
    cin>>n>>sx>>ex;
    memset(memo,-1,sizeof memo);
    for(int i=0;i<n;i++) cin>>x[i]>>y[i]>>angle[i];
    double answ=solve((1<<(n))-1);
    cout<<fixed<<setprecision(9)<<answ-(double)sx;
    return 0;
}

