{
	init();
	dfs1(1,0,0);
	a[1]=1;a[2]=2;a[3]=3;
	dfs2(1,1,1);
	for (int i=0;i<bin[tot];i++)
	{
		int t=0;
		for (int j=1;j<=tot;j++)
		{
			int rev=id[bin[n]-1-sta[j]];
			if (i&bin[j-1]) t+=bin[rev-1];
		}
		g[t]=f[i];f[i]=0;
	}
	a[1]=4;a[2]=5;a[3]=6;
	dfs2(1,1,1);
	pre();
	int ans=0;
	for (int i=0;i<bin[tot];i++)
		(ans+=(LL)f[i]*g[bin[tot]-1-i]%MOD)%=MOD;
	printf("%d\n",(1-ans+MOD)%MOD);
	return 0;
}

