		int p = 1; int S[3];
		for(int j=0;j<M * n;++j) p = ll(p) * (i >> j & 1 ? b[j + n * m] : mod + 1 - b[j + n * m]) % mod;
		for(int j=0;j<M;++j) S[j] = (i >> j * n) & ((1 << n) - 1); 
		int st = 0;
		for(int j : v[n - m]){
			int s[3],tot = 0;
			for(int k=j;k;k&=k-1) s[tot++] = __builtin_ctz(k);
