				for(int j=0;j<M;++j) if((S[j] >> s[j] & 1) == 0) goto nxt2;
				st |= 1 << mp[(~j) & (1 << n) - 1];
				nxt2:;
			}while(next_permutation(s,s+M));
		}
		reduce(g[st] += p - mod);
	}
