	for(int i=0;i<1<<tot[m];++i) f[i] = ll(f[i]) * g[i] % mod;
	fwt2(f,1<<tot[m]);
	for(int i=1;i<1<<tot[m];++i) reduce(ans += f[i] - mod);
	out,ans,'\n';
}

