		}
		for(int i = 1;i <= 6;i ++) {
			for(int j = i + 1;j <= 6;j ++) {
				for(int k = j + 1;k <= 6;k ++) {
					if(check(i,j,k)) {
						int X, Y, Z; X = Y = Z = - 1;
						used[i] = used[j] = used[k] = 0;
						for(int l = 1;l <= 6;l ++) {
							if(!used[l]) continue;
							if(X == -1) X = l;
							else if(Y == -1) Y = l;
							else Z = l;
						}
						used[i] = used[j] = used[k] = 1;
						if(Z == -1) continue;
            sta |= num[X][Y][Z];
					}
				}
			}
		}
		updata(p[sta],now);
		return;
	}
	g[x][y] = 1; int nxt = mul(now,a[x][y]);
	if(y == 6) dfs1(nxt,x + 1,1);
	else dfs1(nxt,x,y + 1);
	g[x][y] = 0; nxt = mul(now,dec(1,a[x][y]));
	if(y == 6) dfs1(nxt,x + 1,1);
	else dfs1(nxt,x,y + 1);
}

void dfs2(int now, int x, int y) {
