const LL mod=1e9+7;
LL qp(LL x,LL p){
	LL ret=1;
	while (p){
		if (p&1) ret=ret*x%mod;
		x=x*x%mod;
		p>>=1; 
	}
	return ret;
}
LL inv(LL x){
	return qp(x,mod-2);
}
