void flow2(vector<int>& P, int si, int ti, int d) {
	int i;
	if (si == ti) return;
	if (A[P[si + 1]] + d <= V) {
		A[P[si]] -= d;
		A[P[si + 1]] += d;
		R.push_back(make_pair(make_pair(P[si], P[si + 1]), d));
		flow2(P, si + 1, ti, d);
	}
	else {
		int d2 = V - A[P[si + 1]];
		A[P[si]] -= d2;
		A[P[si + 1]] += d2;
		if (d2 > 0) R.push_back(make_pair(make_pair(P[si], P[si + 1]), d2));
		flow2(P, si + 1, ti, d);
		A[P[si]] -= d - d2;
		A[P[si + 1]] += d - d2;
		R.push_back(make_pair(make_pair(P[si], P[si + 1]), d - d2));
	}
}

