bool find;
long long cpcum;

void checksum(int now)
{
    visited[now] = 1;
    cpcum += (c[now] - b[now]);
    if (c[now] - b[now] > 0) mo.push(now);
    else if (c[now] - b[now] < 0) le.push(now);
    for (int i = 0; i < node[now].size(); i++)
    {
        int next = node[now][i];
        if (visited[next]) continue;
        checksum(next);
    }
}

bool dfs(int now, int s, int t)
{
    for (int i = 0; i < node[now].size(); i++)
    {
        int next = node[now][i];
        if (parent[next] != -1) continue;
        parent[next] = now;
        if (next == t)
        {
            return true;
        }
        if (dfs(next, s, t)) return true;
    }
    return false;
}


void write(int s, int t,int d,int v)
{
    if (parent[t] == s)
    {
        ans.push_back(make_pair(make_pair(s, t), d));
        c[s] -= d;
        c[t] += d;
        return;
    }
    else if (c[parent[t]] >= d)
    {
        c[t] += d;
        c[parent[t]] -= d;
        ans.push_back(make_pair(make_pair(parent[t],t), d));
        write(s, parent[t], d, v);
    }
    else
    {
        ans.push_back(make_pair(make_pair(parent[t],t), c[parent[t]]));
        int temp = c[parent[t]];
        c[parent[t]] = 0;
        write(s, parent[t], d ,v);
        ans.push_back(make_pair(make_pair(parent[t], t), d - temp));
        c[t] += d;
        c[parent[t]] = temp;

    }

}

