bool path(int v){
	vis[v]=cs;
	p[++l]=v;
	if( b[v]>a[v] ) return 1;

	for(int i=0;i<n;++i)
		if(g[v][i] && vis[i]!=cs)
			if( path(i) )
				return 1;
	--l;
	return 0;
}

LL s1,s2;
bool aux[N];
void check(int v){
	aux[v]=1;
	s1+=a[v],s2+=b[v];
	for(int i=0;i<n;++i)
		if( g[v][i] && !aux[i])
			check(i);
}

vector<string> ans;
char buff[50];
void flow(int i,int flw){

	int v=p[i],u=p[i+1];
	if(a[v]<flw){
		sprintf(buff,"%d %d %d",v+1,u+1,a[v]);
		ans.push_back(buff);
		flow(i-1,flw);
		sprintf(buff,"%d %d %d",v+1,u+1,flw-a[v]);
		ans.push_back(buff);
	}else{
		sprintf(buff,"%d %d %d",v+1,u+1,flw);
		ans.push_back(buff);
		if(i)
			flow(i-1,flw);
	}

}

