        ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;

	int u, v;

	for (int i = 1; i < n; ++i) {
		cin >> u >> v;
		g[u].pb(v);
		g[v].pb(u);
	}

	for (int i = 1; i <= n; ++i) {
		cin >> a[i].x >> a[i].y;
		a[i].pos = i;
	}

	dfs(1, -1);

	rec(1, 1, -1);

	for (int i = 1; i <= n; ++i)
		cout << ans[i] << ' ';

	return 0;
}

