#define int long long
using namespace std;

const int N=1505;
int n,tot;
int lnk[N],nxt[2*N],son[2*N],sz[N],ans[N];
struct myt{
    int x,y,id;
}dot[N],t;

int read(){
    int s=0,w=1;
    char ch=getchar();
    while (ch<'0'||ch>'9') {if (ch=='-') w=-1;ch=getchar();}
    while (ch>='0'&&ch<='9') s=(s<<3)+(s<<1)+ch-'0',ch=getchar();
    return s*w;
}

inline void add(int a,int b){son[++tot]=b;nxt[tot]=lnk[a];lnk[a]=tot;}

inline int cross(myt a,myt b,myt c){
    return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
}

bool cmp(myt a,myt b){
    return cross(t,a,b)>0;
}

void dfs_size(int s,int fa){
    sz[s]=1;
    int j=lnk[s];
    while (j){
        if (son[j]==fa) {j=nxt[j];continue;}
        dfs_size(son[j],s);
        sz[s]+=sz[son[j]];
        j=nxt[j];
    }
    return;
}

void dfs_ans(int l,int r,int rt,int fa){
    int x=l;
    for (int i=l+1;i<=r;++i)
    if (dot[i].x<dot[x].x||(dot[i].x==dot[x].x&&dot[i].y<dot[x].y)) x=i;
    t=dot[x];dot[x]=dot[l];dot[l]=t;
    sort(dot+1+l,dot+1+r,cmp);
    ans[dot[l].id]=rt;
    int now=l+1,j=lnk[rt];
    while (j){
        if (son[j]==fa) {j=nxt[j];continue;}
        dfs_ans(now,now+sz[son[j]]-1,son[j],rt);
        now+=sz[son[j]];
        j=nxt[j];
    }
    return;
}

signed main(){
    n=read();
    for (int i=1;i<n;++i){
        int u=read(),v=read();
        add(u,v);add(v,u);
    }
    for (int i=1;i<=n;++i) dot[i].x=read(),dot[i].y=read(),dot[i].id=i;
    dfs_size(1,0);
    dfs_ans(1,n,1,0);
    for (int i=1;i<=n;++i) printf("%d ",ans[i]);
    return 0;
}

