#define N 2000
#define ll long long
using namespace std;
ll n;
struct sett{
    ll x,y,id;
}p[N],plk;
struct zero{
    ll nxt,to;
}edge[N<<1];
ll tot=0,head[N];
ll size[N];
ll Ans[N];
void add_edge(ll a,ll b){
edge[++tot]=(zero){head[a],b};
head[a]=tot;
}
void aux(ll x,ll fa){
    size[x]=1;
    for(ll i=head[x];i;i=edge[i].nxt)
    {
        ll to=edge[i].to;
        if(to==fa)continue;
        aux(to,x);
        size[x]+=size[to];
    }
}
bool cmp(sett a,sett b)
{
    ll ax=a.x-plk.x,ay=a.y-plk.y,bx=b.x-plk.x,by=b.y-plk.y;
    if(ax>=0&&bx<=0)return 1;
    if(ax<=0&&bx>=0)return 0;
    return (ax*by>ay*bx);
}
void solve(ll l,ll r,ll x,ll fa){
    ll poss=l;
    for(ll i=l+1;i<=r;i++)
    if(p[i].x<p[poss].x||(p[i].x==p[poss].x&&p[i].y<p[poss].y))poss=i;
    swap(p[l],p[poss]);
    plk=p[l];
    Ans[p[l].id]=x;
    //cout<<"steps:"<<x<<" "<<p[l].id<<" "<<l<<" "<<r<<endl;
    sort(p+l+1,p+r+1,cmp);
    // for(int i=l+1;i<=r;i++)cout<<p[i].id<<" ";
    // cout<<endl;
    ll now=l+1;
    for(ll i=head[x];i;i=edge[i].nxt)
    {ll to=edge[i].to;
    if(to==fa)continue;
    solve(now,now+size[to]-1,to,x);
    now+=size[to];
    }
}
int main(){
    scanf("%lld",&n);
    for(ll i=1;i<n;i++)
    {
        ll a,b;
        scanf("%lld%lld",&a,&b);
        add_edge(a,b);
        add_edge(b,a);
    }
    for(ll i=1;i<=n;i++){
        ll x,y;
        scanf("%lld%lld",&x,&y);
        p[i]=(sett){x,y,i};
    }
    aux(1,0);
    solve(1,n,1,0);
    for(ll i=1;i<=n;i++)
    printf("%lld ",Ans[i]);
}

#include<bits/stdc++.h>
