using namespace std;
struct cd
{
    int x,y,id;
} a[500005],xx;
struct ab
{
    int f,t;
} t[500005];
int h,hh[500005],size[500005],ans[500005];
void make(int x,int y)
{
    t[++h].f=hh[x];
    t[h].t=y;
    hh[x]=h;
}
int cmp(cd x,cd y)
{
    if(x.x-xx.x>0&&y.x-xx.x<0) return 1;
    if(x.x-xx.x<0&&y.x-xx.x>0) return 0;
    return (x.x-xx.x)*(y.y-xx.y)>(x.y-xx.y)*(y.x-xx.x);
}
void dfs1(int x,int y)
{
    size[x]=1;
    for(int i=hh[x];i;i=t[i].f)
    {
        int j=t[i].t;
        if(j==y) continue;
        dfs1(j,x);
        size[x]+=size[j];
    }
}
void dfs2(int l,int r,int x,int y)
{
    for(int i=l+1;i<=r;i++)
    {
        if(a[i].x<a[l].x||(a[i].x==a[l].x&&a[i].y<a[l].y)) swap(a[i],a[l]);
    }
    ans[a[l].id]=x;
    xx=a[l];
    l++;
    sort(a+l,a+r+1,cmp);
    for(int i=hh[x];i;i=t[i].f)
    {
        int j=t[i].t;
        if(j==y) continue;
        dfs2(l,l+size[j]-1,j,x);
        l+=size[j];
    }
}
