vector<pair<int, int> > points;
int n;
vector<int> parent;
vector<int> size;

vector<int> mapping;
vector<vector<int> > edges;

void solve(vector<int> &vertices, int root) {
	if (vertices.size() != size[root]) {
		cout << "Ooops";
		exit(0);
	}
	int v = vertices.front();
	for (auto v2 : vertices) if (points[v2] < points[v]) v = v2;
	FOR (i, 0, vertices.size()) {
		if (vertices[i] == v) {
			vertices[i] = vertices.back();
			vertices.pop_back();
		}
	}

	mapping[v] = root + 1;
	if (!vertices.size()) return;

	int y0 = points[v].second;
	int x0 = points[v].first;

	vector<pair<double, int> > v2;
	for (auto vi : vertices) v2.push_back(make_pair(atan2(points[vi].second - y0, points[vi].first - x0), vi));
	sort(all(v2));

	int p = 0;
	for (auto dest : edges[root]) if (parent[root] != dest) {
		vector<int> nextPoints;
		while (nextPoints.size() < size[dest]) nextPoints.push_back(v2[p++].second);
		solve(nextPoints, dest);
	}
}

int main() {
	srand (time(NULL));
    ios_base::sync_with_stdio(false); cin.tie(NULL);

	cin >> n;
	parent.resize(n);
	edges.resize(n);
	FOR (i, 0, n - 1) {
		next(int, a);
		next(int, b);
		a--;
		b--;
		edges[a].push_back(b);
		edges[b].push_back(a);
	}

	vector<int> q;
	q.push_back(0);
	mapping.resize(n);
	parent[q[0]] = -1;

	FOR (i, 0, n) {
		int v = q[i];
		for (auto e : edges[v]) if (e != parent[v]) {
			parent[e] = v;
			q.push_back(e);
		}
	}

	points = readVector<pair<int, int> >(n);

	size.assign(n, 1);
	FORD (i, n - 1, 0) {
		int v = q[i];
		if (parent[v] != -1) size[parent[v]] += size[v];
	}

	vector<int> vertices(n);
	FOR (i, 0, n) vertices[i] = i;
	solve(vertices, q[0]);

	cout << mapping;
}

