namespace std
{
    bool operator<(const P& a, const P& b)
    {
        return a.imag() != b.imag() ? a.imag() < b.imag() : a.real() < b.real();
    }
};
ll cross(const P& a, const P& b) { return a.real() * b.imag() - a.imag() * b.real(); }
struct Comp
{
    P base;
    Comp(const P& base)
        : base(base) { }
    bool operator()(const P& a, const P& b) const
    {
        P x = a - base, y = b - base;
        return cross(x, y) > 0;
    }
};

