int dfs_size(int v, int prev)
{
    size[v] = 1;
    for (int i = 0; i < e[v].size(); ++i)
        if (e[v][i] != prev)
            size[v] += dfs_size(e[v][i], v);
    return size[v];
}

int res[1511];
void build(int v, int prev, P* part)
{
    P cur = *part;
    res[index[cur]] = v + 1;
    ++part;

    sort(part, part + (size[v] - 1), Comp(cur));

    for (int i = 0; i < e[v].size(); ++i)
    {
        int to = e[v][i];
        if (to != prev)
        {
            build(to, v, part);
            part += size[to];
        }
    }
}
