	  return -a;
	else
	  return a;
}
void dfs(ll now,ll fa)
{
	si[now]=1;
	for (ll i=0;i<e[now].size();i++)
	{
		ll u;
		u=e[now][i];
		if (u!=fa)
		{
			dfs(u,now);
			si[now]+=si[u];
		}
	}
}
bool cmp(node a,node b)
{
	return (ll)a.dy*b.dx<(ll)a.dx*b.dy;
}
void solve(ll now,ll fa,ll l,ll r)
{
	ll root;
	node MAX;
	MAX.x=1e18;
	MAX.y=1e18;
	for (ll i=l;i<=r;i++)
	{
		if (sh[i]<MAX)
		{
			MAX=sh[i];
			root=i;
		}
	}
	ans[sh[root].wh]=now;
	if (l==r)
	  return;
	for (ll i=l;i<=r;i++)
	{
		sh[i].dx=sh[i].x-sh[root].x;
		sh[i].dy=sh[i].y-sh[root].y;
	}
	if (root!=l)
	  swap(sh[l],sh[root]);
	sort(sh+l+1,sh+r+1,cmp);
	ll ml,mr;
	ml=l+1;
	mr=l;
	for (ll i=0;i<e[now].size();i++)
	{
		ll u;
		u=e[now][i];
		if (u!=fa)
		{
			mr+=si[u];
			solve(u,now,ml,mr);
			ml=mr+1;
		}
	}
}
