	int subtree,num;
	vector <int> next;
};

int N;
vertex g[1510]; //our tree
point pnt[1510]; //points
int ans[1510]; //answer
vector <point> v; //points that we work with

void precalc_dfs(int v, int p=-1){ //precalculating subtree values
	g[v].subtree=1;
	for (int i=0; i<g[v].next.size(); i++)
		if (g[v].next[i]!=p){
			precalc_dfs(g[v].next[i],v);
			g[v].subtree+=g[g[v].next[i]].subtree;
		}
}

void build(vector <point> a, int from, int p=-1){
	int n=a.size();
	int mini=-1,minx=INF,miny=INF;
	for (int i=0; i<n; i++)
		if (a[i].x<minx || (a[i].x==minx && a[i].y<miny))
			mini=i,minx=a[i].x,miny=a[i].y;
	ans[a[mini].num]=from; //HERE WE FIX THE ANSWER
	a[mini]=a[n-1];
	a.pop_back(); n--;
	for (int i=0; i<n; i++)
		a[i].x-=minx, a[i].y-=miny;
	std::sort(a.begin(),a.end());
	int cur_alloc=0;
	for (int i=0; i<g[from].next.size(); i++)
		if (g[from].next[i]!=p){
			vector <point> b;
			for (int j=0; j<g[g[from].next[i]].subtree; j++)
				b.push_back(a[j+cur_alloc]);
			cur_alloc+=g[g[from].next[i]].subtree;
			build(b,g[from].next[i],from);
		}
}

