	for (int i = 0; i < n - 1; ++i) {
		int u, v;
		scanf("%d%d", &u, &v);
		--u, --v;
		edge[u].push_back(v);
		edge[v].push_back(u);
	}
	dfs(0, -1);
	for (int i = 0; i < n; ++i) {
		int x, y;
		scanf("%d%d", &x, &y);
		p.push_back(make_pair(i, make_pair(x, y)));
	}
	solve(0, p);
	for (int i = 0; i < n; ++i) {
		printf("%d%c", ans[i] + 1, i == n - 1 ? '\n' : ' ');
	}
	return 0;
}

