#define MAXN 2*1599
int Count = 0;
int L[MAXN];
int Next[MAXN];
int H[MAXN];
int X[MAXN];
int Y[MAXN];
int U[MAXN];
int Visit[MAXN];
int Visit1[MAXN];
int V[MAXN];
int n;
int S[MAXN];
int Size[MAXN];
pair<long double, int> Ang[MAXN];

void getSize(int root) {
	int sum = 1;
	Visit[root] = 1;
	for(int idx = H[root]; idx; idx = Next[idx]) {
		int u = L[idx];
		if (Visit[u]) continue;
		//~ cout << root << ":" << u << endl;
		getSize(u);
		sum += Size[u];
	}
	Size[root] = sum;
}

void addLink(int u, int v) {
	L[++Count] = v;
	Next[Count] = H[u];
	H[u] = Count;
}

long double getAngle(int u, int v) {
	if (u==v) return -2;
	long double dx = X[v] - X[u];
	long double dy = Y[v] - Y[u];
	//~ cout << dx << dy;

	return dy*1.0/sqrtl(dx*dx + dy*dy);
}

void divide(int l, int r, int root) {
	int min = l;
	rep(i, l+1, r)
		if (make_pair(X[Ang[i].se], Y[Ang[i].se]) < 
			make_pair(X[Ang[min].se], Y[Ang[min].se]))
			min = i;
	swap(Ang[l], Ang[min]);
	S[Ang[l].se] = root;
	Visit1[root] = 1;
	rep(i, l, r)
		Ang[i].fi = getAngle(Ang[l].se, Ang[i].se);

	sort(Ang+l+1, Ang+1+r);
	//~ rep(i, l , r) cout << Ang[i].fi << ":" << Ang[i].se << " ";
	//~ cout << endl;
	int cl = l+1;
	for(int idx = H[root]; idx; idx = Next[idx]) {
		int u = L[idx];
		if (Visit1[u]) continue;
		divide(cl, cl + Size[u] - 1, u);
		cl += Size[u];
	}
}

int main() {

	cin >> n;
	rep(i, 1, n-1) { 
		cin >> U[i] >> V[i]; 
		addLink(U[i], V[i]); 
		addLink(V[i], U[i]);
	}


	rep(i, 1, n) cin >> X[i] >> Y[i];
	getSize(1); // Size array

	int min = 1;
	rep(i, 2, n) if (make_pair(X[i],Y[i]) < make_pair(X[min], Y[min]))
		min = i;
	//~ cout << X[min] << ":" << Y[min] << endl;

	//~ cout <<"HEllp" << endl;
	rep(i, 1, n) Ang[i] = make_pair(0, i);
	swap(Ang[1], Ang[min]);
	divide(1, n, 1);

	rep(i, 1, n-1)
		cout << S[i] << " ";
	cout << S[n] << endl;

	return 0;
}

