double tanj(int x,int y,int x1,int y1){
    return (double)(y1-y)/(x1-x);
}

bool cmp1(Point x,Point y){
    return x.a<y.a;
}

bool cmp2(Point x,Point y){
    return (long long)(x.b-st.b)*(y.a-st.a)<(long long)(y.b-st.b)*(x.a-st.a);
}

void add(int u,int v){
    nxt[++en]=h[u];h[u]=en;vet[en]=v;
}

void dfs(int u){
    siz[u]=1;
    for (int e=h[u];e;e=nxt[e]){
        int v=vet[e];
        if (!d[v]){
            d[v]=d[u]+1;
            fa[v]=u;
            dfs(v);
            siz[u]+=siz[v];
        }
    }
}

void solve(int u,vector<Point> vec){
    num[vec[0].c]=u;
    st=vec[0];
    sort(vec.begin()+1,vec.end(),cmp2);
    vector <Point> tmp;int now=1;
    for (int e=h[u];e;e=nxt[e]){
        int v=vet[e];
        tmp.clear();
        if (v!=fa[u]){
            while (tmp.size()<siz[v]){tmp.push_back(vec[now]);now++;}
            solve(v,tmp);
        }
    }
}

