        q.push(path[v][i]);
        vis[path[v][i]]=1;
    }
}
void get_tree()
{
    bool vis[1505]={};
    q.push(1);
    vis[1]=1;
    while(!q.empty())
    {
        int t=q.front();
        q.pop();
        push_v(t,vis);
    }

}
