const int MN = 1500 + 10;

struct point {
	ll x, y;
	int k;
	point () {};
	point (ll xx, ll yy, int kk) {
		x = xx, y = yy;
		k = kk;
	}
	static ll dist(point a, point b) {
		return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
	}
	point operator-(point &nw) const {
		point p;
		p.x = x - nw.x;
		p.y = y - nw.y;
		return p;
	}
	static ll kos(point a, point b, point c) {
		point v1 = a - b;
		point v2 = c - b;
		return v1.x * v2.y - v1.y * v2.x;
	}
};

vector <int> g[MN];

int n;

point arr[MN];

int sz[MN];

bool used[MN];

void dfs(int v) {
	used[v] = true;
	for(int i = 0; i < g[v].size(); i ++) {
		int nv = g[v][i];
		if (!used[nv]) {
			dfs(nv);
			sz[v] += (sz[nv] + 1);
		}
	}
}

point p0;

int ans[MN];

bool my(point a, point b) {
	ll k = point::kos(a, p0, b);
	return (k < 0);
}

void solve(int lf, int rg, int root) {
	used[root] = true;
	for(int i = lf; i <= rg; i ++) {
		if (arr[i].y < arr[lf].y || (arr[i].y == arr[lf].y && arr[i].x < arr[lf].x))
			swap(arr[lf], arr[i]);
	}
	p0 = arr[lf];
	sort(arr + lf + 1, arr + rg + 1, my);
	ans[ arr[lf].k ] = root + 1;
	lf ++;
	for(int i = 0; i < g[root].size(); i ++) {
		int to = g[root][i];
		if (used[to])
			continue;
		solve(lf, lf + sz[to], to); //?
		lf += (sz[to] + 1);
	}
}


