using namespace std;

#define MAXN (1505)

const long double pi = acosl(-1);

int N;

vector <int> edge[MAXN];

int xi[MAXN];
int yi[MAXN];

int P[MAXN];

int par[MAXN]; // tree node's parent
int V[MAXN];
int tsize[MAXN]; // subtree size

int sol[MAXN];

void dfs(int id)
{
	V[id] = 1;
	tsize[id] = 1;

	int sz = edge[id].size();
	for(int i = 0; i < sz; ++i)
	{
		int a = edge[id][i];

		if(V[a] == 0)
		{
			par[a] = id;
			dfs(a);

			tsize[id] += tsize[a];
		}
	}

//	printf("node size %d : %d\n", id + 1, tsize[id]);
}

long double sang[MAXN]; // angles used for sorting

bool cmpf(int a, int b)
{
	return sang[a] < sang[b];
}

void painttree(int id, int l, int r) // id - l, children - [l + 1, r)
{
//	printf("pt %d [%d %d) : %d\n", id + 1, l, r, P[l] + 1);
	sol[P[l]] = id + 1;

	if(l + 1 < r)
	{
		int root = P[l];
		int i;

		if(1 || tsize[id] > 3) // have more than 2 children
		{
			long double minang = 100;
			long double maxang = -100;

			for(i = l + 1; i < r; ++i)
			{
				int a = P[i];
				sang[a] = atan2l(yi[a] - yi[root], xi[a] - xi[root]);

				if(minang > sang[a])
					minang = sang[a];
				if(maxang < sang[a])
					maxang = sang[a];
			}

			if(maxang > minang + pi)
			{
				for(i = l + 1; i < r; ++i)
				{
					int a = P[i];
					if(sang[a] < 0)
						sang[a] += 2.0*pi;
				}
			}

			sort(P + l + 1, P + r, cmpf);

/*
			printf("sorted for %d :", id + 1);
			for(i = l + 1; i < r; ++i)
				printf(" %d", P[i] + 1);
			putchar('\n');
//*/
		}

		int sz = edge[id].size();
		int j = l + 1;
		for(i = 0; i < sz; ++i)
		{
			int a = edge[id][i];
			if(par[a] == id)
			{
				painttree(a, j, j + tsize[a]);
				j += tsize[a];
			}
		}
	}
}

int main()
{
	int i;

	scanf("%d", &N);
	for(i = 1; i < N; ++i)
	{
		int a, b;
		scanf("%d %d", &a, &b);
		--a;
		--b;

		edge[a].push_back(b);
		edge[b].push_back(a);
	}

	dfs(0);

	int xl = 1000000001;
	int yl = 1000000001;
	int idl = 0;

	for(i = 0; i < N; ++i)
	{
		scanf("%d %d", &xi[i], &yi[i]);

		if(xl > xi[i] || (xl == xi[i] && yl > yi[i]))
		{
			xl = xi[i];
			yl = yi[i];
			idl = i;
		}

		P[i] = i;
	}

//	printf("leftmost %d\n", idl + 1);

	P[idl] = 0;
	P[0] = idl;

	painttree(0, 0, N);

	for(i = 0; i < N; ++i)
	{
		if(i)
			putchar(' ');
		printf("%d", sol[i]);
	}
	putchar('\n');

	return 0;
}

