	int best = l;
	for (int i=l;i<=r;i++)
		if ( v[i].y < x.y ) {
			x = v[i];
			best = i;
		}
	ans[x.k] = root;
	swap(v[best], v[l]);

	if (l==r) return;
	for (int i=l+1;i<=r;i++)
		v[i].x-=v[l].x, v[i].y-=v[l].y;
	sort(v+l+1, v+r+1, cmp);

	int now = l+1;
	for (int i=h[root];i;i=next[i])
		if (size[g[i]]<size[root]) {
			dfs(g[i], now, now+size[g[i]]-1);
			now+=size[g[i]];
		}
}

