using namespace std;
struct point64_t {
	int64_t x, y, num;
	point64_t() { x = 0, y = 0, num = 0; }
	point64_t(int64_t a, int64_t b, int64_t c) {
		x = a, y = b, num = c;
	}
};
struct Vector {
	int64_t x, y;
	Vector() { x = 0, y = 0; }
	Vector(point64_t a, point64_t b) { x = b.x - a.x, y = b.y - a.y; }
};
int64_t skal(Vector a, Vector b) {
	return (a.x * b.x + a.y * b.y);
}
int64_t vect(Vector a, Vector b) {
	return (a.x * b.y - a.y * b.x);
}
point64_t minp;
bool cmp(point64_t& a, point64_t& b) {
	Vector i(minp, a);
	Vector j(minp, b);
	if (vect(i, j) == 0) {
		return skal(i, i) < skal(j, j);
	}
	return vect(i, j) > 0;
}
vector<vector<int64_t>> g;
vector<int64_t> sz;
vector<int64_t> par;
void dfs(int64_t v, int64_t p) {
	sz[v] = 1;
	par[v] = p;
	for (auto u : g[v]) {
		if (u != p) {
			dfs(u, v);
			sz[v] += sz[u];
		}
	}
}
vector<int64_t> sootv;
void solve(int64_t root, vector<point64_t> a) {
	int64_t n = a.size();
	vector<pair<pair<int64_t, int64_t>, int64_t>> help(n);
	for (int64_t i = 0; i < n; ++i) {
		help[i] = { {a[i].x,a[i].y},i };
	}
	sort(help.begin(), help.end());
	minp = a[help[0].second];
	vector<point64_t> b;
	for (int64_t i = 0; i < n; ++i) {
		if (i != help[0].second) b.push_back(a[i]);
	}
	sort(b.begin(), b.end(), cmp);
	sootv[minp.num] = root;
	for (auto u : g[root]) {
		if (u == par[root]) continue;
		vector<point64_t> c;
		for (int64_t j = 0; j < sz[u]; ++j) {
			c.push_back(b[b.size() - 1]);
			b.pop_back();
		}
		solve(u, c);
	}
}
