using namespace std;
typedef long long ll;
typedef vector<int> vi;
struct point{
    point(){};
    point(ll x_, ll y_, int i_):x(x_),y(y_),idx(i_){};
    ll x;
    ll y;
    int idx;
};

//const point nilpair = make_pair(numeric_limits<ll>::min(),numeric_limits<ll>::min());
bool cmpr(const point& l, const point& r){
    ll s = l.x * r.y - l.y * r.x;
    return s > 0;
}
void place(int vert, vector<point>& p, int l, int r, vi& a,  vector<vi>& c, vi& sz){
    int root = l;
    if (l > r) return;
    for (int i = l; i < r; ++i){
        if (p[i].y > p[root].y){
            root = i;
        }
    }
    a[p[root].idx] = vert + 1;
    swap(p[root],p[l]);
    if (l == r) return;    
    for(int i = l+1; i < r; ++i){
        p[i].x -= p[l].x;
        p[i].y -= p[l].y;
    }
    sort(p.begin() + l + 1, p.begin() + r,cmpr);
    int pos = l+1;
    for(int i = 0; i < c[vert].size(); ++i){
        if (sz[c[vert][i]] < sz[vert]){
            place(c[vert][i], p, pos, pos + sz[c[vert][i]],a,c,sz);
            pos += sz[c[vert][i]];
        }
    }
}
int main(void)
{
    int n;
    cin >> n;
    vector<int> v(n,0);
    vector<int>  sz(n,0);    
    vector<vector<int> > c(n);
    vector<point> pts(n);
    int i = n-1;
    while(i--){
        int s, d;
        cin >> s >> d;
        c[s-1].push_back(d-1);
        c[d-1].push_back(s-1);
    }
    stack<int> s;
    s.push(0);
    while(!s.empty()){
        int vr = s.top();
        if (0 == v[vr]){
            v[vr] = 1;
            sz[vr] = 1;
        }
        for(int i = 0; i < c[vr].size(); ++i){
            if (0 == v[c[vr][i]]){
                s.push(c[vr][i]);
                break;
            }
        }
        if (vr == s.top()){
            v[vr] = 2;
            s.pop();
            for(int i = 0; i < c[vr].size(); ++i){
                if (2 == v[c[vr][i]]) sz[vr] += sz[c[vr][i]];
            }
        }
    }
    for(int i = 0; i < n; i++){
        ll x, y;
        cin >> x >> y;
        pts[i] = point(x, y, i);
    }
    place(0, pts, 0, pts.size(), v, c, sz);
    for(int i = 0; i < n; ++i){
        cout << v[i] <<' ';
    }
    cout << endl;
    return 0;
}

