	s = b[0];
	for (int i = 1; i < b.size(); ++i) if (b[i] < s) s = b[i];
	sort(b.begin(), b.end(), cmp);
	int l = 1;
	ans[s.num] = fa;
	for (int i = fstc[fa]; i; i = nxtc[i]) {
		int k = c[i];
		vector<Point>m;
		for (int j = 1; j <= sz[k]; ++j) m.push_back(b[l]), l++;
		solve(m, k);
	}
}
