typedef pair<int,int> PII;
typedef pair<PII,int> PIII;

int n;
bool adj[1501][1501];
int vtx[1501];
vector<bool> chk;
vector <PIII> points;
vector <PII> res;

int dfs(int node)
{
    int cnt = 0;
    chk[node] = true;
    for(int i = 1;i <= n;++i) 
        if(!chk[i] && adj[node][i])
            cnt += dfs(i);
    vtx[node] = cnt+1;
    return vtx[node];
}

void go(int root, vector<PIII> ps)
{
    int min_y = INT_MAX, min_i = -1;
    for(int i = 1;i <= ps.size()-1;++i) if(ps[i].F.S < min_y) {min_y = ps[i].F.S; min_i = i;}
    res.push_back(MP(ps[min_i].S,root));
    vector<pair<long double,int> > tps(1);
    for(int i = 1;i <= ps.size()-1;++i) if(i != min_i) tps.push_back(MP(atan2l(ps[i].first.first-ps[min_i].first.first,ps[i].first.second-ps[min_i].first.second),i));
    sort(tps.begin()+1,tps.end());
    int s = 1;
    for(int i = 1;i <= n;++i) if(adj[root][i]) {
        vector<PIII> nps(1);
        while(nps.size() < vtx[i]+1) {
            nps.push_back(ps[tps[s].S]);
            ++s;
        }
        adj[i][root] = false;
        go(i,nps);
    }
