void DFStree(int v)
{
  sub[v] = 1;
  for (auto u : g[v])
  {
    if (u == par[v]) continue;
    par[u] = v;
    DFStree(u);
    sub[v] += sub[u];
  }
}

void build(int vRoot, vi points)
{
  int pRoot = points[0];
  for (auto p : points)
  {
    if (y[p] < y[pRoot] || (y[p] == y[pRoot] && x[p] < x[pRoot])) pRoot = p;
  }
  ans[pRoot] = vRoot;

  vector< pair<double, int> > sorted;
  for (auto p : points)
  {
    if (p == pRoot) continue;
    int xDif = x[p] - x[pRoot], yDif = y[p] - y[pRoot];
    sorted.eb(atan2(yDif+.0, xDif+.0), p);
  }

  sort(all(sorted));

  for (auto u : g[vRoot])
  {
    if (u == par[vRoot]) continue;
    vi forSubtree;
    while (sz(forSubtree) < sub[u])
    {
      forSubtree.pb(sorted.back().nd); sorted.pop_back();
    }
    build(u, forSubtree);
  }
}


