void go(vi p, int v, int parent) {
    int min_i = 0;
    REP(i, 0, p.size()) {
        if (mp(X[p[i]], Y[p[i]]) < mp(X[p[min_i]], Y[p[min_i]]))
            min_i = i;
    }

    swap(p[0], p[min_i]);

    REP(i, 0, p.size()) {
        if(i != 0) {
            X[p[i]] -= X[p[0]];
            Y[p[i]] -= Y[p[0]];
        }
    }

    sort(p.begin() + 1, p.end(), cmp);

    REP(i, 0, p.size()) {
        if(i != 0) {
            X[p[i]] += X[p[0]];
            Y[p[i]] += Y[p[0]];
        }
    }

    int pos = 1, u;
    ans[p[0]] = v;

    REP(i, 0, G[v].size()) {
        u = G[v][i];
        if(u != parent) {
            vi q;
            REP(i, 0, size[u]) {
                q.pb(p[pos++]);
            }
            go(q, u, v);
        }
    }
}

