int n,head[2*N],tot=0,ans[N],size[N];
void add(int u,int v)
{
    edge[++tot].to=v;
    edge[tot].nxt=head[u];
    head[u]=tot;
}
bool cmp(point a,point b)
{
    int ax=a.x-poi.x;
    int ay=a.y-poi.y;
    int bx=b.x-poi.x;
    int by=b.y-poi.y;
    if (ax>=0 && bx<=0) return true;
    if (ax<=0 && bx>=0) return false;
    return ax*by>ay*bx;
}
void dfs_size(int u,int fa)
{
    size[u]=1;
    for (int i=head[u];i;i=edge[i].nxt)
    {
        int v=edge[i].to;
        if (v==fa) continue;
        dfs_size(v,u);
        size[u]+=size[v];
    }
}
void dfs(int l,int r,int u,int fa)
{
    int x=l;
    for (int i=l+1;i<=r;i++)
    {
        if (p[i].x<p[x].x || (p[i].x==p[x].x && p[i].y<p[x].y)) x=i;
    }
    swap(p[l],p[x]);
    ans[p[l].id]=u;
    poi=p[l];
    sort(p+l+1,p+r+1,cmp);
    int now=l+1;
    for (int i=head[u];i;i=edge[i].nxt)
    {
        int v=edge[i].to;
        if (v==fa) continue;
