inline int sgn(Type x) {
    return (x > eps) - (x < -eps);
}

struct Point {
    Type x, y, id;
    Point() : x(0), y(0) {}

    Point(Type _x, Type _y) : x(_x), y(_y) {}

    void set(Type _x, Type _y) {
        this->x = _x; this->y = _y;
    }

    Point operator + (const Point &p) const {
        return Point(x + p.x,  y + p.y);
    }

    Point operator - (const Point &p) const {
        return Point(x - p.x, y - p.y);
    }

    Point operator * (const Type &q) const {
        return Point(x * q, y * q);
    }

    Point operator / (const Type &q) const {
        return Point(x / q, y / q);
    }

    bool operator == (const Point &p) const {
        return fabs(p.x - x) < eps && fabs(p.y - y) < eps;
    }

    bool operator != (const Point &p) const {
        return ((*this) == p) == false;
    }

    friend bool operator < (const Point &p1, const Point &p2) {
        return p1.y < p2.y || (p1.y == p2.y && p1.x < p2.x);
    }

    void read() {
        cin >> this->x >> this->y;
    }

    void print() const {
        cout << "Point" << x << "," << y << endl;
    }
};

inline Type Dot(const Point &p1, const Point &p2) {
    return p1.x * p2.x + p1.y * p2.y;
}

inline Type Cross(const Point &p1, const Point &p2) {
    return p1.x * p2.y - p2.x * p1.y;
}

inline Type Length2(const Point &p1) {
    return p1.x * p1.x + p1.y * p1.y;
}

inline Type Length(const Point &p) {
    return sqrt(Length2(p));
}

inline Type Angle(const Point &p) {
    return atan2(p.y, p.x);
}

