bool use[2005];
int main() {
    cin >> n;
    for(int i = 1;i <= n;i++) {
        p[i].read();p[i].id = i;
        o = o + p[i];
    }
    o = o / n;
    for(int i = 1;i <= n;i++) use[i] = true;
    for(int i = 1;i <= n;i++) {
        if(!use[i]) continue;
        if(Length(p[i] - o) == 0) {
            use[i] = false; continue;  
        }
        for(int j = i + 1;j <= n;j++) {
            if(!use[j]) continue;
            if(sgn( Length((p[i] + p[j]) / 2 - o) == 0 )) {
                use[i] = use[j] = false;
                break;
            }
        }
    }
    int pos = 0;
