		sort(d+1,d+n+1);

		bool flag=true;
		for(int i=1;i<=n;++i)
		{
			if(d[i]+d[n-i+1]>eps)
			{
				flag=false;
				break;
			}
		}
		if(flag)
			l[++cnt]=tl;
	}

	int ans=0;
	for(int i=1;i<=cnt;++i)
	{
		int flag=true;
		for(int j=1;j<i;++j)
			if(l[i].sam(l[j]))
			{
				flag=false;
				break;
			}
		if(flag)
			++ans;
	}
	printf("%d\n",ans);
//	printf("%d\n",clock());

	return 0;
}

