struct Point {
	int64_t x, y;

	auto toPair() {
		return make_pair(x, y);
	}

	inline friend ostream & operator <<(ostream &os, const Point &p) {
		return os << "{" << p.x << ", " << p.y << "}";
	}
};

signed main() {
	#ifndef USE_FILE_IO
		ios_base::sync_with_stdio(false);
	#endif
	int n; cin >> n;
	vector<Point> v(n);
	int64_t sumX = 0, sumY = 0;
	for (int i = 0; i < n; i++) {
		cin >> v[i].x >> v[i].y;
		sumX += v[i].x;
		sumY += v[i].y;
	}
	Fraction pX {sumX, n}, pY {sumY, n};
	vector<char> active(n, true);
	for (int i = 0; i < n; i++) {
		if (v[i].x == pX && v[i].y == pY) {
			active[i] = false;
		}
		if (!active[i]) {
			continue;
		}
		for (int j = 0; j < i; j++) {
			if (!active[j]) {
				continue;
			}
			if (v[i].x + v[j].x == 2 * pX && v[i].y + v[j].y == 2 * pY) {
				active[i] = active[j] = false;
				break;
			}
		}
	}
	vector<Point> q;
	for (int i = 0; i < n; i++) {
		if (active[i]) {
			q.push_back(v[i]);
		}
	}
	if (q.empty()) {
		cout << -1 << endl;
		return 0;
	}

	set<Fraction> anses;
	int qs = q.size();

	auto check = [&](const Fraction &x, const Fraction &y) {
		if (2*pX == q[0].x + x) {
			return;
		}

		Fraction fK = -(2*pY - q[0].y - y) / (2*pX - q[0].x - x);
		long double k = fK.toDouble();
		long double pivot = pX.toDouble() * k + pY.toDouble();

		vector<long double> p(qs);
		for (int j = 0; j < qs; j++) {
			p[j] = q[j].x * k + q[j].y;
		}
		sort(p.begin(), p.end());
		bool ok = true;
		for (int j = 0; j < qs; j++) {
			if (abs(2 * pivot - p[j] - p[qs - j - 1]) > (long double)1e-9) {
				ok = false;
				break;
			}
		}
		if (ok) {
			anses.insert(fK);
		}
	};

	for (int i = 1; i < qs; i++) {
		check(q[i].x, q[i].y);
	}
	check(pX, pY);

	int ans = anses.size();
	auto v2 = v;
	set<int64_t> uniqueX;
	sort(v2.begin(), v2.end(), [&](Point a, Point b) -> bool {
		return a.x < b.x;
	});
	for (int i = 0; i < n; i++) {
		uniqueX.insert(v2[i].x + v2[n-i-1].x);
	}
	ans += uniqueX.size() == 1;

	cout << ans << endl;
	return 0;
}

