const int maxn = 4000 + 5;
int n;

int dj[maxn];
int size[maxn];
int odds;
int ncache;
pair<int*, int> cache[maxn * maxn / 2];

void init(int k) {
    FOR(i, 0, k) dj[i] = i, size[i] = 1;
    odds = k;
}
void reset() {
    while (ncache > 0) {
        *cache[ncache - 1].fi = cache[ncache - 1].se;
        ncache--;
    }
}
int find(int u) {
    if (dj[u] == u) return dj[u];
    cache[ncache++] = mp(&dj[u], dj[u]);
    return dj[u] = find(dj[u]);
}
void join(int u, int v) {
    int p = find(u);
    int q = find(v);
    if (p != q) {
        cache[ncache++] = mp(&dj[p], dj[p]);
        dj[p] = q;
        cache[ncache++] = mp(&odds, odds);
        if (size[p] & 1) {
            odds--;
        }
        if (size[q] & 1) {
            odds--;
        }
        cache[ncache++] = mp(&size[q], size[q]);
        size[q] += size[p];
        if (size[q] & 1) {
            odds++;
        }
    }
}

void solve() {
    srand(time(NULL));
    cin >> n;
    vector<PT> p(n);
    PT cen;
    map<PT, int> hs, tmp;
    for (PT& q : p) {
        cin >> q.x >> q.y;
        cen = cen + q;
        q.x *= n, q.y *= n;
        hs[q] ^= 1;
        tmp[q] = 1;
    }
    FOR(i, 0, n) {
        PT q = cen + cen - p[i];
        hs[q] ^= 1;
    }
    p.clear();
    for (auto it : hs) {
        if (it.fi != cen && it.se) {
            p.pb(it.fi);
        }
    }
    if (!sz(p)) {
        cout << -1 << "\n";
        return;
    }
    unordered_map<long long, vii> hs2;
    map<long long, int> can;
    FOR(i, 0, sz(p)) FOR(j, i + 1, sz(p)) if (tmp.count(p[i]) + tmp.count(p[j]) == 1) {
        PT q = p[i] - p[j];
        if (q.y < 0 || (!q.y && q.x < 0)) q.x *= -1, q.y *= -1;
        int g = __gcd(abs(q.x), abs(q.y));
        q.x /= g, q.y /= g;
        long long t = (long long) (q.x + INF) * (INF + INF) + (q.y + INF);
        if (!i) {
            can[t] = 1;
            hs2[t].pb(mp(i, j));
        }
        else if (can.count(t)) {
            hs2[t].pb(mp(i, j));
        }
    }
    int k = sz(p);
    init(k);
    int res = 0;
    for (auto it : hs2) if (can[it.fi]) {
        reset();
        for (auto x : it.se) {
            join(x.fi, x.se);
        }
        if (!odds) {
            res++;
        }
    }
    cout << res << "\n";
}

