        {
            long long x = 1LL * a1 * b2 - 1LL * a2 * b1, y = a1 - a2, d = gcd (x, y), z = b1 - b2, t = a1 - a2, d2 = gcd (z, t);
            //S.insert (unghi (1LL * a2 * b1 - 1LL * a1 * b2, b1 - b2));
            x /= d, y /= d, z /= d2, t /= d2;
            if (y < 0) y = -y, x = -x;
            if (t < 0) z = -z, t = -t;
            S.push_back ({{x, y}, {z, t}});
        }
        else S.push_back ({{0, 0}, {0, 0}});
    }
}

