struct point {
	ld x, y;
	point(ld X = 0, ld Y = 0) {
		x = X, y = Y;
	}
	point operator+(point a) {
		return point(x + a.x, y + a.y);
	}
	point operator-(point a) {
		return point(x - a.x, y - a.y);
	}
	ld operator*(point a) {
		return x * a.y - y * a.x;
	}
	point operator*(ld k) {
		return point(x * k, y * k);
	}
	ld len() {
		return sqrt(x * x + y * y);
	}
};

bool operator==(point a, point b) {
	return a.x == b.x && a.y == b.y;
}

point norm(point a) {
	ld r = a.len();
	a.x /= r;
	a.y /= r;
	return a;
}

