point p[2100];
int en[2100];
vector<ld> v1;
vector<ld> v2;
vector<point> ans;

int main() {
	point sum = 0;
	cin >> n;
	for (int i = 0; i < n; ++i) {
		cin >> p[i].x >> p[i].y;
		sum = sum + p[i];
	}
	for (int i = 0; i < n; ++i) {
		for (int j = i; j < n; ++j) {
			point xx = p[i] + p[j];
			if (xx * n == sum * 2) {
				en[i] = 1;
				en[j] = 1;
			}
		}
	}
	int st = -1;
	for (int i = 0; i < n; ++i) {
		if (!en[i]) {
			st = i;
			break;
		}
	}
	if (st == -1) {
		cout << -1 << "\n";
		return 0;
	}
	sum.x /= n;
	sum.y /= n;
	for (int i = 0; i < n; ++i)
		p[i] = p[i] - sum;
	for (int i = 0; i < n; ++i) {
		point xx = norm(p[i] + p[st]);
		v1.clear();
		v2.clear();
		for (int j = 0; j < n; ++j) {
			ld cc = (p[j] * xx);
			if (abs(cc) > eps) {
				if (cc > 0)
					v1.push_back(cc);
				else
					v2.push_back(-cc);
			}
		}
		sort(v1.begin(), v1.end());
		sort(v2.begin(), v2.end());
		if (v1.size() != v2.size())
			continue;
		int fl = 0;
		for (int j = 0; j < v1.size(); ++j) {
			if (abs(v1[j] - v2[j]) >= eps) {
				fl = 1;
				break;
			}
