const int MAXN = 20001;

int n;
ll x[MAXN], y[MAXN];

void rm(int id) {
    for (int i = id; i + 1 < n; ++i) {
        x[i] = x[i + 1];
        y[i] = y[i + 1];
    }
    --n;
}

ll vals[MAXN];
int ans = 0;

const int BTS = 20;
const ll MSK = (1 << BTS) - 1;

pair<ll, ll> mul(ll x, ll y) {
    bool sgn = false;

    if (x < 0) {
        x = -x;
        sgn = !sgn;
    }

    if (y < 0) {
        y = -y;
        sgn = !sgn;
    }

    ll xl = x & MSK;
    x >>= BTS;
    ll yl = y & MSK;
    y >>= BTS;

    ll lw = (xl * yl);
    ll bg = ((x * y) << BTS) + x * yl + y * xl + (lw >> BTS);
    lw &= MSK;

    if (sgn) {
        bg = -bg;
        lw = -lw;
    }

    return { bg, lw };
}


int origx[MAXN];
int origy[MAXN];
int orign;

void work(ll mdx, ll mdy) {
    bool cool = true;
    for (int j = 0; j < orign; ++j) {
        vals[j] = origx[j] * mdx + origy[j] * mdy;
    }

    sort(vals, vals + orign);

    ll s = vals[0] + vals[orign - 1];

    for (int j = 0; j < orign - 1 - j; ++j) {
        if (vals[j] + vals[orign - 1 - j] != s) {
            cool = false;
            break;
        }
    }

    if (cool) {
        ++ans;
    }
}

