vector <Point> proste, rzuty;

long long kw(long long a) {return a*a;}

long double dist(Point& a, Point& b)
{
	return kw(a.first - b.first) + kw(a.second - b.second);
}

Point srodek(Point& a, Point& b)
{
	return Point((a.first + b.first) / 2, (a.second + b.second) / 2);
}

void add(Point& a, Point& b)
{
	a.first += b.first;
	a.second += b.second;
}

void mult(Point& a, long long b)
{
	a.first *= b;
	a.second *= b;
}

int main()
{
	int n;
	scanf ("%d", &n);
	Point mass_cent = Point(0, 0);

	for (int i=0; i<n; i++)
	{
		scanf ("%lld%lld", &T[i].first, &T[i].second);
		add (mass_cent, T[i]); 
		mult (T[i], n*2);
	}

	mult(mass_cent, 2);
	Point fix = INFpoint;

	for (int i=0; i<n; i++)
	{
		bool ok = true;

		for (int j=0; j<n; j++)
		{
			if (srodek(T[i], T[j]) == mass_cent)
			{
				ok = false;
				break;
			}
		}

		if (ok)
		{
			fix = T[i];
			break;
		}
	}

	if (fix == INFpoint)
	{
		printf("-1\n");
		return 0;
	}	

	for (int i=0; i<n; i++)
	{
		Point s = srodek(fix, T[i]);
		long long a = s.first - mass_cent.first;
		long long b = s.second - mass_cent.second;
		long long c = __gcd(a, b);
		a /= c, b /= c;
		if (a < 0)	a *= -1, b *= -1;
		proste.push_back(make_pair(a, b));
	}

	sort(proste.begin(), proste.end());
	proste.resize(unique(proste.begin(), proste.end()) - proste.begin());
	int res = 0;

	for (int i=0; i<proste.size(); i++)
	{
		long long A = proste[i].first, B = proste[i].second;

		for (int j=0; j<n; j++)
		{
			long long d = B * T[j].first - A * T[j].second;
			rzuty.push_back(make_pair(B * d, (-A) * d));
		}

		sort(rzuty.begin(), rzuty.end());
		bool ok = true;

		for (int j=1; j<=n/2; j++)
		{
			long double d1 = dist(rzuty[j], rzuty[j - 1]);
			int k = rzuty.size() - j;
			long double d2 = dist(rzuty[k], rzuty[k - 1]);
			if (d1 != d2)
			{
				ok = false;
				break;
			}
		}

		if (ok)	res++;
		rzuty.resize(0);
	}

	printf("%d\n", res);
	return 0;
}

