    for (int i = 1; i <= n; i ++) {
        int flag = 0;
        for (int j = 1; j <= n; j ++) {
            if ((p[j]+p[i])*(p[j]+p[i])<EPS || ((p[j]+p[i])/2-M)*((p[j]+p[i])/2-M)<EPS) 
                flag = 1;
        }
        if (flag) sym ++;
        else pos = i;
    }



    if (sym == n) {
        printf("%d\n", -1);
        return 0;
    }

    swap(p[1], p[pos]);


    for (int i = 1; i <= n; i ++) {
        if ((p[1]+p[i])*(p[1]+p[i])<EPS)
            continue;

        if (((p[1]+p[i])/2-M)*((p[1]+p[i])/2-M)<EPS)
            continue;

        Point P = (p[1] + p[i]) / 2;
        Line L = Line(P, P - M);
        for (int j = 1; j <= n; j ++) {
