        bool ok = 1;
        for (int i = 1; i <= n; i ++) {
            if (d[i] + d[n+1-i] > EPS) {
                ok = 0; break;
            }
        }
        if (ok) l[++cnt] = L;
    }

    //printf("%d\n", cnt);
    int ans = 0;
    for (int i = 1; i <= cnt; i ++) {
        int flag = 1;
        for (int j = 1; j < i; j ++) {
            if (l[i].same(l[j])) flag = 0;
        }
        if (flag) ans ++; 
    }
    printf("%d\n", ans);

}

