    }
};

Line getLine(pdd p, pdd q) {
    return { (q.second - p.second), (p.first - q.first), (q.first - p.first) * p.second - (q.second - p.second) * p.first };
}

vector<lf> slope;

int main() {
    scanf("%d", &N);

    lf xsum = 0;
    lf ysum = 0;
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &P[i].first, &P[i].second);
        xsum += P[i].first;
        ysum += P[i].second;
    }

    C = { xsum / N, ysum / N };

    for(int i = 0; i < N; i++) {
        for(int j = i; j < N; j++) {
            if(abs(2 * C.first - P[i].first - P[j].first) < 1e-9 && abs(2 * C.second - P[i].second - P[j].second) < 1e-9) {
                chk[i] = 1;
                chk[j] = 1;
                break;
            }
        }
    }

    for(int i = 0; i < N; i++) if(!chk[i]) tmp.push_back(P[i]);
