            tmp.push_back(line.f(P[j].first, P[j].second));
        }
        sort(tmp.begin(), tmp.end());

        bool ok = true;
        for(int j = 0; j < N; j++) if(abs(tmp[j] + tmp[N - 1 - j]) > 1e-9) {
            ok = false;
            break;
        }
        if(ok) {
            if(line.a == 0) slope.push_back(1e9);
            else slope.push_back(line.b / line.a);
        }
    }

    sort(slope.begin(), slope.end());
