#include <cassert>
#define MAXN 2005
#define eps 1e-8
using namespace std;

const double PI = acos(-1);

struct Point {
    double x, y;

    Point(): x(0), y(0) {}
    Point(double x, double y): x(x), y(y) {}

    friend Point operator+(const Point &A, const Point &B);
    friend Point operator/(const Point &A, double k);
};

Point operator+(const Point &A, const Point &B) {
    return Point(A.x + B.x, A.y + B.y);
}

Point operator/(const Point &A, double k) {
    return Point(A.x / k, A.y / k);
}

int n;
Point p[MAXN], mass;
bool erased[MAXN];
vector<Point> vp;

bool equal(double x, double y) {
    return fabs(x - y) < eps;
}

struct Comp {
    bool operator()(double a, double b) {
        if (equal(a, b))
            return 0;
        return a < b;
    }
};

map<double, int, Comp> posLines;


Point getVector(const Point &A, const Point &B) {
    Point v(A.x - B.x, A.y - B.y);

    if (v.y < 0)
        v.x = -v.x, v.y = -v.y;

    return v;
}

Point getPerpendicularVector(const Point &v) {
    Point pv(-v.y, v.x);

    if (pv.y < 0)
        pv.x = -pv.x, pv.y = -pv.y;

    return pv;
}

Point rotate(const Point &P, double alfa) {
    double c = cos(alfa);
    double s = sin(alfa);

    return Point(c * P.x + s * P.y, -s * P.x + c * P.y);
}

bool check(double alfa) {
    vector<double> v;

    for (auto &P: vp)
        v.push_back(rotate(P, alfa).x);

    double massx = rotate(mass, alfa).x;

    sort(v.begin(), v.end());
    for (int i = 0, j = n - 1; i <= j; ++i, --j) {
        if (!equal(massx, (v[i] + v[j]) / 2))
            return 0;
    }

    return 1;
}

int main() {
    ios::sync_with_stdio(0);

    cin >> n;

    for (int i = 1; i <= n; ++i) {
        cin >> p[i].x >> p[i].y;
        mass = mass + p[i];
    }

    mass = mass / n;

    for (int i = 1; i <= n; ++i) {
        if (equal(p[i].x, mass.x) && equal(p[i].y, mass.y))
            erased[i] = 1;
        if (erased[i])
            continue;
        for (int j = i + 1; j <= n; ++j) {
            Point M = (p[i] + p[j]) / 2;

            if (equal(M.x, mass.x) && equal(M.y, mass.y))
                erased[i] = erased[j] = 1;
        }
    }

    for (int i = 1; i <= n; ++i) {
        if (!erased[i]) {
            vp.push_back(p[i]);
        }
    }

    if (vp.empty()) {
        cout << "-1\n";
        return 0;
    }

    n = (int) vp.size();

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            Point M = (vp[i] + vp[j]) / 2;
            Point v = getPerpendicularVector(getVector(mass, M));

            double alfa = atan2(v.y, v.x);
            assert(alfa < -PI + eps || (alfa > -eps && alfa < PI + eps));
            if (alfa < -PI + eps)
                alfa = PI;

            ++posLines[alfa];
        }
    }

    int ans = 0;
    for (auto &entry: posLines) {
        if (entry.second >= n / 2) {
            ans += check(entry.first);
        }
    }

    cout << ans << "\n";

    return 0;
}

