struct dsu{
	vector<int> p;
	vector<int> sz;
	dsu(int n) : p(n + 1), sz(n + 1, 1) {
		for (int i = 1; i < p.size(); ++i) {
			p[i] = i;
		}
	}


	int find_set(int v) {
		if (v == p[v]) {
			return v;
		}
		return p[v] = find_set(p[v]);
	}

	void union_set(int u, int v) {
		u = find_set(u);
		v = find_set(v);
		if (u == v) {
			return;
		}
		if (sz[u] < sz[v]) {
			swap(u, v);
		}
		sz[u] += sz[v];
		p[v] = u;
	}
};

