const int N = 2e5 + 7;
vector<int> g[N];
bool used[N];
int timer, tin[N], fup[N];
int cnt[N], dp[N];
bool inp[N];
int color[N];
int n, m, a, b;
void dfs(int v, int p = -1) {
    used[v] = true;
    tin[v] = fup[v] = timer++;
    cnt[v] = 1;
    for (size_t i=0; i<g[v].size(); ++i) {
        int to = g[v][i];
        if (to == p)  continue;
        if (color[to] != color[v]) {
            fup[v] = -1;
            continue;
        }   
        if (used[to])
            fup[v] = min (fup[v], tin[to]);
        else {
            dfs (to, v);
            cnt[v] += cnt[to];
            fup[v] = min (fup[v], fup[to]);
            if (fup[to] >= tin[v]) {
                dp[v] += cnt[to];
            }   
        }
    }
}
vector <int> path, cur;
void go(int u, int want) {
    cur.app(u);
    if (want == u) path = cur;
    used[u] = 1;
    for (int v : g[u]) 
        if (!used[v])
            go(v, want);
    cur.pop_back();
}

bool tc = 0;
void col(int u, int c) {
    used[u] = 1;
    if (color[u] != -1)
        tc = 1;
    color[u] = c;
    for (int v : g[u]) 
        if (!inp[v] && !used[v])
            col(v, c);
}     

