int timer;

set <int> pp;

void dfs(int v, int p = -1) {

	used[v] = 1;
	tin[v] = fup[v] = timer++;

	int children = 0;

	for (int to: e[v]) {

		if (to == p){
            continue;
		}
		if (used[to]) {
            fup[v] = min(fup[v], tin[to]);
		}
		else {
			dfs (to, v);
			fup[v] = min(fup[v], fup[to]);
			if (fup[to] >= tin[v] && p != -1) {
                pp.insert(v);
			}
			++children;
		}
	}

	if (p == -1 && children > 1) {
        pp.insert(v);
	}

    return;
}

vector <int> color;

void dfs_a(int v, int b) {

    used[v] = 1;

    for(int to: e[v]) {

        if(used[to] == 1 || to == b) {
            continue;
        }

        ++color[to];
        dfs_a(to, b);
    }

    return;
}

void dfs_b(int v, int a) {

    used[v] = 1;

    for(int to: e[v]) {

        if(used[to] == 1 || to == a) {
            continue;
        }

        color[to] += 2;
        dfs_b(to, a);
    }

    return;
}


