const ll inf = 1e18;

ll bin_pow(ll a, ll n) {
	if (n == 0)
		return 1;

	if (n % 2 == 0) {
		ll b = bin_pow(a, n / 2);
		return b * b;
	}
	else return a * bin_pow(a, n - 1);
}

vector<vector<ll>> g;
vector<bool> used;

ll flaga = false, flagb = false;
vector<ll> buf;

void dfs(ll v, ll a, ll b) {
	used[v] = true;
	buf.push_back(v);

	for (auto to : g[v]) {
		if (to == a)
			flaga = true;
		else if (to == b)
			flagb = true;
		else if (!used[to])
			dfs(to, a, b);
	}
}

