		for (ll i = 0; i < n; i++) {
			if (i != a && i != b && !used[i]) {
				flaga = false, flagb = false;
				buf.clear();

				dfs(i, a, b);

				if (flaga != flagb) {
					if (flaga) {
						ca.push_back(buf);
					}

					if (flagb) {
						cb.push_back(buf);
					}
				}
			}
		}

		ll mula = 0, mulb = 0;
		for (auto c : ca)
			mula += sz(c);
		for (auto c : cb)
			mulb += sz(c);

		ll ans = 0;
		for (auto c : ca) {
			ans += sz(c) * mulb;
		}
		for (auto c : cb) {
			ans += sz(c) * mula;
