ll bin_pow(ll val, ll kol) {
    if (kol == 0) {
        return 1;
    }
    if (kol == 1) {
        return val;
    }
    if (kol & 1) {
        return val * bin_pow(val, kol - 1);
    }
    return bin_pow(val * val, kol / 2);
}

vector<ll> par;
