	N = (n + m) << 1;
	mid = max(0, N - lim);
	memset(g, -1, sizeof g);
	work();
	ans_cnt = 0;
	REP(i, 0, N) if (s[i] == 'A') g[i] = 0; else if (s[i] == 'B') g[i] = 1;
	work();
	cout << ans_cnt << endl;
	return 0;
}

