			if(din[v]){
				fot[v]=sum-din[v]+1+b[0];
			}else {
				if(dot[v]==b[0])
					fot[v]=sum+1+b[1];
				else fot[v]=sum+1+b[0];
			}
			if(!w[v])fot[v]=0;
		}
	}else {
		for(i=0;i<G[u].SZ;i++){
			v=G[u][i];
