void dfs0(int x, int p=-1)
{
	sub[x] = 1;
	lld mx = 0;
	for(int &to : adj[x])
	{
		if(to==p) continue; 
		dfs0(to, x);
		sub[x] += sub[to];
		if(sub[to] == dp[to]) dp[x] += dp[to];
		else mx = max(mx, dp[to]);
	}
	if(a[x] >= v) dp[x]+=1+mx;
	else dp[x] = 0;
}

lld ans[N];
bool ok = 0;
lld dfs(int x, int p=-1, lld out = 0, lld out_sub = 0)
{
	int idx = -1;
	lld sec = 0, mx = 0, Ans = 0;
	for(int &to : adj[x])
	{
		if(to == p) continue;
		if(dp[to] == sub[to]) Ans += dp[to];
		else
		{
			if(dp[to] >= mx) sec = mx, mx = dp[to], idx = to;
			else if(dp[to] > sec) sec = dp[to];
		}
	}
	if(out_sub != out) 
	{
		if(out >= mx) sec = mx, mx = out, idx = -2;
		else if(out > sec) sec = out;
	}
	else Ans += out;
	if(a[x] >= v)
		ans[x] = Ans + mx+1;
	else ans[x] = 0;
	if(ans[x] >= k) ok = 1;
	for(int &to : adj[x])
	{
		if(to == p) continue;
		if(idx == to)
		{
			dfs(to, x, ((a[x]>=v)?(ans[x] - mx + sec):0), sub[x] + out_sub - sub[to]);
			continue;
		}
		if(sub[to] == dp[to]) dfs(to, x, ((a[x]>=v)?(ans[x] - dp[to]):0), sub[x] + out_sub - sub[to]);
		else dfs(to, x, (a[x]>=v)?ans[x]:0, sub[x] + out_sub - sub[to]);
	}
}


