inline void BombProcess()
{
    for (int i = 1 ; i <= n ; i ++) if (deg[i] == 1 && !forb[i]) Bomb.push(i);
    while (Bomb.size()){
        int first = Bomb.front(); Bomb.pop();
        deg[first] --;
        del[first] = true;
        int FIND = -1;
        for (auto u : g[first]){
            if (!del[u] && !forb[u]){
                FIND = u;
                break;
            }
        }
        if (FIND != -1){
            vl[FIND] += vl[first];
            deg[FIND] --;
            if (deg[FIND] == 1)
                Bomb.push(FIND);
        }
        ln = max(ln , vl[first]);
        vl[first] = 0;
    }
}
inline void dfs(int v,  int pr = -1){
    mark[v] = true;
    int f = 0 , s = 0;
    dp[v] = vl[v];
    for (auto u : g[v]){
        if (pr == u || forb[u]) continue;
        dfs(u , v);
        if (dp[u] > f) {s = f ; f = dp[u];}
        else s = max(s , dp[u]);
    }

    ln = max(ln , dp[v] + f + s);
    dp[v] += f;
}
inline bool can(int low){
    ln = 0;
    for (int i = 1 ; i <= n ; i ++){
        mark[i] = 0;
        deg[i] = g[i].size();
        dp[i] = 0;
        del[i] = 0  ;
        mark[i] = 0 ;
        vl[i] = 1;
        forb[i] = (a[i] < low);
    }
    BombProcess();
    for (int i = 1 ; i <= n ; i ++) {
        if (!mark[i] && !forb[i]) dfs(i , -1);
    }
    return ln >= k;
}
