	int all = 0,max1 = 0,max2 = 0;
	for(int i = 0;i < G[cur].size();i++){
		int u = G[cur][i];
		if(u == fa) continue;
		dfs2(u,cur);
		tag_cnt[cur] += tag_cnt[u];
		if(dp[u] == sz[u])
			all += dp[u];
		else if(dp[u] > max1){
			max2 = max1;
			max1 = dp[u];
		}
		else if(dp[u] > max2)
