using namespace std;
typedef long long int ll;
typedef pair<int, int> ii;
const int MAX = 201000;
int a[MAX];
int n, k;
int eu[MAX], ev[MAX];
bool cant[MAX];
int deg[MAX];
int val[MAX];
int down[MAX][2];
bool vis[MAX];
set<int> e[MAX];

void cut(int x) {
	set<ii> s;
	REP(i, n) if(a[i] >= x && e[i].size()) s.insert(ii(deg[i], i));
	while(s.size() && s.begin()->first == 1) {
		int u = s.begin()->second;
		deg[u]--;
		s.erase(s.begin());
		if(cant[u]) continue;
		int v = *e[u].begin();
		e[u].clear();
		e[v].erase(u);
		s.erase(ii(deg[v], v));
		--deg[v];
		s.insert(ii(deg[v], v));
		val[v] += val[u];
	}
}

int DFS(int u) {
	vis[u] = true;
	int res = 0;
	for(auto it : e[u]) {
		int v = it;
		if(vis[v]) continue;
		res = max(res, DFS(v));
		down[u][0] = max(down[u][0], down[v][1]);
		if(down[u][0] > down[u][1]) swap(down[u][0], down[u][1]);
	}
	down[u][0] += val[u];
	down[u][1] += val[u];
	return max(res, down[u][0] + down[u][1] - val[u]);
}

bool f(int x) {
	REP(i, n) {
		deg[i] = 0;
		if(a[i] >= x) val[i] = 1;
		else val[i] = 0;
		vis[i] = cant[i] = false;
		down[i][0] = down[i][1] = 0;
		e[i].clear();
	}
	REP(i, n - 1) {
		int u = eu[i];
		int v = ev[i];
		if(a[u] >= x && a[v] >= x) {
			e[u].insert(v);
			e[v].insert(u);
		}
		else {
			cant[u] = true;
			cant[v] = true;
		}
		++deg[u];
		++deg[v];
	}
	cut(x);
	REP(i, n) {
		if(!vis[i] && a[i] >= x) {
			if(DFS(i) >= k) return true;
		}
	}
	return false;
}

