	int l = 1, r = 0, ans;
	for (int i = 1; i <= n; i++)
		r = max(r, a[i] = read());
	for (int i = 1; i < n; i++)
		insert(read(), read());
	r ++;
	while (l <= r) {
		int mid = l + r >> 1;
		if (check(mid)) l = mid + 1;
		else ans = mid, r = mid - 1;
	}
	printf("%d\n", ans);
	return 0;
}
