	ll a[maxs][maxs];
	void clear(){memset(a,63,sizeof(a));}
	void init(){clear(); for (int i=1;i<=cnt;i++) a[i][i]=0;}
	matrix operator *(const matrix &x)const{
		matrix ret; ret.clear();
		for (int i=1;i<=cnt;i++)
			for (int j=1;j<=cnt;j++)
				for (int k=1;k<=cnt;k++)
					ret.a[i][j]=min(ret.a[i][j],a[i][k]+x.a[k][j]);
		return ret;
	}
	void build(){
		clear();
		for (int i=1;i<=cnt;i++){
			int mask=state[i]; if (~mask&1) a[i][inv[mask>>1]]=0;
			int x=__builtin_ctz(mask)+1; mask^=mask&-mask; mask>>=1;
			for (int j=x+1;j<=n+1;j++)
				if (~mask>>(j-2)&1) a[i][inv[1<<(j-2)|mask]]=v[j-x];
		}
