	matrix ret; ret.init();
	for (;k;k>>=1,a=a*a) if (k&1) ret=ret*a;
	return ret;
}

matrix brute(matrix a,int pos){
	matrix ret; ret.clear();
	for (int i=1;i<=cnt;i++){
		int mask=state[i]; if (~mask&1) ret.a[1][inv[mask>>1]]=min(ret.a[1][inv[mask>>1]],a.a[1][i]);
		int x=__builtin_ctz(mask)+1; mask^=mask&-mask,mask>>=1;
		for (int j=x+1;j<=n+1;j++)
			if (~mask>>(j-2)&1){
				ll res=a.a[1][i]+v[j-x]+h[pos+j-1];
				int tmp=1<<(j-2)|mask;
				ret.a[1][inv[tmp]]=min(ret.a[1][inv[tmp]],res);
			}
	}
	return ret;
}

