typedef ll _et;
struct Matrix
{
    ll size;
    vector< _et > f;
    Matrix(ll size, _et start_value = big) :size(size), f(size * size,start_value) {}
    Matrix(const Matrix& o)  { *this = o;};
    static vector<Matrix> cache;
    inline _et& m(ll a,ll b)
        {
            return f[a*size + b];
        }
    inline const _et& m(ll a,ll b) const
        {
            return f[a*size + b];
        }
    void print()
        {
            for(ll i =0; i<size; ++i)
            {

                for(ll j = 0;  j < size; ++j)
                {
                    std::cout << m(j,i) << " ";
                }
                std::cout << std::endl;
            }

        }

    void operator=(const Matrix& o)
        {
            this->size = o.size;
            this->f = o.f;
        }
    Matrix operator*(const Matrix& o) const
        {
            Matrix res(size);
            for(ll i =0; i<size; ++i)
            {

                for(ll j = 0;  j < size; ++j)
                {
                    for(ll k = 0; k < size; ++k)
                    {
                        res.m(i,j) = min( res.m(i,j), m(k, j) + o.m(i,k));
                    }
                }
            }
            return res;
        }
    Matrix get_pow(ll p)
        {

            Matrix res(*this);
            bool inited = false;
            for(ll i = 1;; ++i)
            {
                if(!p)
                {
                    break;
                }
                if (p % 2)
                {
                    if (!inited)
                    {
                        res = cache[i];
                        inited = true;
                    }
                    else
                    {
                        res = res * cache[i];
                    }

                }
                p /=2;
            }
            return res;
        }
    void fill_cache();
};

const ll xxxx = 40;
vector<Matrix > Matrix::cache;


void Matrix::fill_cache()
{
    cache = vector<Matrix> (xxxx, Matrix(size));
    Matrix res(*this);
    for(ll i = 1; i < xxxx; ++i)
    {
        cache[i] = res;
        res = res * res;
    }
}


vector<ll> standings;
