inline ll btc(ll x)
{
    ll res = 0;
    while(x)
    {
        if (x % 2) ++res;
        x /=2;
    }
    return res;
}


ll get_index(ll standing)
{
    for(ll i = 0; i<standings.size(); ++i)
    {
        if (standings[i] == standing) return i;
    }
    std::cerr << "WTF, INVALID STANDING " << standing << std::endl;
    return -1;
}

void CalcJmpMatrix(Matrix& jumpm, ll pos = -1)
{
    for(ll i = 0; i<standings.size(); ++i)
    {
        ll ss = standings[i];
        ll smallest = 1;
        while( (ss & smallest) == 0) smallest*=2;
        for(ll j = 0; j<jw.size();++j)
        {
            ll ns = ss;
            ns&= ~smallest;
            if (ns & (smallest << j) ) continue;
            ns |= smallest << j;
            if ((ns & 1) == 0 && ns < (1 << jw.size() ))
            {
                auto& x = jumpm.m(i,get_index(ns >> 1));
                ll aw = 0;
                if( pos >= 0 && j!=0)
                {
                    ll pos2 = pos;
                    ll sm2 = smallest >> 1;
                    while ( sm2)
                    {
                        ++pos2;
                        sm2 /= 2;
                    }
                    pos2 +=j;
                    if (magic_stones.find(pos2) != magic_stones.end())
                    {
                        aw = magic_stones[pos2];
                    }
                }
                x = min(x,(ll)jw[j] + aw);
            }
        }
    }
}

