vector<int> bitset;
mat a, o, p;
void pow2(mat &a) {
	for (int i : bitset)
		for (int j : bitset)
			p[i][j] = 1e18;
	for (int k : bitset) {
		for (int i : bitset)
			for (int j : bitset)
				p[i][j] = min(p[i][j], a[i][k] + a[k][j]);
	}
	swap(a, p);
}
void operator *=(vector<ll> &dp, mat &a) {
	for (int i : bitset)
		dpn[i] = 1e18;
	for (int i : bitset) {
		for (int j : bitset) {
			dpn[j] = min(dpn[j], dp[i] + a[i][j]);
		}
	}
	swap(dp, dpn);
}
void jump(ll to) {
	a = o;
	ll jump = to - curx;
	for (;jump;pow2(a), jump >>= 1) {
		if (jump & 1) dp *= a;
	}
	curx = to;
}
int main() {
