		if (it->first <= curx - k) {
			it++; continue;
		}
		if (it->first <= curx + 1) {
			for (int i : bitset)
				dpn[i] = 1e18;
			curx++;
			for (int cur : bitset) {
				int next = cur >> 1;
				if (cur & 1) {
					for (int i = 1, b = 1;i <= k;i++, b <<= 1) if (~next & b) {
						dpn[next | b] = min(dpn[next | b], dp[cur] + c[i] + (mp.count(curx - k + i) ? mp[curx - k + i] : 0));
