struct matrix {

	LL A[MAX_STATE][MAX_STATE];

	matrix() {
		for (int i = 1; i < MAX_STATE; i++) {
			for (int j = 1; j < MAX_STATE; j++)
				A[i][j] = inf;
			A[i][i] = 0;
		}
	}

	matrix operator * (matrix B) {
		matrix r;
		for (int i = 1; i <= cnt; i++)
			r.A[i][i] = inf;
		for (int i = 1; i <= cnt; i++)
			for (int j = 1; j <= cnt; j++)
				for (int k = 1; k <= cnt; k++)
					r.A[i][j] = min(r.A[i][j], A[i][k] + B.A[k][j]);
		return r;
	}

	matrix operator ^ (int y) {
		matrix x, r;
		for (int i = 1; i <= cnt; i++)
			for (int j = 1; j <= cnt; j++)
				x.A[i][j] = A[i][j];
		if (!y) return matrix();
		while (y) {
			if (y & 1) r = r * x;
			x = x * x; y >>= 1;
		}
		return r;
	}
};

int calc(int x) {
	int sum = 0;
	while (x) {
		if (x & 1) sum++;
		x >>= 1;
	}
	return sum;
}

