template<typename T>
class BIT {
    vector<T> a;
    using BinOp = function<T(T, T)>;
    BinOp bin_op;
    const T init;
public:
    explicit BIT(int n, BinOp op = [](T x, T y) { return x + y; }, T init = T{})
            : bin_op(op), init(init), a(n + 1, init) {}

    T prefix(int x) const {
        auto res = init;
        while (x) {
            res = bin_op(a[x], res);
            x -= x & -x;
        }
        return res;
    }

    void modify(int x, T v) {
        while (x < (int) a.size()) {
            a[x] = bin_op(a[x], v);
            x += x & -x;
        }
    }

    void clear() {
        fill(a.begin(), a.end(), init);
    }
};

vi get_prime(int n) {
    vi minp((ul) n + 1), p;
    for (int i = 2; i <= n; i++) {
        if (!minp[i]) {
            minp[i] = i;
            p.pb(i);
        }
        FOR(x, p) {
            if (x <= minp[i] && x * i <= n)
                minp[x * i] = x;
            else break;
        }
    }
    return p;
}

