// 仿照 ftiasch 的写法
template<typename T>
struct Mat {
    array<array<T, 2>, 2> m;

    array<T, 2> &operator[](int i) {
        return m[i];
    }

    const array<T, 2> &operator[](int i) const {
        return m[i];
    }

    Mat operator*(const Mat b) {
        Mat c;
        rng (i, 0, 2) {
            rng (j, 0, 2) {
                rng (k, 0, 2) {
                    c[i][j] += m[i][k] * b[k][j];
                }
            }
        }
        return c;
    }
};

struct Frac {
    int p, q;
    operator Mint() {
        assert(q != 0);
        return p / Mint(q);
    }
};

bool operator<(const Frac &a, const Frac &b) {
    return 1ll * a.p * b.q < 1ll * b.p * a.q;
}

