#if defined LOCAL && !defined DUIPAI
    ifstream in("in.txt");
    cin.rdbuf(in.rdbuf());
#endif
    int n;
    scan(n);
    if (n == 1) {
        println(0);
        return 0;
    }
    vi x(n), v(n);
    vector<Mint> p(n);
    Mint inv_100 = 1 / Mint(100);
    rng (i, 0, n) {
        scan(x[i], v[i], p[i]);
        p[i] *= inv_100;
    }

    vector<Mat<Mint>> allowed_collisions(n - 1);
    // 0: left, 1: right
    rng (i, 0, n - 1) {
        allowed_collisions[i][0][1] = p[i + 1];
    }

    // segment tree
    vector<Mat<Mint>> a(2 * (n - 1) - 1);
    auto get_prob = [to_right = p[0], &mat = a[get_id(0, n - 2)]]() {
        return to_right * (mat[1][0] + mat[1][1]) + (1 - to_right) * (mat[0][0] + mat[0][1]);
    };
    function<void(int l, int r)> build = [&](int l, int r) {
        if (l == r) {
            a[2 * l] = allowed_collisions[l];
            return;
        }
        int mid = get_mid(l, r);
        build(l, mid);
        build(mid + 1, r);
        a[get_id(l, r)] = a[get_id(l, mid)] * a[get_id(mid + 1, r)];
    };
    build(0, n - 2);
    function<void(int, int, int)> modify = [&](int l, int r, int k) {
        if (l == r) {
            a[2 * l] = allowed_collisions[k];
            return;
        }
        int mid = get_mid(l, r);
        if (k <= mid) {
            modify(l, mid, k);
        } else {
            modify(mid + 1, r, k);
        }
        a[get_id(l, r)] = a[get_id(l, mid)] * a[get_id(mid + 1, r)];
    };
    vector<pair<Frac, int>> events(3 * (n - 1));

    rng (i, 0, n - 1) {
        int d = x[i + 1] - x[i];
        events[i * 3] = {{d, v[i + 1] + v[i]}, i << 2 | 1};
        events[i * 3 + 1] = {
                v[i] < v[i + 1] ? Frac{d, v[i + 1] - v[i]} : Frac{1, 0}, i << 2 | 0};
        events[i * 3 + 2] = {
                v[i] > v[i + 1] ? Frac{d, v[i] - v[i + 1]} : Frac{1, 0}, i << 2 | 3};
    }

    sort(all(events));

    Mint prev_prob = get_prob(), ans = 0;

    FOR (event, reverse(events)) {
        int i = event.second >> 2;
        int dir1 = get_bit(event.second, 0);
        int dir2 = get_bit(event.second, 1);
        // allow this collision of the i-th and i+1-t proton to happen
        allowed_collisions[i][dir1][dir2] = dir2 ? p[i + 1] : 1 - p[i + 1];
        modify(0, n - 2, i);
        Mint prob = get_prob();
        if (event.first.q != 0) {
            ans += (prob - prev_prob) * event.first;
        }
        prev_prob = prob;
    }

    println(ans);

#if defined LOCAL && !defined DUIPAI
    cout << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif
    return 0;
}

