struct matrix // 右1左0
{
	int A[2][2];

	inline matrix () { memset (A, 0, sizeof A); }

	inline int* operator [] (const int &x) { return A[x]; }

	inline matrix operator * (const matrix &rhs) const
	{
		matrix now;
		for (int i = 0; i < 2; ++i)
			for (int k = 0; k < 2; ++k) if (A[i][k])
				for (int j = 0; j < 2; ++j)
					ADD (now.A[i][j], (LL) A[i][k] * rhs.A[k][j] % MOD);
		return now;
