    }
    Mat friend operator *(Mat x1,Mat x2)
    {
        Mat x3;
        x3.num[0][0]=(x1.num[0][0]*x2.num[0][0]+x1.num[0][1]*x2.num[1][0])%mz;
        x3.num[0][1]=(x1.num[0][0]*x2.num[0][1]+x1.num[0][1]*x2.num[1][1])%mz;
        x3.num[1][0]=(x1.num[1][0]*x2.num[0][0]+x1.num[1][1]*x2.num[1][0])%mz;
        x3.num[1][1]=(x1.num[1][0]*x2.num[0][1]+x1.num[1][1]*x2.num[1][1])%mz;
        return x3;
    }
}mp;
struct Point
{
