long long ksm(long long x)
{
    long long z=1,y=mz-2;
    while(y)
    {
        if(y%2)
            z=(z*x)%mz;
        y>>=1;
        x=(x*x)%mz;
    }
    return z;
}
void build(int x,int l,int r)
{
	tre[x].l=l;
	tre[x].r=r;
	tre[x].mid=(l+r)/2;
	if(l==r)
	{
		tre[x].m.num[0][0]=tre[x].m.num[0][1]=(1+mz-p[l])%mz;
		tre[x].m.num[1][0]=tre[x].m.num[1][1]=p[l];
	}
	else
	{
		build(x*2,l,tre[x].mid);
		build(x*2+1,tre[x].mid+1,r);
		tre[x].m=tre[x*2].m*tre[x*2+1].m;
	}
}
Mat ask(int x,int l,int r)
{
	if(tre[x].l==l && r==tre[x].r)
		return tre[x].m;
	else if(r<=tre[x].mid)
		return ask(x*2,l,r);
	else if(l>tre[x].mid)
		return ask(x*2+1,l,r);
	return ask(x*2,l,tre[x].mid)*ask(x*2+1,tre[x].mid+1,r);
}
void change(int x,int y,int k)
{
	if(tre[x].l==tre[x].r)
	{
		if(k==1)
			tre[x].m.num[1][0]=0;
		if(k==2)
			tre[x].m.num[0][0]=0;
		if(k==3)
			tre[x].m.num[1][1]=0;
	}
	else
	{
		if(y<=tre[x].mid)
			change(x*2,y,k);
		else
			change(x*2+1,y,k);
		tre[x].m=tre[x*2].m*tre[x*2+1].m;
	}
}

